window.__D("text/pelach-harimon/c005",{"p":[[4801940185,"שלא בדרך השתלשלות רק בדרך צמצום ודילוג המהות, משא\"כ הכלים דאצי' אעפ\"י שאינם מהות נברא מ\"מ הם מקור לנברא וההמשכה מן הכלים דאצי' לבי\"ע הוא בדרך השתלשלות כו' [... ומה שמבואר במ\"א שגם בי\"ע נמשך מאצי' בבחי' יש מאין<sup data-n=\"3835\">7</sup> שלא בדרך השתלשלות היינו מהות עצם הנברא נמשך מן הכלים דאצי' בדילוג הערך כי אין ערוך בע\"ג לבבע\"ג, כי אעפ\"י שהכלים דאצי' הם מקור להשפעה מיוחדת מ\"מ יכול להשפיע בהשפעה פרטי' בלי שיעור כמו כלי החכמה אעפ\"י שהוא מקור מיוחד לחכמה בלבד מ\"מ יוכל להשפיע חכמה בלי שיעור ולכן המשכת עצם הנברא מבחי' הכלים דאצי' שהם בלתי מוגבלים הוא בדרך דילוג יש מאין, אבל כאן מדבר בבחי' השפעה פנימי' היינו מה שנמשך בחי' אצי' ממש בבי\"ע כמובן מהמשלים שיתבארו והשפעה זאת דאצי' עצמו המאיר בבי\"ע הוא נמשך בדרך השתלשלות מעצמות הכלים דאצי' כו' וד\"ל].\n<b>ויובן</b> ענין הריחוק ערך דכלים דאצי' לגבי השפע הנמשך מהם בבי\"ע יובן ע\"ד המבואר במ\"א במה שא' אברהם ואנכי עפר ואפר<sup data-n=\"3836\">8</sup> שבחי' אהבת אברהם אוהבי<sup data-n=\"3837\">9</sup> אעפ\"י שהוא למעלה מכל מיני סוג אהבה הנמצא אפי' בנשמות ומכש\"כ במלאכים כי האבות הן המרכבה<sup data-n=\"3838\">10</sup> עד שהאיר בחי' אצי' ממש בנשמה שבגופו [כמבואר בביאור דואני נתתי<sup data-n=\"3839\">11</sup> כו'] מ\"מ אין ערך להארת האצי' שהאיר בגופו לגבי מקור ההארה זאת כמ\"ש כלולה בבחי' החסד דאצי' כמו שאין ערך לאפר הנשאר אחר שריפת העץ לגבי מציאותו הרוחני כמ\"ש כלול בעץ עצמו קודם שריפתו [שאז הי' מורכב עם ג' יסודות הרוחני' דאויר מים אש ולכן הי' הוא ג\"כ רוחני בתכלית]. ועוד יובן משארז\"ל אין לך עשב<sup data-n=\"3840\">12</sup> מלמטה שאין לו מזל מלמעלה המכה ואומר לו גדל שבוודאי אין ערך למתיקות התפוח לגבי מקור המתיקות כמו שהיא כלולה במזל הרוחני, כי אפי' המתיקות שבשכל שהוא ג\"כ בבחי' גילוי טעם ועונג אינו בערך הטעם ומתיקות שבתפוח שהוא טעם גשמי ומכש\"כ מקור המתיקות כמ\"ש כלול במזל הרוחני שאינו בגדר גילוי טעם כלל, אך מ\"מ הוא מקור לבחי' גילוי המתיקות שבתפוח גשמי, כן עד\"ז הוא הבדלת הערך דבחי' הכלים דאצי' לגבי השפע הנמשך מהם בבי\"ע הוא עכ\"פ נרגש במציאות דבר מה [כמובן ממשל דאפר הנשאר שנגלה במציאות דבר מה וכן המתיקות שבתפוח אעפ\"י שהוא טעם רוחני מ\"מ הוא מציאות נרגש כו', משא\"כ יסוד העפר הכלול בעץ לא נרגש מציאותו כלל וכן מקור המתיקות במזל הרוחני לא נרגש מציאותו כלל כו'], משא\"כ הכלים דאצי' עצמם אינם מורגשים למציאות בפ\"ע כלל רק כלולים בתכלית באא\"ס השופע בהם",[["3835","7","<b>בי\"ע. . יש מאין</b>: ראה תו\"א וירא יד, ב ואילך."],["3836","8","<b>ואנכי עפר ואפר</b>: וירא יח, כז. ראה אגה\"ק סט\"ו."],["3837","9","<b>אברהם אוהבי</b>: ישעי' מא, ח."],["3838","10","<b>האבות הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. תו\"ח נח מט, ד ובהערה 42. משפטים ח\"ב ש, ג. סה\"מ תרכ\"ט ע' רלח. וש\"נ."],["3839","11","<b>משארז\"ל </b>[ממשארז\"ל ]<b> שהאיר בחי' אצי'. . בביאור דואני נתתי</b>: פלח הרמון ויחי קכא, ב."],["3840","12","<b>אין לך עשב</b>: ראה ב\"ר פ\"י, ו. מאמרי אדה\"א דברים ח\"ג ע' תתמח. וש\"נ. שם ע' תתעו ואילך. שער האמונה ע' נג. אוה\"ת וארא כרך ח ע' ב'תתפג."]]],[4801940242,"ואעפ\"כ הם מקור להשפיע בבי\"ע ולכן נק' בשם טהרה ע\"ש שאא\"ס מאיר בהם בתוקף הבהירות ובלי צמצום והסתר כלל כו' כנ\"ל בב' פי' דטהורה<sup data-n=\"3841\">13</sup> כו', אבל בחי' קדושה הוא בחי' האור בעצמו קודם שנמשך ונתלבש בהם בבחי' הכלים שהוא קדוש ומובדל לגמרי שאינו בגדר מקור ולא מקור למקור להשפעה מיוחדת בפרט כי הוא בחי' א\"ס ממש רק ע\"י צמצום שהוא בחי' דילוג הערך נמשך מן האור בחי' הכלי כנ\"ל. ולכן נק' בשם קדושה כו' וד\"ל.\n<b>ובזה</b> יובן ענין נשמה שנתת בי טהורה כי עצמות הנשמה הוא בחי' אלקות הנמשך מן הכלים דאצי' או מפנימי' הכלים דבי\"ע שהם בחי' אצי' שבבי\"ע ולכן גם הנשמה היא בבחי' ביטול בתכלית והביטול שבה הוא בתכלית השלימות בלי צמצום והסתר כלל ולכן נק' ג\"כ בשם טהורה כמו הכלים דאצי' שנק' בשם טהרה כו' [... וענין זה הוא בין בנשמות דאצי' הנמשכים מכלים דאצי' כמו נשמות האבות ובין בנשמות דבי\"ע שהמשכתן הוא מפנימי' הכלים שהם בחי' אצי' שבבי\"ע שזהו בחי' ל' כלים דמל' דאצי'<sup data-n=\"3842\">14</sup> הנעשים נשמה לבי\"ע שהם בחי' אלקות ממש כמבואר בכהאריז\"ל ועיין באגה\"ק במאמר איהו וחיוהי<sup data-n=\"3843\">15</sup> כו' ולכן גם הנשמות הנמשכים מהם הם ג\"כ בחי' חלק אלוה ממש וכמו נשמות השבטים שהם בחי' אצי' שבבי\"ע<sup data-n=\"3844\">16</sup> כו', רק אעפ\"כ יש הפרש בין הנשמות להכלים עצמן שהנשמות הן בבחי' ביטול בתכלית באא\"ס השופע בהם דרך הכלים אבל לא בבחי' יחוד לכן אפי' הנשמות דאצי' אין בהם כח לברוא יש מאין משא\"כ בחי' הכלים אפי' בחי' ל' כלים המתפשטים ממל' דאצי' בבחי' נשמה לבי\"ע הם בבחי' יחוד בתכלית עם אא\"ס השופע בהם, ולכן בכחם לברוא יש מאין. וההפרש בין בחי' ביטול לבחי' יחוד יובן לפע\"ד ע\"ד ההפרש שבין התכללות אותיות המחשבה באור וחיות כח השכל וכח המחשבה השופע בהם בבחי' מקיף ופנימי בדרך יחוד המקיף עם הפנימי כו' שזהו משל לבחי' ביטול והתכללות הנשמה באא\"ס השופע בה שאינו אלא בחי' ביטול, ובין התכללות יסוד העפר בעץ קודם שריפתו והתכללות המתיקות במזל שזהו משל לבחי' ביטול הכלים באא\"ס השופע בהם שנק' בשם יחוד כו' וד\"ל. ..], ומש\"א אתה בראת כו' היינו שירדה ונתלבשה בחיצוני' הכלים די\"ס דבי\"ע עד שנעשית בחי' בריאה יש מאין כמו המלאכים כו' [ואדרבה התלבשות הנשמה בבחי' חיצוני' יותר מן המלאכים כי המלאכים שרשם יחוד רוחני והנשמות הם בחי' יחוד גופני<sup data-n=\"3845\">17</sup> כו' וד\"ל] וזהו ענין ירידת הנשמה משרשה בבחי' פנימי' הכלים דבי\"ע שהוא בחי' אצי' שבבי\"ע או בבחי' הכלים דאצי' וירדה ונתלבשה בחיצוני' הכלים דבי\"ע וירדה ממדריגה למדריגה עד שנתלבשה בגוף החומרי כו' שזהו מש\"א ואתה נפחת בי כו' וד\"ל.",[["3841","13","<b>כנ\"ל בב' פי' דטהורה</b>: לעיל בריש המאמר ע' שמה."],["3842","14","<b>ל' כלים דמל' דאצי'</b>: ראה ע\"ח שער השמות שער מ\"ד, פ\"א-ב. לקמן מאמר ד\"ה את שבתותי תרי\"ב ובהערה 26."],["3843","15","<b>באגה\"ק במאמר איהו וחיוהי</b>: ס\"כ (קל, א)."],["3844","16","<b>נשמות השבטים. . אצי' שבבי\"ע</b>: ראה גם פלח הרמון שבהערה 11. תו\"א ויחי קג, סע\"א. תו\"ח ויחי רמב, ד."],["3845","17","<b>המלאכים שרשם. . והנשמות. . גופני</b>: ראה ע\"ח שער מ\"ן ומ\"ד של\"ח, דרוש ד. שער פני' וחי' ש\"מ, דרוש י."]]],[4801940295,"<b>ומעתה</b> י\"ל ענין העלי' שמחמת הירידה כו', ומתחילה י\"ל דלפי הנ\"ל דקדושה הוא באור וטהרה הוא בבחי' הכלים א\"כ למה נא' טהרה בלוים<sup data-n=\"3846\">18</sup> וקדושה בכהנים<sup data-n=\"3847\">19</sup> דהלא גם הכהנים הם בבחי' קו הימין דנש\"י ומבואר למעלה דשרש הנשמות הוא בבחי' הכלים ואיך נאמר בכהנים בחי' קדושה כו'. אך הענין יובן בהקדים ענין איהו וחיוהי חד איהו וגרמוהי חד<sup data-n=\"3848\">20</sup> שיש הפרש בין יחוד אא\"ס בחכמה שזהו בחי' איהו וחיוהי כי חיוהי נק' החכמה כמאמר והחכמה תחי'<sup data-n=\"3849\">21</sup> ובין יחוד אא\"ס בבחי' הבינה שזהו בחי' איהו וגרמוהי כו', כי הנה הבינה נק' בחי' יש<sup data-n=\"3850\">22</sup> הגם שהוא בחי' בלי מה כנ\"ל מ\"מ להיותה מקור להשפעת העולמות דבי\"ע לכן נק' בשם יש וכידוע דהתחלת שרש ומקור הנבראים הוא מבחי' בינה דאצי' כי אימא עילאה מקננא בכורסי'<sup data-n=\"3851\">23</sup> שית סטרין<sup data-n=\"3852\">24</sup> כו' ולכן אא\"ס המתלבש בה הוא בא בבחי' צמצום בשביל התהוות מקור פרטי להשפעה מיוחדת בפרט [... כי כל העולמות אינם אלא פרט א' מעצמות המאציל כענין ויצא כברק<sup data-n=\"3853\">25</sup> כו' וביו\"ד נברא<sup data-n=\"3854\">26</sup> כו'], משא\"כ בחי' החכמה הגם שהיא ג\"כ בחי' כלי מ\"מ מאחר שהיא בחי' כח מ\"ה<sup data-n=\"3855\">27</sup> שהיא בחי' ביטול ונק' בחי' אין<sup data-n=\"3856\">28</sup> ולכן שורה בה כללות האא\"ס כמ\"ש בעצמותו שאינו בחי' מקור להשפעה כלל כידוע דעצמות אא\"ס לאו מכל אינון מדות כלל וכל יכול, וכח ואור הזה הוא מתלבש בחכמה [וכידוע בלק\"א בשם הה\"מ נ\"ע<sup data-n=\"3857\">29</sup> שחכמה הוא בחי' אמת ולכן מתלבש בה בחי' אחד האמת אשר הוא לבדו הוא ואין בלתו כו'], ובזה יובן מה שנאמר בחי' טהרה בלוים ובחי' קדושה בכהנים כי עבודת הלוים הוא במורגש לארמא קלא לכן העלאת מ\"ן שלהם הוא בבחי' בינה ולכן גם ההמשכה אינו רק מבחי' בינה שנק' טהרה כנ\"ל משא\"כ עבודת הכהנים הוא בחשאי<sup data-n=\"3858\">30</sup> ובחי' ביטול לכן עבודתם מגיע עד בחי' החכמה ששם שורה עצמות אא\"ס דלאו מכל אינון מדות כלל ולכן גם ההמשכה משם ולכן נאמר בהם וקדשתו<sup data-n=\"3859\">31</sup> כו'.\n<b>ומעתה</b> יובן ענין סוכ\"ע וממכ\"ע, כי בחי' ממכ\"ע הוא אור המתלבש בבחי' בינה דאצי' שהוא אור הבא בדרך התלבשות בבי\"ע כי אימא עילאה מקננא בכורסי' וזהו בחי' עלמין סתימין [בחי' נשמות שמקורם בבינה בחי' מחשבתו ית'",[["3846","18","<b>טהרה בלוים</b>: בהעלותך ח, ז."],["3847","19","<b>וקדושה בכהנים</b>: אמור כא, ח."],["3848","20","<b>איהו וחיוהי. . וגרמוהי חד</b>: ראה ת\"ז בהקדמה ג, ב."],["3849","21","<b>והחכמה תחי'</b>: קהלת ז, יב [ושם: החכמה — ראה גם לעיל ע' קמה הערה 52]."],["3850","22","<b>הבינה נק' בחי' יש</b>: ראה גם לעיל ס\"ע ו. וש\"נ."],["3851","23","<b>אימא עילאה מקננא בכורסי'</b>: ת\"ז ת\"ו כג, א. ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["3852","24","<b>שית סטרין</b>: ראה ת\"ז שם."],["3853","25","<b>ויצא כברק</b>: זכרי' ט, יד."],["3854","26","<b>וביו\"ד נברא</b>: מנחות כט, ב."],["3855","27","<b>החכמה. . כח מ\"ה</b>: זהר רע\"מ צו כח, א. לד, א."],["3856","28","<b>החכמה. . בחי' אין</b>: ראה גם לעיל ס\"ע ו. וש\"נ."],["3857","29","<b>בלק\"א בשם הה\"מ נ\"ע</b>: פל\"ה בהגהה."],["3858","30","<b>עבודת הלוים. . לארמא קלא. . הכהנים הוא בחשאי</b>: ראה זהר בשלח נז, א. שמיני לט, א. אמור פח, ב. קרח קעז, ב. סה\"מ תרכ\"ט ע' רז ואילך. וש\"נ."],["3859","31","<b>וקדשתו</b>: אמור כא, ח."]]],[4801940345,"כמ\"ש ונשמת שדי תבינם<sup data-n=\"3860\">32</sup> כו'] ושית סיטרין מקנני' ביצירה ואימא תתאה מקננא באופן<sup data-n=\"3861\">33</sup> שזהו בחי' עלמין דאתגליין [בחי' מלאכים וחיצוני' העולמות שמקורם דבר ה' כנ\"ל<sup data-n=\"3862\">34</sup>, וכ\"ז הוא בחי' ממכ\"ע אבל בחי' סוכ\"ע הוא בחי' אא\"ס המלובש בחכ\"ע ששם שורה עצמות אא\"ס דלאו מכל אינון מדות כלל וזהו בחי' קדושה שהוא בחי' אור שאינו בא בדרך התלבשות כלל לכן נמצא למטה כמו למעלה בהשוואה כו', [... אך מ\"מ נק' סוכ\"ע שהוא בגדר עלמין כמשי\"ת להיותו מלובש עכ\"פ בכלי החכמה אעפ\"י שאינו בחי' כלי גמורה רק בחי' מה ואין כו'].\n<b>והנה</b> כמו שחכמה ובינה הוא בחי' סוכ\"ע וממכ\"ע בכללות ד' העולמות דאבי\"ע כן מאצי' לבי\"ע יש ג\"כ בחי' סובב וממלא כי בחי' עצם המל' דאצי' הוא ג\"כ רק הארה בבחי' מקיף כנ\"ל לכן אור המל' עצמה ג\"כ קדוש ומובדל מבחי' הנבראים ולכן נק' ג\"כ בשם קדש רק שהוא בחי' קדש תתאה ומה שממנה נמשך ג\"כ התהוות וחיות כל הנבראים [... כנ\"ל בתורה דאין המשל דומה לנמשל כו'] זהו בחי' המתלבשת בנבראים נק' בחי' ממכ\"ע והיינו בחי' ל' כלים דמל' דאצי' הנעשים נשמה לבי\"ע י' כלים הפנימי' בבריאה התחתונים<sup data-n=\"3863\">35</sup> ביצי' כו' זהו בחי' ממכ\"ע אבל עצם אור המל' דאצי' הוא למעלה מגדר התלבשות וזהו בחי' סוכ\"ע הנק' קדש אך יש ג\"כ בחי' קדוש שזהו ענין ירידת הסובב מגבוה לנמוך להתלבש בבחי' ממכ\"ע [... כנ\"ל בתורה שממנו עיקר ההתהוות [זהו בחי' עתיק שבכל עולם שנמשך מבחי' מל' שבעולם העליון ממנו שבה מלובש אור המל' דאצי' [כי כו' וד\"ל] זהו בחי' קדוש בוא\"ו<sup data-n=\"3864\">36</sup>, ולכן יש ג\"פ קדוש כנגד ג' עולמות דבי\"ע<sup data-n=\"3865\">37</sup> כו', וכן למעלה באצי' יש ג' בחי' אלו דממכ\"ע וסוכ\"ע ובסובב גופא יש בחי' קדש ובחי' קדוש, כי בחי' ממכ\"ע הוא בחי' אא\"ס המלובש בבינה ומדות ומל' דאצי' שזהו בחי' בי\"ע שבאצי'<sup data-n=\"3866\">38</sup> ובחי' סוכ\"ע הוא בחי' אא\"ס המלובש בחכ\"ע עצמה שנק' קדש כנ\"ל שהוא בחי' אצי' שבאצי' והנה מבואר בכהאריז\"ל שבחכמה עצמה הנק' מקיף דחי' יש בחי' נרנח\"י<sup data-n=\"3867\">39</sup> ובחי' נר\"נ שבה מתפשטים בבחי' הבינה ומדות ומל' דאצי' והארתם בהם הוא בבחי' מקיף כו' וזהו בחי' ג\"פ קדוש בוא\"ו שהוא ענין ג' מקיפים פרטים הנמשך מחכ\"ע לכל הספירות משא\"כ חי' יחידה דחכ\"ע הוא בחי' קדש בלא וא\"ו עצמות הסובב כו' וד\"ל.\n<b>ומעתה</b> י\"ל ענין העלי' של הנשמה שנעשה ע\"י המצות דהנה המצות נק' מצות המלך<sup data-n=\"3868\">40</sup> שנעשים בקבלת עומ\"ש דוקא כנ\"ל ועי\"ז מתברר החיות המלובש בדבר הגשמי של המצוה ונכלל בבחי' המל' הנק' קדש תתאה ועי\"ז פועל",[["3860","32","<b>ונשמת שדי תבינם</b>: איוב לב, ח."],["3861","33","<b>ואימא תתאה מקננא באופן</b>: ת\"ז ת\"ו כג, א."],["3862","34","<b>כנ\"ל</b>: אוצ\"ל: כנ\"ל]."],["3863","35","<b>התחתונים</b>: אוצ\"ל: האמצעים."],["3864","36","<b>קדוש בוא\"ו</b>: ראה גם לקמן מאמר ד\"ה את שבתותי תשמרו תרי\"ב ובהערה 57."],["3865","37","<b>ג\"פ קדוש. . דבי\"ע</b>: ראה גם לעיל בהמאמר ובהערה 53."],["3866","38","<b>בי\"ע שבאצי'</b>: ראה ע\"ח שער כללות אבי\"ע שמ\"ב, פ\"ד. ראה גם לעיל ע' כז. ע' קפה."],["3867","39","<b>בכהאריז\"ל שבחכמה. . נרנח\"י</b>: ראה לקו\"ת כאן (ע, ד) שמציין לע\"ח שמ\"א פ\"ז. ולפנינו הוא שער דרושי אבי\"ע שמ\"ב, פ\"ה."],["3868","40","<b>המצות נק' מצות המלך</b>: נסמן לעיל בהמאמר הערה 60."]]],[4801940392,"עליית המל' לשרשה שהוא בחי' החכמה הנ\"ל הנק' קדש עילאה ועוד למעלה יותר בבחי' הכתר, כי הנה במה שאנו אומרים בב\"ש יחיד חי העולמים מלך ובישתבח מלך יחיד חי העולמים כי הנה בחי' יחיד הוא בחי' הכתר וחכמה שהוא בחי' סוכ\"ע הנק' קדש שמובדל בערך מכל ההשתלשלות עד שאין כל ההשתלשלות תופסים מקום כלל לגבי' כטפה בים<sup data-n=\"3869\">41</sup> אוקינוס ויותר מזה כי לא נערוך אליו קדושתו<sup data-n=\"3870\">42</sup> ולכן נק' בחי' יחיד, כי ההפרש בין יחיד לאחד<sup data-n=\"3871\">43</sup> בלה\"ק כי אחד הוא התאחדות דברים נפרדים משא\"כ יחיד הוא בעצם ואין שני לו, כך למעלה בחי' אחד הוא כאשר נתצמצם להיות בחי' מקור כללי להשתלשלות שכולל כל הריבוי והתחלקות שבהשתלשלות כאחד [... ויתכן זה במח' הכללי' דבינה כו'] אבל בחי' סוכ\"ע שהוא קדוש ומובדל לגמרי מכל ההשתלשלות אין שייך לומר בחי' אחד רק בחי' יחיד, וזהו יחיד חי העולמים שמחמת בחי' יחיד נמשך בחי' חי העולמים ונתלבש בבחי' מלך שהוא בחי' המל' דאצי' [... וכנ\"ל בענין נפתלי אילה שלוחה<sup data-n=\"3872\">44</sup> שפי' ואתה מחי'<sup data-n=\"3873\">45</sup> ו' אתה נהו\"ע שהוא בחי' מקור חיות העולמות די\"ס דאצי' הנק' אחד ונהו\"ת שהוא בחי' המל' דאצי' כלילן כחדא<sup data-n=\"3874\">46</sup> וסיבת השפלת ירידת החיות בבחי' האותיות דמל' דאצי' הוא מבחי' רצה\"ע הסוכ\"ע וכן מבחי' החכמה נמצא הדיבור שהוא בחי' המל' כו'], א\"כ שרש מדת המלוכה הוא בבחי' יחיד וזהו נתב\"ס אבל אח\"כ סוב\"ת<sup data-n=\"3875\">47</sup> שזהו ע\"י פסוד\"ז שהוא בחי' שבחו של מקום מרוממים מדת המל' שתתעלה לשרשה בבחי' חכמה ורצה\"ע וזהו מלך יחיד שהמל' מתעלה לבחי' יחיד כו' וד\"ל.\n<b>ועד\"ז</b> יובן בענין עליית המל' ע\"י המצות שע\"י הבירורים שמתבררים ע\"י המצות ונכללים במדת המל' עי\"ז מתעלית המל' לשרשה ועי\"ז מתעלים גם הנשמות עמה בקדש העליון, וזהו שרש ענין זרקא מקף כו' הולך סגולתא<sup data-n=\"3876\">48</sup> כו' כי זרקא הוא בחי' מל' שנק' זרקא<sup data-n=\"3877\">49</sup> כמבואר בת\"ז דאיהו אבנא בקירטא<sup data-n=\"3878\">50</sup> שזהו אותיות התפילה והתורה שעי\"ז מתרומם בחי' המל' כי אותיות התורה נק' ג\"כ ואותיות התפילה<sup data-n=\"3879\">51</sup> וזהו ג\"כ שרש ענין ואני כברוש רענן<sup data-n=\"3880\">52</sup> כו' וענין וצדקה תרומם גוי<sup data-n=\"3881\">53</sup> כנ\"ל",[["3869","41","<b>כטפה בים</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' קסד. סהמ\"צ להצ\"צ ע' צא ואילך. מאמרי אדה\"א נ\"ך ע' שלח ואילך."],["3870","42","<b>לא נערוך אליו קדושתו</b>: פיוט יגדל. ראה תו\"א בשלח סב, ג. לקו\"ת (מטות פא, ב) יו\"כ ע, א. תו\"ח בשלח ח\"א קסג, א. וש\"נ."],["3871","43","<b>ההפרש בין יחיד לאחד</b>: ראה גם לעיל ע' קצג ובהערה 6."],["3872","44","<b>נפתלי אילה שלוחה</b>: ויחי מט, כא. ראה פלח הרמון ויחי קלה, א ואילך (וראה לקמן ברשימת הכת\"י להמאמר, שמאמר זה הוא כנראה משנת תר\"א)."],["3873","45","<b>ואתה מחי'</b>: נחמי' ט, ו."],["3874","46","<b>נהו\"ע. . ונהו\"ת. . כלילן כחדא</b>: זהר תצוה קעט, ב."],["3875","47","<b>נתב\"ס. . סוב\"ת</b>: ראה ס\"י פ\"א, מ\"ז."],["3876","48","<b>זרקא. . סגולתא</b>: ראה זהר בראשית כד, א. ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תסט."],["3877","49","<b>מל' שנק' זרקא</b>: ראה מק\"מ לזהר שם (כד, א). אוה\"ת ח\"ש כרך ד ע' תשפג."],["3878","50","<b>בת\"ז דאיהו אבנא בקירטא</b>: ראה גם לקו\"ת כאן (ע, ד). לעיל בהמאמר ובהערה 72."],["3879","51","<b>כי אותיות. . התפלה</b>: בלקו\"ת כאן (ע, ד): שאותיות התפלה נקראו אבנים."],["3880","52","<b>ואני כברוש רענן</b>: נסמן לעיל בהמאמר הערה 76."],["3881","53","<b>וצדקה תרומם גוי</b>: משלי יד, לד [ושם: צדקה — נסמן לעיל בהמאמר הערה 88]."]]],[4801940436,"בתו' כו' וד\"ל. והנה עיקר עליית המל' וגם הנשמות עמה היא בשבת דווקא שאז עולים לעצמו' הקדש כו' שהוא עצמו' הסובב כנ\"ל באריכות בתו' כו'. והנה כ\"ז כשלא פגם בקדש העליון אבל כשעשה חסרון בהמשכת בחי' קדש העליון ע\"י ביטול מ\"ע או ע\"י ל\"ת שהלביש נפשו בלבושים צואים ח\"ו כמ\"ש ואת נפש אויביך יקלענה<sup data-n=\"3882\">54</sup> כו' אזי אין תקנה רק ע\"י כניסת כה\"ג להיכל ק\"ק כו'. וביאור הענין הנה מבואר בזהר דאית מלך לתתא ואית מלך לעילא<sup data-n=\"3883\">55</sup> דאיהו רזא דקה\"ק כי הנה מל' מכ\"ע<sup data-n=\"3884\">56</sup> כתיב ובחי' מלכ\"ע הוא בחי' המל' דאצי' סודכ\"ר<sup data-n=\"3885\">57</sup> דאצי' שהוא מקור עולמות הנבראים וזהו מלך לתתא, אבל מלך לעילא הוא בחי' מל' דא\"ס שלמעלה מן החכמה ורצון וממנה נעשה בחי' מקור לנאצלים ואפי' לבחי' רצון וחכמה הנק' קדש ולכן נק' קדש הקדשים שזהו בחי' קדש עליון שממנו בחי' מקור לכל מיני קדש שבהשתלשלות וכמ\"ש והחכמה מאין תמצא<sup data-n=\"3886\">58</sup> כו', וזהו ג\"כ והבדילה הפרוכת<sup data-n=\"3887\">59</sup> בין הקדש ובין קדש הקדשים כמו שלמטה פרסא מפסיק בין אצי' שהוא בחי' אלקות ובין בחי' הנבראים<sup data-n=\"3888\">60</sup> מצד שאין ערך להם לבחי' אלקות כן אין ערך לבחי' קדש דסוכ\"ע לגבי קה\"ק ולכן צ\"ל פרסא מפסיק ביניהם. והנה בזה גופא יש שני בחי' משפיע ומקבל כי בחי' קה\"ק הוא בחי' חיצוני' שבה שנעשה שרש וראש לנאצלים וזהו בחי' אא\"ס כי הוא בחי' א\"ס [מצד שלא נגלה בו בחי' כלים המגבילים רק שרשי הכלים] אבל בחי' פנימי' שבה הוא בחי' אור הזה כמ\"ש נכלל במאור עדיין שזהו כמו שהי' הוא ושמו בלבד<sup data-n=\"3889\">61</sup> ובחי' זאת נק' מלך עילאה דאיהו רזא ופנימי' דקה\"ק [והוא שני בחי' שבכתר<sup data-n=\"3890\">62</sup> הפנימי' הוא בחי' תחתונה שבעצמו' מה<sup data-n=\"3891\">63</sup> שנעשה שרש וראש לנאצלים].\n<b>ועכהנ\"ל</b> יובן ענין שבת שבתון הוא ולפעמים אמר היא<sup data-n=\"3892\">64</sup> בחי' נוק', דכאשר יש תשובה מלמטה למעלה שזהו ענין ועניתם את כו' בתשעה<sup data-n=\"3893\">65</sup> שהוא בחי' נסירה בחי' פירוד הרע מכל חלקי כחות נה\"א כנ\"ל<sup data-n=\"3894\">66</sup> אזי מעוררים מלמעלה מבחי' הפנימי' דמלך עילאה כו' שהוא בחי' דכר כו' ובבחי' זאת מדבר בפ' אמור ולכן לא נאמר חוקת עולם כי לא בכל פעם נמשך בחי' זאת, אבל כאשר אין התשובה מלמטה למעלה אז נאמר שבת שבתון היא שאינו מעורר רק בחי' קה\"ק שהוא בחי' החיצוניות שהוא בחי' שרש וראש לנאצלים כו' וזהו מצד סגולת היום שמאירה בכל פעם ולכן נאמר בזה חוקת עולם. ועם זה יובן ג\"כ מש\"א וכיפר עה\"ק ובסוף א' על",[["3882","54","<b>ואת נפש אויביך יקלענה</b>: שמו\"א כה, כט."],["3883","55","<b>דאית מלך לתתא ואית מלך לעילא</b>: ראה זהר יתרו סז, ב. לקו\"ת כאן (עא, א)."],["3884","56","<b>מל' מכ\"ע</b>: תהלים קמה, יג."],["3885","57","<b>סודכ\"ר</b>: סופא דכל דרגין"],["3886","58","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["3887","59","<b>והבדילה הפרוכת</b>: תרומה כו, לג."],["3888","60","<b>פרסא מפסיק בין אצי'. . הנבראים</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ב. לקוטי הש\"ס להאריז\"ל חולין ס, ב ד\"ה לכי ומעטי (כ, ב). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתפא. וראה גם לקמן מאמר ד\"ה וזכרתי הר\"ת על יד הערה 29 ואילך."],["3889","61","<b>שהי' הוא ושמו בלבד</b>: ראה פדר\"א פ\"ג. תו\"ח וארא ח\"א נג, ב הערה 6."],["3890","62","<b>שני בחי' שבכתר</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א."],["3891","63","<b>מה</b>: אוצ\"ל: ומה."],["3892","64","<b>שבת שבתון הוא. . היא</b>: אמור כג, לב. אחרי טז, לא."],["3893","65","<b>ועניתם. . בתשעה</b>: אמור שם."],["3894","66","<b>כנ\"ל</b>: בהמאמר (ד\"ה והנה בזה)."]]],[4801940474,"מקה\"ק<sup data-n=\"3895\">67</sup> כו' דהנה כתיב כשמן הטוב על הראש יורד על הזקן<sup data-n=\"3896\">68</sup> דהנה בחי' זקן הוא בחי' י\"ג ת\"ד שהוא ענין י\"ג מדה\"ר<sup data-n=\"3897\">69</sup> המאירים מעצמות הכתר בבחי' סובב וממלא [שהוא בחי' חכמה הנק' קדש סוכ\"ע ובינה שנק' טהרה שהוא בחי' ממכ\"ע] והארה זאת להיותה מבחי' העצמיות שלמעלה מבחי' סומ\"מ לזאת לא יוכל להאיר רק הארה חיצוני' בבחי' שערות בלבד שאינו נוגע לעצמו' וכדוגמת השערות באדם שאינו נוגע לעצמו' חיות המוחין ולכן כשיגזזו אותם לא יכאב לו כלל, אך ידוע במסכת נזיר שהשערות חלולים<sup data-n=\"3898\">70</sup> המה שבחלל זה יש חיות פנימי מפנימי' חיות המוחין [... ולכן כשימשכו אותם יכאב לו מאד<sup data-n=\"3899\">71</sup> כן למעלה הנה בחי' השערות הוא מותרי המוחין דח\"ס אך בפנימיותם נמשך בחי' שמן הטוב [ונק' י\"ג נהרי דאפרסמונא דכיא<sup data-n=\"3900\">72</sup> ] ששרשו הוא בבחי' פנימי' הכתר שהוא בחי' אור הנכלל במאור שע\"י סדר ההשתלשלות א\"א להיות נמשך למטה אך מצד כח עצמו' המאור הוא הפועל בו שיהי' נמשך ע\"י השערות כו' [וכנ\"ל בתו' דואני נתתי<sup data-n=\"3901\">73</sup> שע\"י יוסף מלך השמיני בחי' מלך הדר<sup data-n=\"3902\">74</sup> שהוא הפועל ירידת והמשכת שמן הטוב שיהי' נמשך ע\"י השערות כו' [וכנ\"ל בתו' דואני נתתי שע\"י יוסף הוא הטבת הנרות<sup data-n=\"3903\">75</sup> בחי' המשכת שמן ופתילה] והיינו דוקא אחרי ההעלאה מלמטה למעלה שהוא ענין עליית השבטים כמ\"ש ששם עלו שבטים<sup data-n=\"3904\">76</sup> להודות לשם הוי' אז אח\"כ נעשה ירידה והמשכה ע\"י יוסף כו' והמשכה זאת הוא בחי' המשכת שמן הטוב כו'. ובזה יובן ההפרש בין וכיפר עה\"ק לבין וכיפר על מקה\"ק, שכאשר יש תשובה מלמטה למעלה אז מעורר המשכה פנימי' יותר שהוא המשכת שמן הטוב שבבחי' השערות ונק' שבת שבתון הוא ל' דכר אז וכיפר על הקדש שכחו יפה לכפר אפי' על פגם שבחכ\"ע עצמו כי שרש חכ\"ע שנק' בחי' אבא שרשו בבחי' הפנימי' דשמן הטוב, אבל כשאינו מעורר רק המשכת י\"ג מדה\"ר עצמם ששרשם מבחי' החיצוני' אז אינו מכפר רק על מקה\"ק שהוא בחי' אימא אשר שרשה הוא בבחי' החיצוני' ואז נק' שבת שבתון היא כו' וד\"ל.\n<b>ובזה</b> יובן ענין יקרה היא מפנינים<sup data-n=\"3905\">77</sup> מכה\"ג שנכנס לפני ולפנים, כי הנמשך ביוהכ\"פ הוא מצד כניסת כה\"ג ששרשו בחי' אה\"ר להיכל ק\"ק אשר שם השראת השכינה וכן למעלה בכל ג' העולמות דבי\"ע ראשית גילוי אור השכינה דמל' דאצי' היא בהיכל קה\"ק בעולם ההוא, וכאשר הי' נכנס בהיכל קה\"ק הי' בבחי' ביטול גדול לגבי אור השכינה השורה שם, וכן עד\"ז למעלה בחי' שרש נפשו שבכל",[["3895","67","<b>וכיפר עה\"ק. . על מקה\"ק</b>: נסמן לעיל בהמאמר הערה 7."],["3896","68","<b>כשמן הטוב. . הזקן</b>: תהלים קלג, ב."],["3897","69","<b>י\"ג ת\"ד. . י\"ג מדה\"ר</b>: ראה זהר אד\"ר נשא קלא, א. תרומה (ספדצ\"נ פ\"ת) קעז, א. ע\"ח שער א\"א שי\"ג, פ\"ט."],["3898","70","<b>במסכת נזיר שהשערות חלולים</b>: לט, א."],["3899","71","<b>מאד</b>: אוצ\"ל: מאד]."],["3900","72","<b>י\"ג נהרא דאפרסמונא דכיא</b>: ראה תענית כה, א. ראה גם מאמרי אדה\"א נ\"ך ע' תקצו. וש\"נ."],["3901","73","<b>בתו' דואני נתתי</b>: פלח הרמון ויחי קיט, ב-ג."],["3902","74","<b>יוסף מלך השמיני. . הדר</b>: ראה פלה\"ר שם קכב, א. תו\"ח שמות לט, ג. וש\"נ."],["3903","75","<b>שע\"י יוסף הוא הטבת הנרות</b>: ראה פלה\"ר שם קיט, ג."],["3904","76","<b>ששם עלו שבטים</b>: תהלים קכב, ד [בדילוג]."],["3905","77","<b>יקרה היא מפנינים</b>: משלי ג, טו. סוטה ד, ב."]]],[4801940509,"עולם ועולם הי' נכלל בבחי' ביטול לבחי' אור השכינה השורה בהיכל קה\"ק שבעולם ההוא, אך בחי' קה\"ק שבכל עולם הוא בחי' נברא לבד אך עי\"ז הי' שרש נפשו בבחי' אלקות ממש הוא בחי' אה\"ר ששרשו רב חסד<sup data-n=\"3906\">78</sup> הי' נכלל למעלה בקה\"ק דעצמו' אא\"ס כו' ובחי' זאת הי' מעורר למעלה מעלה בחי' קה\"ק דעצמו' אא\"ס שלמעלה מקדש כו' למלאות כל הפגמים והחסרונות, ואופן ההתעוררות הוא בב' אופנים בחי' הוא ובחי' היא לפי אופן מעה\"ת, אך כל כניסתו הי' מעורר השפעה הנ\"ל בבחי' מקיף עלי' כי הנכנס להיכל ההיכל מקיפו בלבד אבל לימוד התורה הוא ג\"כ היכל ק\"ק שנק' ד\"א של הלכה<sup data-n=\"3907\">79</sup> כידוע אך בעת לימודו הוא מתאחד בחכמתו העצמי' בבחי' פנימי' בתוך תוכו וזהו יקרה היא כו' וד\"ל.",[["3906","78","<b>כה\"ג. . אה\"ר. . רב חסד</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תצ. וש\"נ. ש\"א מב, א הערה 25."],["3907","79","<b>היכל ק\"ק שנק' ד\"א של הלכה</b>: ראה ברכות ח, א. תניא פנ\"ג. סידור שער הת\"ת צח, ד. תו\"ח בא ח\"א צד, א. וש\"נ."]]],[4801940122,"<b>שבת חוהמ\"ס תרכ\"ב (מהר\"ה)</b>\n<b>בסוכות</b> תשבו<sup data-n=\"3908\">1</sup> שבעת ימים<sup data-n=\"3909\">2</sup>, איתא ברבות פ' וירא<sup data-n=\"3910\">3</sup> בשכר שא' אברהם למלאכים והשענו תחת העץ<sup data-n=\"3911\">4</sup> שילם לו הקב\"ה בג' מקומות במדבר ובישוב ולע\"ל, במדבר פרש ענן למסך<sup data-n=\"3912\">5</sup>, בישוב בסוכות תשבו כו', ולע\"ל וסוכה תהי' לצל יומם<sup data-n=\"3913\">6</sup>. וצ\"ל מה מגיע לו כ\"כ עבור שאמר להם והשענו תחת העץ.\n<b>והענין</b> כי הנה איתא בזוהר וירא תחת העץ<sup data-n=\"3914\">8</sup> בקוב\"ה אתמר והוא אילנא דחיי<sup data-n=\"3915\">7</sup> שהוא בחי' חכ'<sup data-n=\"3916\">9</sup> והחכ' תחי'<sup data-n=\"3917\">10</sup>, והנה עץ הוא בחי' ומדריגת הנשמות ולא",[["3908","1","<b>בסוכות תשבו</b>: אולי הנחת ר\"ה מדרוש של כ\"ק אדמו\"ר הצ\"צ.\nמאמר הצ\"צ הוא כנראה ד\"ה זה שנדפס באוה\"ת ויקרא ע' קעד ואילך. ראה גם ד\"ה וסוכה תהי' לצל יומם באוה\"ת ישעי' ע' קיח ואילך [נדפס גם באוה\"ת סוכות ע' א'תשח ואילך — ושם חסר]. סה\"מ תרל\"ב ח\"ב ע' תרלה ואילך. ע' תקפא ואילך. ובהנסמן בהנ\"ל.\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י כאן."],["3909","2","<b>בסוכות תשבו שבעת ימים</b>: אמור כג, מב. ראה גם (בנוסף להערה 1) סה\"מ תרל\"ד ר\"ע שמ וע' שפד. תער\"ב ח\"א ע' תיג. תרצ\"ט ע' 54."],["3910","3","<b>איתא ברבות פ' וירא</b>: באוה\"ת ויקרא כאן ע' קעד מציין: רבות וירא פס\"ח (אמנם פס\"ח הוא בפ' ויצא). ראה ב\"ר פמ\"ח, י. טור ברקת הל' סוכה סתרכ\"ה. באוה\"ת ישעי' כאן מציין לטור ברקת סתרכ\"ו. ובאוה\"ת דברים כאן מציין לסתרנ\"ו (סתרנ\"ו הוא הל' לולב ולכאורה זהו טעות הדפוס)."],["3911","4","<b>והשענו תחת העץ</b>: וירא יח, ד."],["3912","5","<b>פרש ענן למסך</b>: תהלים קה, לט."],["3913","6","<b>וסוכה תהי' לצל יומם</b>: ישעי' ד, ו."],["3914","8","<b>תחת העץ</b>: אג: דהעץ."],["3915","7","<b>תחת העץ. . אילנא דחייא</b>: ראה זהר וירא קב, ב."],["3916","9","<b>אילנא דחיי. . חכ'</b>: ראה גם סה\"מ תרכ\"ט ע' שטו."],["3917","10","<b>והחכ' תחי'</b>: קהלת ז, יב [ושם: החכמה — ראה לעיל ע' קמה ובהערה 52]."]]],[4801940186,"מדריגת המלאכים, כי עץ הוא בחי' ומדריגת אדם וכמ\"ש כי האדם עץ השדה<sup data-n=\"3918\">11</sup> וכתיב כימי העץ ימי עמי<sup data-n=\"3919\">12</sup>, כי אדם הוא מדריג' תומ\"צ וכמ\"ש ועל הכסא דמות כמראה אדם<sup data-n=\"3920\">13</sup>, כי רמ\"ח פיקודין רמ\"ח אברים דמלכא<sup data-n=\"3921\">14</sup> ושס\"ה גידים שס\"ה ל\"ת<sup data-n=\"3922\">15</sup>, וכן איתא בספר אור תורה<sup data-n=\"3923\">16</sup> בשם הה\"מ דמעזריטש<sup data-n=\"3924\">17</sup> ע\"פ ועה\"ח בתוך הגן<sup data-n=\"3925\">18</sup> שגן הוא ג\"ן פרשיות של תורה<sup data-n=\"3926\">19</sup> ולכן בחי' זו למעלה ממלאכים, כי במלאכים כתיב זכר רב טובך יביעו<sup data-n=\"3927\">20</sup> וצדקתך ירננו שהשגתם מגיע רק בבחי' צדיק<sup data-n=\"3928\">21</sup> שהוא בחי' מל' צדק מלכותא קדישא<sup data-n=\"3929\">22</sup>, והגם שצ\"ל אליו ולא למדותיו<sup data-n=\"3930\">23</sup> מ\"מ הוא בבחי' מל' רק שהוא בבחי' אא\"ס שמאיר במל' ולא בעצם מדת המל' וע\"כ רק וצדקתך ירננו שהוא בבחי' מלכותך מל' כ\"ע<sup data-n=\"3931\">24</sup> וממשלתך בכל דו\"ד, כי בבחי' המל' שייך זמן<sup data-n=\"3932\">25</sup> מלך מלך וימלוך<sup data-n=\"3933\">26</sup>, וזהו צדק מלאה ימינך<sup data-n=\"3934\">27</sup> אבל שרש הנשמות הוא בבחי' עץ שהוא בחי' ז\"א<sup data-n=\"3935\">28</sup> ולכן בעצרת ר\"ה<sup data-n=\"3936\">30</sup> על פירות האילן<sup data-n=\"3937\">29</sup> כי אז מ\"ת שניתנה לישראל דוקא ולא למלאכים כי בקשו תנה הודך על השמים<sup data-n=\"3938\">31</sup> ולא פעלו, וע\"כ נק' ישראל קדש ישראל לה'<sup data-n=\"3939\">32</sup> ראשית תבואתה<sup data-n=\"3940\">33</sup>, כי מלאכים מקבלים מבחי' [תבואה<sup data-n=\"3941\">34</sup> כי] תבואתה הוא",[["3918","11","<b>כי האדם עץ השדה</b>: פ' שופטים כ, יט."],["3919","12","<b>כימי העץ ימי עמי</b>: ישעי' סה, כב."],["3920","13","<b>ועל הכסא דמות כמראה אדם</b>: יחזקאל א, כו [בדילוג]."],["3921","14","<b>רמ\"ח. . אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["3922","15","<b>ושס\"ה גידים שס\"ה ל\"ת</b>: זהר וישלח קע, ב."],["3923","16","<b>בספר אור תורה</b>: ר\"פ וירא בהוצאת קה\"ת ח, א. ראה גם הנסמן בציונים לשם. סה\"מ תרל\"ב ח\"ב ע' תקכג וע' תקפה וש\"נ. תרל\"ד ע' שפד."],["3924","17","<b>דמעזריטש</b>: א: דמעזיריץ נ\"ע. ג ניתוסף: נ\"ע."],["3925","18","<b>ועה\"ח בתוך הגן</b>: בראשית ב, ט."],["3926","19","<b>ג\"ן פרשיות של תורה</b>: ראה זהר מדהנ\"ע וירא קד, ב. מאמרי אדה\"א דברים ח\"ד ע' א'רג. וש\"נ. ראה גם לעיל ע' צא. וש\"נ."],["3927","20","<b>זכר רב טובך יביעו</b>: תהלים קמה, ז."],["3928","21","<b>צדיק</b>: אג: צדק."],["3929","22","<b>צדק מלכותא קדישא</b>: ת\"ז בהקדמה יז, ב. ראה גם תו\"א מקץ לז, א."],["3930","23","<b>אליו ולא למדותיו</b>: ואתחנן ד, ז. במאמרי אדה\"ז תקס\"ג ח\"א ע' קכו: שארז\"ל בספרי. ראה פרדס שער הכוונה של\"ב, פ\"ב. מאמרי אדה\"א ויקרא ח\"א ע' נ. וש\"נ. נ\"ך ע' לד. וש\"נ."],["3931","24","<b>מלכותך מל' כ\"ע</b>: תהלים קמה, יג."],["3932","25","<b>בבחי' המל' שייך זמן</b>: ראה שער היחוד והאמונה פ\"ז. ראה גם לעיל ע' רטז ובהערה 175."],["3933","26","<b>מלך מלך וימלוך</b>: ראה זהר בראשית לד, א. אוה\"ת סידור ע' פג ואילך."],["3934","27","<b>צדק מלאה ימינך</b>: תהלים מה, יא."],["3935","28","<b>עץ. . ז\"א</b>: ע\"ח שער הזווגים שט\"ו, פ\"ג. מאו\"א מערכת עץ אות יז. לקמן מאמר ד\"ה אם בחוקותי הא' על יד הערה 124."],["3936","30","<b>ר\"ה</b>: ניתוסף לאחר סיום השורה בכת\"י אחר. אג: ליתא."],["3937","29","<b>בעצרת. . על פירות האילן</b>: ר\"ה טז, א (במשנה)."],["3938","31","<b>תנה </b>[בכת\"י זה נרשם סימן מחיקה על תיבה זו]<b> הודך על השמים</b>: תהלים ח, ב. שבת פח, ב. ראה גם מאמרי אדה\"א שמות ח\"א ע' קעד."],["3939","32","<b>קדש ישראל לה'</b>: ירמי' ב, ג."],["3940","33","<b>תבואתה</b>: [א: תבואתו. ג: כבפנים] ראה מאמרי אדה\"א שמות ח\"א ע' א בהערה. סה\"מ תר\"ל ע' קלד ואילך. לק\"ט ר\"פ בראשית ובהערה לב. וראה גם בנוגע למלאכים מאמרי אדה\"ז אתהלך לאזניא ע' קח."],["3941","34","<b>מלאכים. . תבואה</b>: ראה גם מאמרי אדה\"ז אתהלך לאזניא ע' קח וע' קיב. פרשיות התורה ח\"א ע' נט. לקו\"ת פינחס עט, ב ואילך. אוה\"ת פינחס ס\"ע א'רג."]]],[4801940243,"תבואת ה'<sup data-n=\"3942\">35</sup> שמקבלים מבחי' ה' גבורות<sup data-n=\"3943\">36</sup> וע\"כ יש ה' מינים<sup data-n=\"3944\">37</sup> בתבואה וכידוע בענין שעורה שעור ה'<sup data-n=\"3945\">38</sup> לכן<sup data-n=\"3946\">39</sup> לכל חד וחד לפום שיעורא דילי'<sup data-n=\"3947\">40</sup>, אבל שרש הנשמות הוא בבחי' אילן בחי' ז\"א אילנא דחיי<sup data-n=\"3948\">41</sup>.\n<b>והנה</b> אברהם שהי' איש החסד<sup data-n=\"3949\">42</sup> נתן למלאכים עצה והשענו תחת העץ והיינו שגם הם יוכלו לקבל מבחי' העץ הגם בבחי' מקיף עכ\"פ והיינו<sup data-n=\"3950\">43</sup> ע\"י נשמות והוא ע\"ד דכתיב אכלתי יערי עם דבשי<sup data-n=\"3951\">44</sup> ואיתא בזוהר יערי היינו<sup data-n=\"3952\">45</sup> יוצר אור שהוא סיפור המלאכים ודבשי מתיקות דק\"ש, והנה אכלתי יערי עם דבשי שמלאכים מתעלים<sup data-n=\"3953\">46</sup> ג\"כ אח\"כ על ידי האהבה דנש\"י בק\"ש והוא לפי שמקודם מקבלים נשמות ממלאכים כי א\"א לנשמות להגיע להביטול דק\"ש שמצד הנשמה אם לא בהקדם הביטול דנה\"ב, כי הנה\"א מלובשת בנה\"ב ולכן הנה\"ב מעכבת לנה\"א, והנה ביטול הנה\"ב א\"א להיות על ידי ק\"ש כי זה אין יכולה לשמוע [ולהתפעל<sup data-n=\"3954\">47</sup> כ\"א רק הנה\"א מהתבוננות ה' אלקינו ה' אחד, וע\"כ צריך להקדים סיפור המלאכים איך והאופנים וחיות הקדש מתנשאים ברעש גדול שהם שרש המלאכי'<sup data-n=\"3955\">48</sup>, ועי\"ז יכולה הנה\"ב להתפעל ], ואזי אח\"כ יכול גם הנה\"א להתפעל באהבה בק\"ש, והנה עי\"ז שמקבלים נשמות<sup data-n=\"3956\">49</sup> ממלאכים לכן אח\"כ השכר של המלאכים שעל ידי העלי' של הנשמות מתעלים גם הם בבחי' זו הגם שאין זה מדריגתם כלל בעצם, וזהו אכלתי יערי עם דבשי שגם יערי נכלל בבחי' דבשי, וכתי' ונתתי לך מהלכים<sup data-n=\"3957\">50</sup> בין העומדים, שלפי שמקודם נעשה מהלכים דנשמות ע\"י עומדים דמלאכים וכנ\"ל, והנה אח\"כ נעשה מהלכים בין העומדים שגם בחי' עומדים נעשים מהלכים<sup data-n=\"3958\">51</sup>, וזהו שאמר אברהם להמלאכים ונתן להם עצה והשענו תחת העץ שגם הם יקבלו מבחי' העץ הגם שהוא",[["3942","35","<b>תבואתה הוא תבואת ה'</b>: ראה גם זהר ויחי רכו, ב. סה\"מ תר\"ל שם."],["3943","36","<b>מבחי' ה' גבורות</b>: א: ה' גבורות. ג: מבחי' ה' בחי' מל'."],["3944","37","<b>יש ה' מינים</b>: אג: ה' מינים יש."],["3945","38","<b>שעורה שעור ה'</b>: זהר בלק קפח, ב. ראה גם לעיל מאמר ד\"ה וספרתם תקצ\"ח על יד הערה 72 ואילך. ד\"ה וספרתם הד' על יד הערה 9 ואילך. ד\"ה וספרתם הה' על יד הערה 12. ד\"ה והניף הכהן תקפ\"ו על יד הערה 45. לקמן ד\"ה בשברי לכם הא' על יד הערה 19 ואילך. מאמרי אדה\"א הנחות תקע\"ז ע' לד. וש\"נ."],["3946","39","<b>לכן</b>: אג: ליתא."],["3947","40","<b>לפום שיעורא דילי'</b>: ראה זהר וירא קג, רע\"ב."],["3948","41","<b>ז\"א אילנא דחיי</b>: ראה ע\"ח שער דרושי הצלם שכ\"ה, דרוש השלישי. שער הקליפות שמ\"ח, פ\"ב. פלח הרמון בשלח ע' קמ."],["3949","42","<b>אברהם שהי' איש החסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ."],["3950","43","<b>והיינו שגם. . והיינו</b>: א: והיינו. ואולי נשמט מפני תיבות הדומות: והיינו. . והיינו."],["3951","44","<b>אכלתי יערי עם דבשי</b>: שה\"ש ה, א. ראה זהר פינחס רכו, ב. לקו\"ת ראה יט, ד. שה\"ש לד, ב."],["3952","45","<b>היינו</b>: א: הו\"ע."],["3953","46","<b>שמלאכים מתעלים</b>: ראה גם (ובהבא לקמן) תו\"א וישב ל, ב ואילך."],["3954","47","<b>ולהתפעל. . להתפעל</b>: בכת\"י זה: ולהתפלל. וכנראה שזהו טעות המעתיק, וצ\"ל ולהתפעל, וההמשך נשמט כנראה מפני תיבות הדומות."],["3955","48","<b>שרש המלאכי'</b>: כ\"ה גם בג."],["3956","49","<b>שמקבלים נשמות</b>: א: שנשמות מקבלים."],["3957","50","<b>ונתתי לך מהלכים</b>: זכרי' ג, ז."],["3958","51","<b>והנה. . נעשים מהלכים</b>: ראה גם מאמר ד\"ה צאינה וראינה ליל א' דשבועות תשכ\"ב."]]],[4801940296,"למעלה ממדריגתם כי שרשם הוא רק בבחי' מל', והיינו ע\"י נש\"י והוא ע\"ד דכתי' היושבת בגנים<sup data-n=\"3959\">52</sup> חברים מקשיבים לקולך השמיעני כו'<sup data-n=\"3960\">53</sup> היושבת בגנים קאי על נש\"י שיושבים בב'<sup data-n=\"3961\">54</sup> גנים געה\"ע וגעה\"ת<sup data-n=\"3962\">55</sup>, וחברים היינו מלאכים<sup data-n=\"3963\">56</sup>, והנה ע\"י נשמות היושבת בגנים הנה גם חברים שהם מלאכים מקשיבים לקולך השמיעני לתורה כו'.\n<b>אך</b> מי עשה זה אברהם ולכן כתיב ויטע אשל<sup data-n=\"3964\">57</sup> בבאר שבע כי באר שבע הוא [בחי'] מל'<sup data-n=\"3965\">58</sup> שנק' שביעאה דכולהו<sup data-n=\"3966\">59</sup>, ופי' ויטע אשל ר\"ת אכילה שתיה לווי'<sup data-n=\"3967\">60</sup> עי\"ז המשיך מבחי' האילן שהוא בחי' ז\"א<sup data-n=\"3968\">61</sup> בבחי' מל' הנק' באר שבע, ואז יוכלו המלאכים ג\"כ לקבל, ולכן אילן גימט' הוי' אד'<sup data-n=\"3969\">62</sup> יחוד ת\"ת ומל' כי תפארת בחי' בריח התיכון<sup data-n=\"3970\">63</sup> מבריח מן הקצה אל הקצה, והנה בשכר זה שגמל חסד עם המלאכים זכו בניו למצות סוכה ששילם להם הקב\"ה ג\"כ בחי' ומדריגה שגבוה גם ממדריגתם, כי סוכה הוא בחי' גבוה מבחי' עץ החיים, כי כתיב היש בה עץ אם אין<sup data-n=\"3971\">64</sup> עץ הוא בחי' אילנא דחיי והחכ' תחי' אבל בחי' אין גבוה יותר<sup data-n=\"3972\">65</sup> כי והחכ' מאין תמצא<sup data-n=\"3973\">66</sup>.\n<b>והענין</b> כי שהגם שעץ הוא בחי' אדם וכמ\"ש כי האדם עץ השדה שלמע' שהוא בחי' ז\"א<sup data-n=\"3974\">67</sup>, מ\"מ הנה כתי' טוב לחסות בה'<sup data-n=\"3975\">68</sup> מבטוח באדם שהגם שבוטח<sup data-n=\"3976\">69</sup> בפנימיות ולחסות הוא בבחי' מקיף מ\"מ טוב לחסות בבחי' מקיף אבל בבחי' גבוה שהוא בחי' הוי' דז\"א<sup data-n=\"3977\">70</sup> מבטוח באדם שהוא ז\"א, ועד\"ז בחי' ומדריגת סוכה הוא [ב]בחי' גבוה יותר מבחי' עץ וע\"כ צ\"ל הסוכה צלתה מרובה מחמתה<sup data-n=\"3978\">71</sup> כי חמתה הוא בחי' שמש ומגן הוי' אלקים<sup data-n=\"3979\">73</sup> וצ\"ל בחי' גבוה יותר דהיינו צלתה מרובה מחמתה",[["3959","52","<b>היושבת בגנים</b>: שה\"ש ח, יג."],["3960","53","<b>כו'</b>: אג: ליתא."],["3961","54","<b>בב'</b>: שם: בגנים ב'."],["3962","55","<b>גנים געה\"ע וגעה\"ת</b>: ראה תו\"ח וישב קצח, א ובהערה 6. בשלח ח\"א רלז, א. וש\"נ."],["3963","56","<b>וחברים היינו </b>[א: הם]<b> מלאכים</b>: ראה שהש\"ר שם. זהר ויקרא כב, א."],["3964","57","<b>ויטע אשל</b>: וירא כא, לג."],["3965","58","<b>באר שבע. . מל'</b>: ראה זהר ויצא קמז, א ובאוה\"ח ומקדש מלך שם. קנב, רע\"ב ובאוה\"ח שם. ש\"א — לר\"י גיקטלייא — שער א ע' ו. פרדס שעה\"כ שכ\"ג, פ\"ב מערכת באר. מאו\"א אות ב, סי\"א. סה\"מ תרכ\"ז ע' קנא. וש\"נ."],["3966","59","<b>מל' שנק' שביעאה דכולהו</b>: ראה זהר בראשית כד, ב. ויחי ריז, ב. אוה\"ת בשלח ע' תרלח."],["3967","60","<b>אשל ר\"ת אכילה שתיה לווי'</b>: ראה סה\"מ תש\"ט ע' 94. לקו\"ש וירא כרך טו ע' 501."],["3968","61","<b>האילן. . ז\"א</b>: ראה גם ת\"ז תכ\"א ס, א. וראה גם לעיל הערה 41."],["3969","62","<b>אילן גימט' הוי' אד'</b>: באוה\"ת ויקרא כאן ע' קעז־ ישעי' ע' קכב־ סה\"מ תרל\"ד ע' שמ מציין: במא\"א א' פ\"ח."],["3970","63","<b>תפארת בחי' </b>[אג: ליתא]<b> בריח התיכון</b>: ע\"פ תרומה כו, כח. ויקהל לו, לג. ראה זהר בלק קפו, ב ובהגהות הרח\"ו שם."],["3971","64","<b>היש בה עץ אם אין</b>: שלח יג, כ."],["3972","65","<b>יותר</b>: א: ניתוסף: כו'."],["3973","66","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["3974","67","<b>האדם. . ז\"א</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ה."],["3975","68","<b>טוב לחסות בה'</b>: תהלים קיח, ח. ראה לקו\"ת שמ\"ע צ, ד. (צא, ב). אוה\"ת ויקרא כאן ס\"ע קעה."],["3976","69","<b>שבוטח</b>: אג: שטיחה היא (הוא)."],["3977","70","<b>דז\"א</b>: אג: דא\"א."],["3978","71","<b>צלתה מרובה מחמתה</b>: סוכה כב, א (במשנה)."],["3979","73","<b>שמש ומגן הוי' אלקים</b>: תהלים פד, יב."]]],[4801940346,"הוא<sup data-n=\"3980\">72</sup> בחי' ישת חשך סתרו<sup data-n=\"3981\">74</sup>, ולכן נפסק הדין במשנה העושה סוכתו תחת האילן<sup data-n=\"3982\">75</sup> כאלו עשאה בתוך הבית כו' ולכאורה אינו מובן זה הלא כל הענין דמצות סוכה זכו ע\"י והשענו תחת העץ א\"כ למה פסול הסוכה שתחת האילן, אך הענין כי והשענו תחת העץ זה אמר למלאכים שהם יקבלו מבחי' העץ בבחי' מקיף, אבל נשמות שהם עצמם מבחי' עץ בבחי' פנימיות וע\"כ ולקחתם לכם פרי עץ הדר<sup data-n=\"3983\">76</sup>, כי<sup data-n=\"3984\">77</sup> הנה קיחה הוא בחי' פנימיות וע\"כ הסוכה שהוא המקיף מבחי' גבוה יותר ולכן פסולה הסוכה תחת האילן, וזהו העושה סוכתו תחת האילן כאלו עשאה תחת<sup data-n=\"3985\">78</sup> הבית, כי בית הוא מל'<sup data-n=\"3986\">79</sup> ואילן הוא ז\"א והעושה סוכתו תחת האילן ז\"א הוא דומה כאלו הי' עושה תחת הבית בחי' מל', כי הסוכה צ\"ל מבחי' גבוה יותר מבחי' ז\"א.\n<b>והענין</b><sup data-n=\"3987\">*80</sup> שאילן הוא גימט' הוי' אד' וסוכה הוא ג\"כ גימט' הוי' אד'<sup data-n=\"3988\">80</sup> וא\"כ מהו הנ\"מ, אך הענין כי יש ב' מדריגות ביחוד הוי' אד' כי יש שילוב הוי' באד' ויש שילוב אד' בהוי'<sup data-n=\"3989\">81</sup> וע\"כ י\"ל מה שאילן הוא הוי' אד' הוא שילוב הוי' באד' ומה שסוכה הוא הוי' אד' הוא שילוב אד' בהוי'. וגם י\"ל דסוכה הוא הוי' אד' בבחי' גבוה יותר כי אד' הוא שרש דבחי' אד' [דלעילא] וכמ\"ש אד' מי יעמוד<sup data-n=\"3990\">82</sup>, והוי' הוא ג\"כ בחי' הוי' דלעילא כו'. והנה שילם לו הקב\"ה בג' מקומות במדבר ובישוב ולע\"ל, במדבר פרש ענן למסך והוא ענני הכבוד כי יש כבוד תתאה ויש כבוד עילאה<sup data-n=\"3991\">83</sup> כי משה ביקש הראני את כבודך<sup data-n=\"3992\">84</sup> והשיבו וראית את אחורי<sup data-n=\"3993\">85</sup> ופני לא יראו כו' וקאי על כבוד עילאה, וזהו אי' מקום כבודו<sup data-n=\"3994\">86</sup> והוא מאיר ע\"י ענן כי הוא כמו משל לנמשל, ולע\"ל וסוכה תהי' לצל יומם<sup data-n=\"3995\">87</sup> צל על בחי' יומם הוא מקיפים דאבא, כי לע\"ל כתי' ולא יהי' לך עוד השמש לאור יומם והי' הוי' לך לאור עולם<sup data-n=\"3996\">88</sup> כו', וכ\"ז שילם לו",[["3980","72","<b>כי חמתה. . הוא</b>: א: ליתא."],["3981","74","<b>ישת חשך סתרו</b>: תהלים יח, יב. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'רכח ואילך."],["3982","75","<b>העושה סוכתו תחת האילן</b>: סוכה ט, ב."],["3983","76","<b>ולקחתם לכם פרי עץ הדר</b>: אמור כג, מ [בדילוג]."],["3984","77","<b>כי</b>: אג: ליתא."],["3985","78","<b>תחת</b>: אג: בתוך."],["3986","79","<b>בית הוא מל'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ב מערכת בית. מאו\"א מערכת בית אות יד."],["3987","*80","<b>והענין</b>: ג: והגם."],["3988","80","<b>וסוכה. . גימט' הוי' אד'</b>: ראה מאו\"א מערכת סוכה אות טו וביאיר נתיב שם. ראב\"ד לס\"י פ\"א, מי\"א [ירושלים תשכ\"ב לג, ב]. פרדס שעה\"כ שכ\"ג, פט\"ו מערכת סוכה [ועם הגהות באוה\"ת ישעי' כאן ע' קיח ואילך. וראה גם אוה\"ת ויקרא כאן ס\"ע קעז ואילך. סה\"מ תרל\"ד כאן ע' שמ]. פע\"ח שער חה\"ס שכ\"ח, פ\"ב. פ\"ג."],["3989","81","<b>שילוב הוי' באד'. . אד' בהוי'</b>: ראה מבו\"ש ש\"ג ח\"ב ספ\"ה. לקו\"ת ש\"ש סה, ד ובהנסמן במ\"מ לשם סד, ב. תו\"ח וארא ח\"א נ, א הערה 32. וראה גם לעיל ע' צה."],["3990","82","<b>אד' מי יעמוד</b>: תהלים קל, ג. ראה גם לקו\"ת שלח מ, א."],["3991","83","<b>כבוד תתאה ויש כבוד עילאה</b>: ראה לקו\"ת שה\"ש מז, ב ואילך. מאמרי אדה\"א דרושי חתונה ח\"א ע' א. וש\"נ. תו\"ח וישב ר, ג ובהערה 47. סה\"מ תרכ\"ט ע' קנג. וש\"נ. לקמן מאמר ד\"ה בסוכות תשבו הב' על יד הערה 130. לעיל ע' קפה. ולהעיר מר\"ח יבמות מט, ב: יש כבוד למעלה מכבוד."],["3992","84","<b>הראני [ג ניתוסף</b>: נא] את כבודך: תשא לג, יח [בדילוג]."],["3993","85","<b>וראית את אחורי</b>: תשא לג, כג."],["3994","86","<b>אי' מקום כבודו</b>: נוסח קדושת כתר."],["3995","87","<b>הוא מקיפים. . יומם</b>: א: ליתא."],["3996","88","<b>ולא יהי'. . לאור עולם</b>: ישעי' ס, יט [בדילוג. ושם: לא יהי' — אבל כ\"ה גם בסה\"מ תרל\"ח ע' צו. וש\"נ]."]]],[4801940393,"לפי שגמל חסד עם המלאכים להמשיך בהם בחי' שגבוה ממדריגתם כי מדריגתם הוא רק בבחי' מל' כנ\"ל והוא המשיך בהם והשענו תחת העץ ויטע אשל בבאר שבע המשכה מבחי' ז\"א, לכן השכר שלו שזכו בניו למצות סוכה שהוא ג\"כ גבוה ממדריגת בחי' עץ החיים, כי היש בה עץ אם אין כנ\"ל הרי בחי' אין גבוה מבחי' עץ, ומה ששילם לו בג' מקומות מדבר וישוב ולע\"ל, הוא כנגד ג' מדריגות בינה [ו]ז\"א ומל', כי מדבר הוא בחי' מל'<sup data-n=\"3997\">89</sup> וישוב הוא בחי' ז\"א ע\"ש ישב אדם שם<sup data-n=\"3998\">90</sup>, ולע\"ל הוא בחי' בינה<sup data-n=\"3999\">91</sup>, וכ\"ז על ידי שאמר למלאכים והשענו תחת העץ, וזהו שלח לחמך על פני המים<sup data-n=\"4000\">92</sup> כי ברוב הימים תמצאנו פי' ברוב הימים היינו המשכה מבחי' ימי קדם כנ\"ל<sup data-n=\"4001\">93</sup>.",[["3997","89","<b>מדבר. . מל'</b>: ראה לקו\"ת במדבר ג, ב."],["3998","90","<b>ישב אדם שם</b>: ירמי' ב, ו."],["3999","91","<b>ולע\"ל. . בינה</b>: ראה גם אוה\"ת ויקרא כאן ע' קעו."],["4000","92","<b>שלח לחמך על פני המים</b>: קהלת יא, א."],["4001","93","<b>כנ\"ל</b>: א: כו' וד\"ל."]]],[4801940123,"<b>בסוכות</b> תשבו שבעת ימים<sup data-n=\"4002\">1</sup> כל האזרח בישראל ישבו בסוכות<sup data-n=\"4003\">2</sup> למען ידעו דורותיכם<sup data-n=\"4004\">3</sup> כי בסוכות הושבתי את בנ\"י כו', נמצא שמצות סוכה דעכשיו הוא זכר לענני כבוד<sup data-n=\"4005\">4</sup> שהי' במדבר בצאתם ממצרים. וזהו מ\"ש בתהילים ויבא מלך הכבוד<sup data-n=\"4006\">5</sup> כו' שקאי על מקיפים דסוכות דעכשיו שהוא נגד ענני כבוד שהי' במדבר, כי בתהילים מבואר שם ג' ענינים ר\"ה ויו\"כ וסוכות, שמ\"ש לה' הארץ ומלואה<sup data-n=\"4007\">6</sup> קאי על ר\"ה כמ\"ש ארץ אשר הוי' אלקיך דורש אותה מראשית השנה<sup data-n=\"4008\">7</sup> כו', שבר\"ה הארץ מקבל מבחי' הוי' עצמו משא\"כ בכל השנה שאינה מקבלת רק מבחי' אלקים כמשי\"ת. ומ\"ש עוד מי יעלה בהר ה'<sup data-n=\"4009\">8</sup> ומי יקום במקום קדשו קאי על יו\"כ שביו\"כ הוא גילוי מבחי' מקום קדשו העצמי כמ\"ש במשה הנה מקום אתי<sup data-n=\"4010\">9</sup> ונצבת על הצור כו' ויעבור ה' על פניו<sup data-n=\"4011\">10</sup> ויקרא הוי' הוי' כו' נמצא שבחי' מקום אתי הוא ענין גילוי של י\"ג מדה\"ר שזה ג\"כ מאיר בכל יו\"כ<sup data-n=\"4012\">11</sup>, ויבא מלך הכבוד הוא ענין הגילוי של מקיפים",[["4002","1","<b>בסוכות תשבו שבעת ימים</b>: הנחת ר\"ה מדרוש כ\"ק אדמו\"ר הצ\"צ.\nלהבא לקמן ראה מאמר ד\"ה לדוד מזמור נדפס באוה\"ת האזינו בהוספות ע' א'תתקל ואילך. ולפיסקא מי יעלה ראה אוה\"ת תהלים כרך ג ע' א'רצב ואילך."],["4003","2","<b>בסוכות תשבו. . בסוכות</b>: אמור כג, מב."],["4004","3","<b>למען ידעו דורותיכם</b>: שם כג, מג."],["4005","4","<b>סוכה. . לענני כבוד</b>: ראה שו\"ע אדה\"ז הל' סוכה סתרכ\"ה."],["4006","5","<b>ויבא מלך הכבוד</b>: תהלים כד, ז. ט."],["4007","6","<b>לה' הארץ ומלואה</b>: שם כד, א."],["4008","7","<b>ארץ אשר הוי'. . השנה</b>: עקב יא, יב (בדילוג)."],["4009","8","<b>מי יעלה בהר ה'</b>: תהלים כד, ג."],["4010","9","<b>הנה מקום אתי</b>: תשא לג, כא."],["4011","10","<b>ויעבור ה' על פניו</b>: שם לד, ו."],["4012","11","<b>י\"ג מדה\"ר. . יו\"כ</b>: ראה לקו\"ת דברים א, ד. תו\"ח בשלח ח\"א קעב, א. וש\"נ."]]],[4801940187,"דסוכות זכר לענני כבוד כנ\"ל, נמצא שמבואר בקפיטל<sup data-n=\"4013\">12</sup> זה של מזמור לדוד<sup data-n=\"4014\">13</sup> ג' ענינים ר\"ה ויו\"כ וסוכות לכן אומרים זה בר\"ה ויו\"כ<sup data-n=\"4015\">14</sup>.\n<b>ולהבין</b> את כל הנ\"ל, גם להבין מ\"ש כאן ארץ וכאן כתי' תבל, גם כאן כתיב ומלאה וכאן כתי' יושבי בה, דהנה כתי' אשריך ארץ שמלכך בן חורין<sup data-n=\"4016\">15</sup> אוי לך ארץ שמלכך נער<sup data-n=\"4017\">16</sup>, נמצא שלפעמים הארץ היא בן חורין כשמקבל מבחי' הוי' עצמו כמו בר\"ה משא\"כ כשמקבלת ע\"י ממוצעים ע\"י בחי' נער שש\"ע<sup data-n=\"4018\">17</sup> אז היא אינה בן חורין כמשי\"ת. דהנה כתי' וזאת המצוה אשר ציוה ה' אלקי' כו' לעשות בארץ<sup data-n=\"4019\">18</sup> כו' שמע<sup data-n=\"4020\">19</sup> ישראל<sup data-n=\"4021\">20</sup> כו', ולכאורה מה שייך זה לארץ דוקא הלא ק\"ש היא חובת הגוף<sup data-n=\"4022\">21</sup> ונוהגת בין בארץ בין בחו\"ל כמארז\"ל מצות התלויות בארץ<sup data-n=\"4023\">22</sup> אינה נוהגת אלא בארץ אבל מצות שאינה תלויות בארץ נוהגת בין בארץ בין בחו\"ל, וק\"ש הוא חובת הגוף. דהנה כתי' את ה' האמרת היום<sup data-n=\"4024\">23</sup> וה' האמירך היום<sup data-n=\"4025\">24</sup> כו' וארז\"ל אתם עשוני חטיבה אחת בעולם<sup data-n=\"4026\">25</sup> שנ' שמע ישראל כו' הוי' אחד שישראל עושין אותו לשבח בעולם שאומרים הוי' אחד אף אני אעשה אתכם ג\"כ חטיבה אחת בעולם שנאמר<sup data-n=\"4027\">26</sup> ומי כעמך ישראל<sup data-n=\"4028\">27</sup> גוי אחד בארץ כו', וצ\"ל מה ענין השבח מישראל במה שאומרים ה' אחד הלא כתי' מקודם אנוכי הוי' אלקי'<sup data-n=\"4029\">28</sup> כו' ולא יהי' לך<sup data-n=\"4030\">29</sup> אלקים",[["4013","12","<b>בקפיטל</b>: ראה גם תו\"ח בא ח\"א קז, ג. וש\"נ. אוה\"ת (יהל אור) תהלים ע' לא ס\"ח. סה\"מ תרל\"ו ח\"ב ע' שלח. קול ברמה לד, ב."],["4014","13","<b>מזמור לדוד</b>: כנצ\"ל: לדוד מזמור."],["4015","14","<b>מזמור לדוד. . בר\"ה ויו\"כ</b>: ראה פע\"ח שער תפילות ר\"ה שכ\"ה, פ\"ז (ולא נזכר יו\"כ). מ\"ח מסכת ליל ר\"ה פ\"ח, מ\"ה. מסכת יומא פ\"ד, מ\"ט. סידור ר\"ש רשקוב־ קול יעקב־ אדה\"ז במקומו. מטה אפרים סתקפ\"ב, ס\"ג. סתרי\"ט, סי\"ח. וראה גם אוה\"ת (האזינו בהוספות) כאן ע' א'תתקל. תהלים כרך ג ס\"ע א'רפו. שם ע' א'רפג. ע' א'רפו (ובשניהם ר\"ה)."],["4016","15","<b>אשריך ארץ שמלכך בן חורין</b>: קהלת י, יז [ושם: חורים — אבל כ\"ה גם בזהר לך צה, ב. סידור קול יעקב בתפלת העמידה לשבת (ישמח משה). אוה\"ת עקב ע' תרב ס\"ו. ע' תרח סי\"ג. ואתחנן ע' צ. ע' קלא. סה\"מ תרל\"ד ע' רפח. תרע\"ט ע' תקעז]."],["4017","16","<b>אוי לך.. נער</b>: שם י, טז [ושם: אי — אבל כ\"ה גם בסה\"מ תרע\"ט שם]."],["4018","17","<b>נער שש\"ע</b>: ראה יבמות טז, ב ובתוס' שם."],["4019","18","<b>וזאת המצוה. . בארץ</b>: ואתחנן ו, א [בדילוג]."],["4020","19","<b>וזאת המצוה. . שמע ישראל</b>: ראה לקו\"ת ואתחנן ד, א. ט, א. מאמרי אדה\"א הנחות תקע\"ז ע' רנה. וש\"נ."],["4021","20","<b>שמע ישראל</b>: ואתחנן שם, ד."],["4022","21","<b>ק\"ש היא חובת הגוף</b>: ראה קדושין לז, א וברש\"י שם. וראה גם לקו\"ש עקב כרך ט ע' 80 ואילך ובהערות שם. אחרי כרך יז ע' 190."],["4023","22","<b>מצות התלויות בארץ</b>: ראה קדושין לו, ב (במשנה)."],["4024","23","<b>את ה' האמרת היום</b>: תבוא כו, יז."],["4025","24","<b>וה' האמירך היום</b>: תבוא שם, יח."],["4026","25","<b>אתם עשוני חטיבה אחת בעולם</b>: באוה\"ת (האזינו בהוספות) כאן ס\"ע א'תתקל מציין: חגיגה ד\"ג סע\"א. . עשאוני. באוה\"ת תבוא ע' תתרנז ובכרך ה ע' ב'סו מציין: בברכות ד\"ו ע\"א: אתם עשאוני. אבל באוה\"ת תבוא ע' תתרסח (מברכות). ע' תתרעט (מברכות וחגיגה) מובא: עשיתוני. ראה גם הנסמן בד\"ה את הוי' האמרת תש\"ל [קונט' ח\"י אלול תשמ\"ז — סה\"מ מלוקט ב ע' פז הערה 2). הל' שבפנים: עשוני מובא באוה\"ת תבוא כרך ו ע' ב'שעט. אבל לקמן בפיסקא וזהו ג\"כ, כותב: עשיתוני."],["4027","26","<b>שנ'. . שנאמר</b>: כ\"ה בברכות שם. ובחגיגה דכתיב. ובאוה\"ת (האזינו בהוספות) כאן ותבוא ע' תתרעט: דכתיב. . שנאמר."],["4028","27","<b>ומי כעמך ישראל</b>: דהי\"א יז, כא. ראה סה\"מ מלוקט שם הערה 4."],["4029","28","<b>אנוכי הוי' אלקי'</b>: יתרו כ, ב."],["4030","29","<b>ולא יהי' לך</b>: יתרו כ, ג."]]],[4801940244,"אחורים כו' נמצא שהי' ציווי ע\"ז בעת מ\"ת מכבר ומה זה חידוש מזה שאומרים הוי' אחד שלכאו' הוא ענין אחד עם הציווי של אנוכי ולא יהי' לך. גם במנין המצות נמנה זה למצוה בפ\"ע מצווה ליחדה<sup data-n=\"4031\">30</sup> את ה' שהו\"ע הוי' אחד, ואנוכי ולא יהי' לך נמנה לב' מצוות<sup data-n=\"4032\">31</sup> בפ\"ע, דהנה ביתרו כתי' עתה ידעתי<sup data-n=\"4033\">32</sup> כי גדול הוי' מכל האלקי' כו' ואיתא במדרש שאמר השבח עדיין לא בשלימות<sup data-n=\"4034\">33</sup> כי במשה כתי' וידעת היום<sup data-n=\"4035\">34</sup> כו' כי הוי' הוא האלקים בשמים ממעל כו' נמצא שהוי' ואלקים כולא חד<sup data-n=\"4036\">35</sup> ממ\"ש ולא שאלקי' הוא מציאות בפ\"ע, ולכאורה הלא במשה כתי' ג\"כ כי הוי' אלקיכם<sup data-n=\"4037\">36</sup> הוא אלקי האלקים, גם בתהילים כתי' ג\"כ בזה הלשון הודו לאלקי האלקי'<sup data-n=\"4038\">37</sup> כו', ומפני מה אמר במדרש שיתרו דווקא אמר השבח לא בשלימות, גם שבאמת יש סברא שיתרו קודם מ\"ת בא<sup data-n=\"4039\">38</sup> ושמע ג\"כ הציווי של עשה\"ד של אנכי ולא יהי' לך ובוודאי אמר השבח בשלימות.\n<b>דהנה</b> בפי' אלקי' יש ב' פירושים הא' פי' אלקי' לשון אלקי' ממש כמ\"ש במלאכים ויבאו בני האלקים<sup data-n=\"4040\">40</sup> דמצד שהם בתכלית הביטול לאלקים נקראים ג\"כ אלקי'<sup data-n=\"4041\">39</sup>, כמ\"ש זה דור דורשיו<sup data-n=\"4042\">41</sup> מבקשי פניך יעקב סלה כו'<sup data-n=\"4043\">42</sup> שנק' פנימי' א\"ס בשם יעקב מצד עוצם ביטולו לפנימי' א\"ס, גם כמ\"ש ויקרא לו אל אלקי ישראל<sup data-n=\"4044\">43</sup> והפי' הוא שאלקי ישראל קראו ליעקב אל, שיעקב הי' בבחי' אלקי' ממש, גם במשה כתי' ונתתי עשב<sup data-n=\"4045\">44</sup> כו' שאמר ע\"ע ונתתי, ומלאכים דוברים ג\"כ בשם ה'",[["4031","30","<b>הוי' אחד. . מצווה ליחדה </b>[וכ\"ה לקמן בפיסקא וזהו ג\"כ. וכנצ\"ל: ליחדו]: רמב\"ם בספה\"מ מ\"ע ב. הל' יסוה\"ת פ\"א, ה\"ז. סהמ\"צ להצ\"צ ע' 118 ואילך."],["4032","31","<b>ואנוכי ולא יהי'. . לב' מצוות</b>: רמב\"ם בסהמ\"צ מ\"ע א. מל\"ת א. הל' יסוה\"ת פ\"א, ה\"ו. סהמ\"צ להצ\"צ ע' 88 ואילך."],["4033","32","<b>עתה ידעתי</b>: יתרו יח, יא."],["4034","33","<b>השבח עדיין לא בשלימות</b>: ראה דב\"ר פ\"ב, [כח]. אוה\"ת יתרו ע' תשלט ואילך. ע' תשמט ואילך."],["4035","34","<b>וידעת היום</b>: ואתחנן ד, לט. ראה גם לקמן מאמר ד\"ה וזכרתי הר\"ת על יד הערה 69."],["4036","35","<b>שהוי' ואלקים כולא חד</b>: ראה זהר בהקדמה יב, א. תרומה קסא, ב. מאמרי אדה\"א דברים ח\"א ע' קעה ובהנסמן בריש המאמר שם. תו\"ח וארא ח\"א ס, א. וש\"נ. לקמן מאמר ד\"ה אם בחוקותי הא' על יד הערה 43 ואילך."],["4037","36","<b>כי הוי' אלקיכם</b>: עקב י, יז."],["4038","37","<b>הודו לאלקי האלקי'</b>: תהלים קלו, ב."],["4039","38","<b>שיתרו קודם מ\"ת בא</b>: ראה מכילתא (ורש\"י) ר\"פ יתרו. זבחים קטז, א. זהר יתרו סז, ב. סח, א. תו\"ח יתרו ח\"ב רעא, ד ואילך. ביאוה\"ז להצ\"צ כרך א ע' רנד ואילך. ד\"ה באתי לגני תשל\"ח ס\"ב ואילך (קונ' כ\"ב שבט תשמ\"ט — סה\"מ מלוקט ג ע' נח ואילך). וש\"נ."],["4040","40","<b>ויבאו בני האלקים</b>: איוב א, ו. ב, א."],["4041","39","<b>במלאכים. . הביטול. . נקראים ג\"כ אלקי'</b>: ראה תו\"א תשא פו, א. אוה\"ת יתרו ע' תשמח ואילך. ע' תשסג (נדפס גם באוה\"ת תשא ע' א'תתעד)."],["4042","41","<b>זה דור דורשיו</b>: תהלים כד, ו. ראה גם אוה\"ת וישלח כרך ה ע' תתעט."],["4043","42","<b>כו'</b>: כ\"ה בהכת\"י."],["4044","43","<b>ויקרא לו אל אלקי ישראל</b>: וישלח לג, כ. מגילה יח, א. הובא ברש\"י ורמב\"ן וישלח שם. ראה גם לקמן מאמר ד\"ה את שבתותי תשמרו תרי\"ב על יד הערה 67 ואילך. תו\"ח בשלח ח\"א רמו, ד ואילך. ויקהל ח\"ב שפט, ג ובהנסמן בהנ\"ל. אוה\"ת בהר כרך ד ע' א'קמד ואילך. סה\"מ תרכ\"ז ס\"ע קיג ואילך. תרל\"ב ח\"א ע' לז ואילך ובהנסמן שם. תרל\"ג ח\"א ע' מח ואילך. וש\"נ. סה\"מ תרל\"ח ע' קצה."],["4045","44","<b>ונתתי עשב</b>: עקב יא, טו."]]],[4801940297,"כמ\"ש בי נשבעתי<sup data-n=\"4046\">45</sup> כו'. ויש עוד פי' אלקי' לשון כח<sup data-n=\"4047\">46</sup> כמ\"ש ואת אלי הארץ לקח<sup data-n=\"4048\">47</sup> כו', ראה נתתיך אלקי' לפרעה<sup data-n=\"4049\">48</sup> שנתן לו כח לשלוח העשר מכות למצרים, ודיינים נקראים ג\"כ בשם אלקי'<sup data-n=\"4050\">49</sup> ע\"ש הכח והיכולת שיש להם, לכן מלאכים נקראים ג\"כ בשם אלקי' ע\"ש הכח שיש להם להשפיע למטה כל מיני השפעה שהם כוחות שלוחי השפע, כמו שאנו רואים למטה שיש תבואות שגדילים מן השמש ויש תבואות שגדילים מן לבנה כמ\"ש ממגד תבואות שמש<sup data-n=\"4051\">50</sup> וממגד גרש ירחים נמצא שבחמה ולבנה יש כח להשפיע למטה כמ\"כ מלאכים הם כוחות שמשפיעים בעולמות העליונים הרוחני' ולכן נקראים אלקי' לשון כח<sup data-n=\"4052\">51</sup>, ובאמת ב' הפירושים הכל ענין אחד דהכח שיש להם הוא רק מצד האא\"ס המלובש בהם ולא שיש בהם כח מצד עצמם ח\"ו רק מפני שהם בבחי' ביטול לאא\"ס עד שהם בבחי' אלקי' ממש לכן שורה בהם אא\"ס ומצד האא\"ס השורה בהם נמצא בהם הכח והיכולת, כמו שליח הוא ביד המשלח שהמשלח הוא העיקר אבל השליח עצמו אין לו שום כח רק לפי רצון המשלח דווקא כמ\"כ חמה ולבנה הגשמי או מלאכים עליונים הרוחניים אין להם שום כח מצד עצמם רק שהם כגרזן ביד החוצב<sup data-n=\"4053\">52</sup> כו' והעיקר הוא אא\"ס המלובש בהם הוא העושה בהם הכח להשפיע בכל עולם לפי ערכו.\n<b>וזהו</b> מ\"ש וידעת כו' כי הוי' הוא האלקי' שהעיקר הוא הוי' שהוא אא\"ס המלובש בשם אלקי' ושם אלקי' הוא טפל ובטל לבחי' הוי' כגרזן ביד החוצב כו', גם ע\"ס דאצי' נקראים ג\"כ בשם אלקי' מב' טעמים הנ\"ל שהם כוחות ומקורים לכללות הע\"ס הנמצאים בבי\"ע והם בתכלית האחדות עם עצמות אא\"ס המאיר בעולם אצי' כמ\"ש איהו וחיוהי חד<sup data-n=\"4054\">*53</sup> איהו וגרמוהי כו', וזהו בשמים ממעל שקאי על ע\"ס דאצי' ועל הארץ מתחת שהו\"ע מלאכים דבי\"ע עד חמה ולבנה הגשמי הכל הוי' הוא העיקר והאלקי' הוא בטל וטפל עד שאינה במציאות כלל נגד בחי' הוי', וזהו אין עוד אפי' עוד הטפל אין שייך ג\"כ לומר עליו [שבאמת לבד שאין להם כח מצד עצמם אלא גם עצם מציאותם הוא ג\"כ רק מצד אא\"ס המלובש בהם ולולי הא\"ס המלובש בהם אין להם שום מציאות כלל. נמצא שהכל הוא העיקר הוי' אפי' בבחי' מציאותן עד שאין שייך לקרוא להם אפי' בבחי' עוד הטפל, כי בכל נברא יש ב' בחי' פנימי' וחיצוני' ומצד פנימיותם הם בתכלית הביטול ונפשטים מהגבלתם ונכללים בעצמות",[["4046","45","<b>בי נשבעתי</b>: וירא כב, טז. ראה קו\"א לתניא ד\"ה להבין מ\"ש בפע\"ח קנט, א."],["4047","46","<b>אלקי' לשון כח</b>: ראה שו\"ע אדה\"ז דין כוונת הברכות ס\"ה, ס\"ג. תו\"ח וארא ח\"א עה, ב. וש\"נ."],["4048","47","<b>ואת אלי הארץ לקח</b>: יחזקאל יז, יג [ושם: אילי — אבל כ\"ה גם בחידושי אגדות מהר\"ל מנחות נג, ב ד\"ה יבא אדיר. או\"ת עקב נב, ד. תו\"א מקץ מ, ג. סה\"מ שבהערה 49 ושם: את אלי]."],["4049","48","<b>ראה נתתיך אלקי' לפרעה</b>: וארא ז, א."],["4050","49","<b>ודיינים. . בשם אלקי'</b>: ראה מכילתא (ורש\"י) יתרו כ, א. משפטים כב, כז. סנהדרין סו, א. אוה\"ת יתרו ע' תשמג. סה\"מ תרס\"ח ע' קעד."],["4051","50","<b>ממגד תבואות שמש</b>: ברכה לג, יד [ושם: וממגד]."],["4052","51","<b>מלאכים. . אלקי' לשון כח</b>: ראה גם אוה\"ת יתרו ע' תשנא. סה\"מ תרס\"ח שם ואילך."],["4053","52","<b>כגרזן ביד החוצב</b>: מו\"נ ח\"ג פכ\"ט. זהר בראשית לו, א. ישעי' י, טו."],["4054","*53","<b>איהו וחיוהי חד</b>: ת\"ז בהקדמה ג, ב."]]],[4801940347,"האא\"ס הבבע\"ג עד שהם אלקו' ממש, ופי' אלקות ממש הוא כי עצמות אא\"ס הוא באמת בלתי מוגבל רק כשצריך לירד למקבלים הוצרך לבוא ולהתצמצם בבחי' גבול בכדי שיהי' יש וגבול, אך כשנפשטים מיש שלהם אז הם ניכללים באא\"ס הבלתי מוגבל ולכן הם אלקו' ממש כמו עצמות אא\"ס הבלתי מוגבל ממש, אך באמת מצד חיצוני' שלהם הם עומדים בבחי' גבול ולכן יש בכוחם להשפיע למטה בבחי' גבול ג\"כ כמו ממחנה מיכאל נמשך למטה בחי' חסד דווקא וממחנה גבריאל בחי' גבו' דווקא כמו חמה מגדל צמחים אלו, ובוודאי הם עצמם ג\"כ בבחי' גבול ומציאות יש ולכן נקראים בשם אלקי' לשון כח מצד הכח הנמצא בחיצוני' שלהם להשפיע למטה, ונמצא לכאו' שזו ב' הפכים אך באמת הא בהא תלי' כי הכח הנמצא בחיצוני' שלהם הוא רק מצד עוצם הביטול שלהם בבחי' פנימי' שלהם לכן הם מקבלים הכח מאא\"ס להשפיע למטה נמצא שהגבול שלהם הוא ג\"כ מאא\"ס הבלתי מוגבל כמו שליח שגם החיצוני' שלו הכח הנמצא בו הוא רק מצד פנימי' הביטול שלו למשלח, ולא עוד שלמע'<sup data-n=\"4055\">54</sup> אפי' עצם מציאותן הוא ג\"כ מא\"ס לבד הכח הנמצא בהם משא\"כ בשליח שעצם מציאותו הוא נמצא מצד עצמו אבל למע' הרי הכל הוא ממך כו', לכן הן הכח שלהם והן עצם מציאותן הוא רק מא\"ס, וכ\"ז הוא רק מצד פנימי' הביטול שלהם, ונמצא שב' הפי' הכל אחד]<sup data-n=\"4056\">53</sup>.\n<b>וזהו</b> ג\"כ כי הוי' אלקיכם הוא אלקי האלקים שהעיקר הוא הוי' דווקא כמ\"ש לקמן עושה משפט<sup data-n=\"4057\">55</sup> כו' הוא הוא העושה בעצמו את משפט יתום כו', וזהו מ\"ש הודו לאלקי האלקים כל\"ח שההודאה והביטול צ\"ל לאלקי האלקים לעצמו' האא\"ס המקור לכל בחי' אלקי'. ובזה יובן מ\"ש במדרש שביתרו השבח עדיין אינה בשלימות שאמר כי גדול הוי' מכל האלקים משמע שיש מציאות ג\"כ להם רק שהוי' הוא גדול מהם, ובאמת לפי המבואר לעיל אין להם שום מציאות כלל ומה שנראה מציאותן הכל הוא רק הוי'. וזהו אתם עשיתוני חטיבה אחת במה שאומרים הוי' אחד שהכל הוא רק אחדות הפשוטה ואין שום מציאות בלעדי ית'. וזהו מצוות היחוד באלקי' שנחשב למצווה בפ\"ע, כי הציווי של אנוכי הוא מצוה להאמין שיש מציאות לא\"ס ולא יהי' לך הוא מצווה בפ\"ע שלא יהי' אלקי' אחרים ח\"ו, אבל משמע שיש מציאות בלעדו רק שלא יהי' עובד להם אבל מצוות היחוד הוא ליחדה שבאמת אין שום מציאות כלל בלעדו ית', וזהו שאנו אומרים לשם יחוד קוב\"ה ושכנתי' קודם כל מצוה<sup data-n=\"4058\">56</sup> שהו\"ע מצוות יחוד כנ\"ל.\n<b>אף</b> אני אעשה אתכם חטיבה אחת בעולם שנאמר ומי כעמך ישראל גוי אחד בארץ כו' שהם ג\"כ במדריג' אחד [ולכאורה איך שייך לומר עליהם אחד דבשלמ' על",[["4055","54","<b>עוד שלמע'</b>: אוצ\"ל: עוד אלא שלמע'."],["4056","53","[שבאמת. . אחד]: כנראה שזהו הגהת ר' הלל."],["4057","55","<b>עושה משפט</b>: עקב י, יח [המשך להכתוב שלפנ\"ז כי ה\"א]."],["4058","56","<b>שאנו אומרים לשם יחוד. . קודם כל מצוה</b>: ראה פע\"ח שער הזמירות ש\"ז, ספ\"ה. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקצב ובהנסמן במ\"מ לשם. מאמרי אדה\"א הנחות תקע\"ז ע' קצב. וש\"נ. תו\"ח תצוה ח\"ב שלט, ב. וש\"נ. המשך מים רבים תרל\"ו ע' רל. ח\"ב ע' רפז."]]],[4801940394,"הקב\"ה נופל לשון אחד שאין שום מציאות בלעדו ית', אך פי' אחד הנאמר על נש\"י הפי' הוא כך] אחד שאין כיוצא להן כמ\"ש באברהם אחד הי' אברהם<sup data-n=\"4059\">57</sup> שלא הי' כיוצא בו בדורו כך נש\"י הם אחד שאין כיוצא להן כמ\"ש נש\"י עבמ\"ח<sup data-n=\"4060\">58</sup> בנים אתם להוי'<sup data-n=\"4061\">59</sup> כו' חלק הוי' עמו<sup data-n=\"4062\">60</sup> משא\"כ המלאכים. נמצא ששרשם ומקורם הוא בהוי' אחד בבחי' אחדות הפשוטה אך ירדו למטה בכדי להפכא חשוכא לנהורא<sup data-n=\"4063\">61</sup> דווקא, שנתאווה הקב\"ה להיות לו דירה בתחתונים<sup data-n=\"4064\">62</sup> דווקא לכן ירדו הנשמות למטה להפוך חושך התחתון לאור ע\"י שישראל הם מתקשראן באוריי' ואוריי' בקוב\"ה<sup data-n=\"4065\">63</sup> נמצא שע\"י מעשה המצוות גשמי' למטה הם ממשיכים הוי' אחד למטה. ועיקר הגילוי יהי' לע\"ל כמ\"ש ונגלה כבוד הוי'<sup data-n=\"4066\">64</sup> כו' וכ\"ז ע\"י היום לעשותם<sup data-n=\"4067\">65</sup> דווקא והעיקר הוא היום לעשותם<sup data-n=\"4068\">66</sup> כמ\"ש יפה שעה אחת<sup data-n=\"4069\">67</sup> בתשובה ומע\"ט בעוה\"ז מכל חיי עוה\"ב, וזהו גוי אחד בארץ<sup data-n=\"4070\">68</sup> שממשיכים בחי' הוי' אחד למטה בארץ ע\"י תומ\"צ הנעשים בארץ, ודווקא בארץ עי\"ז הם ממשיכים מבחי' עצמות א\"ס למטה מצד דנסב\"ת<sup data-n=\"4071\">69</sup> סוף מעשה עבמ\"ת<sup data-n=\"4072\">70</sup>, ופי' בארץ ע\"י הארץ מצד נסב\"ת כנ\"ל.\n<b>והענין</b> הוא דהנה כתי' וזאת הארץ אשר תפול לכם לנחלה<sup data-n=\"4073\">71</sup> דאיתא במדרש כמה דברים ברא הקב\"ה ולא בחר אלא אחד מהם, ברא כמה ארצות ולא בחר אלא בא\"י כמ\"ש כי לי<sup data-n=\"4074\">76</sup> כל הארץ<sup data-n=\"4075\">73</sup>, כמה אומות ברא ולא בחר אלא בישראל כמ\"ש כי לי ישראל<sup data-n=\"4076\">74</sup> יעקב בחר לו יה<sup data-n=\"4077\">75</sup>, יבא ישראל שנאמר עליהם כי לי ישראל ויקבלו את הארץ שנ' כי לי הארץ עכ\"ל<sup data-n=\"4078\">72</sup>. נמצא שהארץ שייך לישראל דווקא. ולהבין זה דהנה כתי' זורע צדקות<sup data-n=\"4079\">77</sup> כו' שתומ\"צ נמשלו לזריעה כמ\"ש אור זרוע לצדיק<sup data-n=\"4080\">78</sup>",[["4059","57","<b>אחד הי' אברהם</b>: יחזקאל לג, כד."],["4060","58","<b>נש\"י עבמ\"ח</b>: ראה ב\"ר פ\"א, ד. שע\"ת קטו, ב. תו\"ח שמות ח\"א לב, ב ובהערה 248."],["4061","59","<b>בנים אתם להוי'</b>: פ' ראה יד, א."],["4062","60","<b>חלק הוי' עמו</b>: האזינו לב, ט."],["4063","61","<b>להפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א. סה\"מ תרכ\"ט ע' פח ואילך. וש\"נ. מאמר ד\"ה זאת חוקת התורה ש\"פ פרה תשכ\"ו."],["4064","62","<b>שנתאווה. . דירה בתחתונים</b>: ראה תניא רפל\"ו (ובהנסמן בליקוט פירושים לשם). ביאוה\"ז תזריע עב, ג. מאמרי אדה\"א הנחות תקע\"ז ע' שכט. שערי אורה צז, ב. לקמן מאמר ד\"ה אם בחוקותי הג' (קרוב לסופו) פיסקא אך הנה ידוע. סה\"מ תרל\"ח ע' לט הערה 138."],["4065","63","<b>שישראל הם מתקשראן. . בקוב\"ה</b>: ראה זהר אחרי עג, א."],["4066","64","<b>ונגלה כבוד הוי'</b>: ישעי' מ, ה."],["4067","65","<b>וכ\"ז. . לעשותם</b>: כ\"ה בהכת\"י."],["4068","66","<b>היום לעשותם</b>: ואתחנן ז, יא."],["4069","67","<b>יפה שעה אחת</b>: ראה אבות פ\"ד, מי\"ז."],["4070","68","<b>גוי אחד בארץ</b>: ראה תו\"א וישב כז, סע\"ד. מאמר ד\"ה הוא הי' אומר תרל\"א [קונט' בר מצוה תרנ\"ג ע' לט על יד הערה 87]. סה\"מ תרכ\"ט ע' רכח. וש\"נ. לקמן בפסקאות הבאות. מאמר ד\"ה את שבתותי תרי\"ב על יד הערה 64."],["4071","69","<b>דנסב\"ת</b>: ס\"י פ\"א, מ\"ז."],["4072","70","<b>סוף מעשה עבמ\"ת</b>: ע\"פ פיוט לכה דודי."],["4073","71","<b>וזאת הארץ. . לנחלה</b>: מסעי לד, ב [ושם: זאת]."],["4074","76","<b>כי לי הארץ</b>: בהר כה, כג."],["4075","73","<b>כי לי כל הארץ</b>: יתרו יט, ה."],["4076","74","<b>כי לי ישראל</b>: בהר כה, נה [ושם: בנ\"י]."],["4077","75","<b>יעקב בחר לו יה</b>: תהלים קלה, ד."],["4078","72","<b>וזאת. . דאיתא במדרש. . עכ\"ל</b>: כ\"ה בהכת\"י. ראה במד\"ר פ\"ג, ח. באוה\"ת (האזינו בהוספות) כאן ע' א'תתקלג: כמ\"ש במד\"ר פ' מסעי דרפ\"ד א' [פכ\"ג, יא] ע\"פ זאת הארץ. . אמר הקב\"ה הארץ שלי כו' וישראל שלי כו' שלי לשלי."],["4079","77","<b>זורע צדקות</b>: ברכת יוצר."],["4080","78","<b>אור זרוע לצדיק</b>: תהלים צז, יא."]]],[4801940437,"שאור התומ\"צ נזרע למטה. והענין הוא דכמו שבזריעה הגשמי' שכשזורעין גרעין אחד נצמח מזה אילן שלם כך ע\"י קיום התומ\"צ למטה בגשמי' ממשיכים אא\"ס למטה שלא לפ\"ע העבודה כמו בתפילין ממשיכים הקב\"ה מניח תפילין<sup data-n=\"4081\">79</sup> בציצית ממשיכים ל\"ב נ\"ח<sup data-n=\"4082\">80</sup> בסוכה מקיפים עליונים<sup data-n=\"4083\">81</sup> וכמו\"כ בלולב ואתרוג שזה רק כמו הזריעה שהצמיחה הוא לא לפ\"ע הזריעה כך ע\"י קיום התומ\"צ ממשיכים שלא לפ\"ע העבודה, לכן דכמו שהזריעה בגשמי' צ\"ל בארץ דווקא שבלא ארץ לא יגדל ולא יצמח כלל כך מה שממשיכים מבחי' הוי' אחד ע\"י תומ\"צ צ\"ל בארץ דווקא (... והענין הוא דכמו שבגשמי' הארץ הוא מוצא מהעלם אל הגילוי מפני שבה דווקא מלובש הכח הצומח רק שהגרעין הוא מעלה מ\"ן לכח הצומח אשר בארץ ובהעלאת מ\"ן המשכת מ\"ד ולכן נגלה עי\"ז הכח הצומח המלובש בה, כך דווקא בארץ הגשמי למטה מלובש בזה מעצמות א\"ס הפשוט מצד נסב\"ת רק שהוא בהעלם וכשמקיים תומ\"צ למטה ה\"ז מעלה מ\"ן לאא\"ס המלובש למטה שיאיר בבחי' גילוי למטה, ומצד שסוף מעשה עבמ\"ת לכן עי\"ז הוא ממשיך מבחי' עצמות למטה שיאיר בבחי' גילוי מאחר שזה הי' תחלת כוונתו שיהפוך חושך התחתון לאור ולהיות לו דירה בתחתונים. ..) שע\"י הארץ דווקא נגלה הוי' אחד למטה.\n<b>דהנה</b> איתא בסידור בבהמ\"ז<sup data-n=\"4084\">82</sup> מה שאנו אומרים על הארץ שהנחלת לאבותינו<sup data-n=\"4085\">83</sup>, והקשו שם איך אנו אומרים זה עכשיו שאין לנו הארץ שנמסר לזרים, ותירץ שם שקאי על ארץ העליונה, שארץ עליונה אנו יורשים גם עכשיו כמ\"ש ועמך כולם צדיקים<sup data-n=\"4086\">84</sup> לעולם ירשו ארץ שהו\"ע ארץ עליונה, כמ\"ש התהלך<sup data-n=\"4087\">85</sup> לפני ה' בארצות החיים<sup data-n=\"4088\">86</sup> ב' ארצות ארץ התחתון ובחי' ארץ עליונה<sup data-n=\"4089\">87</sup>, וזהו גוי אחד בארץ דהפי' הוא ע\"י הארץ הם ממשיכים הוי' אחד והמכוון הוא ע\"י הארץ העליונה שהיא משפיע גילוי אלקו' למטה שהוא מקור נש\"י (... ובאמת הפי' גוי אחד בארץ ע\"י ב' ארצות דוקא שע\"י קיום התומ\"צ למטה בארץ הגשמי עי\"ז מגלה ארץ העליונה גילוי אלקו', וזהו התהלך לפני הוי' בארצות החיים ע\"י ב' ארצות דווקא שארץ הגשמי מגיע לבחי' ארץ העליונה שהוא בחי' מלכות<sup data-n=\"4090\">88</sup> ובחי' מלכות מגיע לבחי' ארץ חפץ",[["4081","79","<b>הקב\"ה מניח תפילין</b>: ברכות ו, א. ראה גם תו\"א מקץ לה, ב. סה\"מ תרכ\"ז ע' מה. וש\"נ. ע' קיא. וש\"נ."],["4082","80","<b>בציצית ממשיכים ל\"ב נ\"ח</b>: ראה זח\"ג תוספת שא, א. מאמרי אדה\"א בראשית ע' שצד. וש\"נ."],["4083","81","<b>בסוכה מקיפים עליונים</b>: ראה ביאוה\"ז אמור פ, ב. הנסמן בתו\"ח בא ח\"א קיד, א. מאמרי אדה\"א דברים ח\"ד ע' א'שנו ובהנסמן שם. סה\"מ תרכ\"ז ע' תכא."],["4084","82","<b>איתא בסידור בבהמ\"ז</b>: קיא, א. וראה ג\"כ לקו\"ת עקב טז, ג."],["4085","83","<b>על הארץ שהנחלת לאבותינו</b>: בסידור שם: על הארץ הטובה אשר נתן לך — ועל הכל (עקב ח, י)."],["4086","84","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["4087","85","<b>התהלך</b>: וכ\"ה בסמוך. וכנצ\"ל: אתהלך."],["4088","86","<b>אתהלך לפני ה' בארצות החיים</b>: תהלים קטז, ט."],["4089","87","<b>ב' ארצות. . ארץ עליונה</b>: מובא בשם הזהר במאמרי אדה\"א במדבר ח\"ב ע' תקעא. תו\"ח משפטים ח\"ב רצה, ב."],["4090","88","<b>ארץ. . מלכות</b>: ראה זהר תוספתא בראשית לא, ב."]]],[4801940475,"שהוא בחי' עתיק סעהא\"ס<sup data-n=\"4091\">89</sup> בחי' מל' דא\"ס כי מל' עולה עד הכתר<sup data-n=\"4092\">90</sup> ולבחי' פנימי' הכתר<sup data-n=\"4093\">91</sup> כידוע. ..).\n<b>וזהו</b> השמים שמים לה'<sup data-n=\"4094\">92</sup> והארץ נתן לבני אדם כי אדם קאי על תומ\"צ כמ\"ש ועל דמות הכסא<sup data-n=\"4095\">93</sup> דמות כמראה אדם ובני אדם קאי על נש\"י המקיימים תומ\"צ לכן נתן להם את הארץ שמה שממשיכים הוי' אחד ע\"י תומ\"צ הוא דווקא ע\"י הארץ כנ\"ל [... ופי' גוי אחד בארץ הפי' הוא כך שממשיכים הוי' אחד ע\"י תומ\"צ למטה בארץ שענין התומ\"צ הוא רק להפכה חשל\"נ ונמצא שנכלל הכל בבחי' הוי' אחד, וגם ע\"י הארץ דווקא מצד שבארץ הגשמי יש כח זו שכשמקיים בה תומ\"צ ממשיכים מבחי' הוי' אחד מצד שבה מלובש מבחי' הוי' אחד בהעלם מצד נסב\"ת וסוף מעבמח\"ת לכן כשנשלם הסוף מעשה ממשיכים מבחי' מח' תחלה ונעשה לו דירה בתחתונים, אך מאין נמצא לו הכח לכ\"ז לבוא להתבוננות של הוי' אחד ולקיים התומ\"צ למטה להעלות הכל לבחי' אחד שיהי' נכללים בהוי' אחד הוא מחמת שמקבל מבחי' ארץ העליונה שבחי' ארץ העליונה נותן לו כח המעלה מ\"ן לבוא לבחי' התבוננות של הוי' אחד ולקיים התומ\"צ וזהו גוי אחד בארץ ע\"י הארץ שהיא ארץ עליונה, ונמצא שמתחלה מקבל מבחי' ארץ עליונה כח המעלה מ\"נ ואח\"כ בא לבחי' אתדל\"ת לבחי' התבוננות של הוי' אחד ומאחר שמשיג לבחי' הוי' אחד שהכל הוא רק הוי' ואין שום מציאות בלעדו ית' אז הוא בא לקיום התומ\"צ בגשמי' ומעלה הכל לבחי' אחד ומהפך חשל\"נ ובאתדל\"ת אתדל\"ע<sup data-n=\"4096\">94</sup>, ואתדל\"ת זו מגיע עד עצמות א\"ס הפשוט מחמת סוף מעבמח\"ת ובקיום התומ\"צ בגשמי' למטה בהארץ הזו הגשמי מגיע לבחי' ארץ חפץ שהו\"ע מל' דא\"ס ואז הוא בא לבחי' אהבה רבה אהבה בתענוגים אך כל הגילוים שאח\"כ הכל הוא ג\"כ ע\"י ארץ העליונה בחי' מל' דאצי' וזהו לעולם ירשו ארץ, ולפי זה מ\"ש התהלך לפני הוי' בארצות ב' ארצות קאי על מל' דאצי' ומל' דא\"ס כנ\"ל, ונמצא שפי' גוי אחד בארץ הפי' הוא שע\"י הארץ הן ע\"י הארץ התחתון ע\"י קיום התומ\"צ או ע\"י הארץ העליונה נעשים אז בבחי' אחד שאז נכללים בבחי' הוי' אחד, והגם שמבואר לעיל שמצד שרשם ומקורם הם ג\"כ בבחי' אחד, אך בבחי' אחד יש ג\"כ ב' ענינים כמו שהוא למע' מתייחד בע\"ס והעיקר בחי' אחד הוא מה שמתייחד למטה בז' רקיעי' וארץ שהנשמה מצד שרשה כמו שהיא למע' אינה נכללת בבחי' אחד זו רק דווקא למטה ע\"י הארץ התחתון והארץ העליונה עד שמגלה בה מבחי' ארץ חפץ ואז הוא בא לבחי' ומדריגה היותר עליונה, ופי' מה אתם עשאוני חטיבה אחת פי' שעושין אותי לשבח בעולם שאין רואים שום מציאות רק אותי לכן אתם אומרים הוי' אחד שהוי' הוא אחד ואין שום מציאות אחר,",[["4091","89","<b>סעהא\"ס</b>: סוף עולם הא\"ס."],["4092","90","<b>מל' עולה עד הכתר</b>: ראה גם תו\"ח בא ח\"א קכה, א. תצוה ח\"ב שכג, א. בראשית מא, ד. מאמרי אדה\"א דברים ח\"ג ר\"ע תתקלב."],["4093","91","<b>מל' עולה. . פנימי' הכתר</b>: ראה גם שה\"א ק, א. מאמרי אדה\"א נ\"ך ע' תרו. מאמר דור לדור מכ\"ק אדה\"א קה\"ת תשנ\"ב ס\"ע 12."],["4094","92","<b>השמים שמים לה'</b>: תהלים קטו, טז."],["4095","93","<b>ועל דמות הכסא</b>: יחזקאל א, כו."],["4096","94","<b>ובאתדל\"ת אתדל\"ע</b>: ראה זהר לך פח, א. תו\"ח שמות ח\"א מא, א ובהערה 189."]]],[4801940510,"כך אני אעשה אתכם כו' וקורא לנש\"י ג\"כ גוי אחד שכמו שאתם מייחדים אותי בעולם כך אני ג\"כ מייחד אתכם בעולם שכל העולמות מתייחדים ונכללים בנש\"י ע\"י שמהפכים הכל מחל\"נ, ונמצא שהארץ מקבל מבחי' הוי' אחד ע\"י נשמות ונשמות מקבלים מבחי' הוי' אחד ע\"י הארץ ומקבלים זה מזה ואז שניהם נכללים בבחי' אחד משא\"כ זה בלא זה לא הי' באים לבחי' ומדריגו' אחד האמיתי כנ\"ל וד\"ל. וזהו ג\"כ מה אתם כו' אף אני כו' פי' מאחר שאתם עשאוני חטיבה אחת ומייחדים אותי בכם אז אתם מתייחדים ג\"כ בארץ שמאחר שמתבוננים בהוי' אחד אז הם ממשיכים הוי' אחד למטה בארץ ג\"כ ומתייחדים בארץ ע\"י תומ\"צ כנ\"ל. ..]. וזהו וזאת המצוה אשר ציווה הוי' אלקי' אתכם לעשות בארץ כו' שמע ישראל כו' שענין ק\"ש הוא כללות המצות<sup data-n=\"4097\">95</sup> וכללות המצוות אינה שייך רק לארץ דווקא כנ\"ל [... והענין הוא שבכדי שיבוא להתבוננות דשמע לבחי' הוי' אחד הוא מקבל תחלה מבחי' ארץ העליונה כנ\"ל ואח\"כ יבוא מזה לקיום התומ\"צ למטה בארץ הגשמי ובאתדל\"ת אתדל\"ע מגיע לבחי' ארץ חפץ והגילוי מלמע' למטה הוא ג\"כ ע\"י ארץ העליונה בחי' מל' דאצי', ונמצא שכ\"ז הוא שייך רק לבחי' ארץ דווקא ולכן כתי' לעשות בארץ דווקא. ..].\n<b>וזהו</b> אשריך ארץ שמלכך בן חורין שכשארץ הגשמי למטה מקבל מבחי' הארץ העליונה הגילוי של הוי' ע\"י תומ\"צ כנ\"ל אז הוא בן חורין שמאיר בה מבחי' חורין עילאין מבחי' אני הוי' לא שניתי<sup data-n=\"4098\">96</sup>, משא\"כ שכשאינה מקבלת מבחי' ארץ העליונה שכשאין נעשה למטה קיום התומ\"צ אז אוי לה שמקבלת מבחי' אלקי' ואינו מאיר בה מבחי' הוי' רק ע\"י ממוצעים בחי' נער שש\"ע ואז אין גילוי אלקו' למטה. וזהו שבר\"ה אז הוא לה' הארץ שבר\"ה נמשך גילוי אלקו' על כל השנה מה שיקיים תומ\"צ בכל השנה ונמצא שאז הוא הגילוי כללית של כל השנה לכן אז הארץ הוא רק לה' שמאיר בהארץ מבחי' הוי' אחד, וזהו ארץ אשר הוי' אלקי' דורש אותה מראשית השנה שבר\"ה הוי' דורש את הארץ, וזהו מראשית כי ראשית חכ' כמ\"ש הוי' בחכ' יסד ארץ<sup data-n=\"4099\">97</sup> כונן שמים בתבונה שהארץ שרשה מבחי' חכ', אך בכל השנה אינו מאיר בה מבחי' שרשה ומקורה כ\"א ע\"י תומ\"צ, ולכן בר\"ה מאיר בה מבחי' ראשית חכ' מבחי' הוי' מבחי' שרשה ויסודה, וזהו ג\"כ מ\"ש כי הוא על ימים יסדה שאז מאיר בהארץ מבחי' ים כי ים וארץ הוא עלמא דאתגלי' ועלמא דאתכסי'<sup data-n=\"4100\">99</sup> ובבחי' עלמא דאתכסי' שם הוא תכלית הביטול משא\"כ בחי' ארץ אין שם כ\"כ ביטול אבל בר\"ה מאיר בה מבחי' ימים מבחי' יסדה שעלמא דאתכסי' הוא מקור של עלמא דאתגלי' ובר\"ה מאיר בה מבחי' שרשה ומקורה, וזהו ועל נהרות יכוננהו<sup data-n=\"4101\">98</sup> כי נהר היוצא מעדן הוא בחי' נהר דבינה<sup data-n=\"4102\">100</sup> עלמא דאתכסי' היוצא מעדן מבחי' חכ\"ע<sup data-n=\"4103\">101</sup>",[["4097","95","<b>ק\"ש הוא כללות המצות</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' רנה. שע\"ת מא, א. המשך תערב ח\"ג ע' א'תמא וע' א'תמג."],["4098","96","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["4099","97","<b>הוי' בחכ' יסד ארץ</b>: משלי ג, יט."],["4100","99","<b>ים וארץ הוא עלמא דאתגלי' ועלמא דאתכסי'</b>: ראה גם לעיל ע' פב."],["4101","98","<b>כי הוא על ימים יסדה. . ועל נהרות יכוננהו</b>: תהלים כד, ב [ושם: יכוננה]."],["4102","100","<b>נהר היוצא מעדן. . דבינה</b>: בראשית ב, י. ראה תו\"א משפטים עה, ד: כמ\"ש בזהר פ' אמור [צט, א]. לקמן מאמר ד\"ה והתהלכתי תרט\"ו ובהערה 154."],["4103","101","<b>מעדן מבחי' חכ\"ע</b>: ראה גם לעיל ע' קז. לקמן מאמר ד\"ה את שבתותי תרי\"ב על יד הערה 34. ד\"ה והתהלכתי תרט\"ו על יד הערה 155. ד\"ה רפאיני תר\"ח על יד הערה 9. תו\"ח בשלח ח\"א קמא, א ובהערה 98."]]],[4801940540,"ובר\"ה מאיר בה מבחי' נהר ומבחי' חכ\"ע כמבואר לעיל ואז הארץ הוא רק לה' וזהו ומלאה שהוא לשון מכה\"כ<sup data-n=\"4104\">102</sup> שאז הוא מלא מבחי' גילוי אלקו' עד שאין נראה העולם כלל ליש ומציאות משא\"כ כשמקבלת ע\"י ממוצעים אז כתיב ויושבי בה שיש מציאות עולמות, וזהו תבל כי תבל הוא גימ' ב\"פ ארי'<sup data-n=\"4105\">103</sup> כי בעת הקרבת הקרבנות הי' יורד<sup data-n=\"4106\">104</sup> כדוגמת ארי' דאכיל קרבנין<sup data-n=\"4107\">105</sup> ויש ב' בחי' ארי' דיצי' וארי' דבריאה ובכלל הוא נער שש\"ע שזהו בחי' ממוצעים, כי לה' הארץ קאי על א\"י ותבל קאי על שאר ארצות<sup data-n=\"4108\">106</sup> ששאר ארצות מקבל רק ע\"י ממוצעים, ובאמת כתי' לה' בפתח שבאמת הוא הכל לה' אפי' בחי' תבל וזהו בחי' פ’תח שהוא שימוש להורות שהכל הוא לה' רק בגילוי בארץ מאיר בה מבחי' הוי' משא\"כ שאר ארצות וזהו דרך כלל ובפרט הוא בכל ר\"ה מאיר בכל הארץ מבחי' לה' כו' וד\"ל.\n<b>מי</b> יעלה<sup data-n=\"4109\">107</sup> בהר ה' ומי יקום במקום קדשו כו' שקאי על יו\"כ ופי' שבר\"ה הארץ מקבל רק מבחי' הוי' כנ\"ל משא\"כ ביו\"כ מאיר מבחי' הר הוי' שהוא בחי' לפני הוי', שיש ב' בחי' הוי' כמ\"ש הוי' הוי' פסיק טעמ'<sup data-n=\"4110\">108</sup>, וב' בחי' הוי' הוא בחי' ג\"ע התחתון וג\"ע העליון כמ\"ש כל ישראל יש להם חלק לעוה\"ב<sup data-n=\"4111\">109</sup> נמצא שמקבלים רק חלק אחד ולפעמים כתי' כל השונ' הלכות מובטח לו שהוא בן עוה\"ב<sup data-n=\"4112\">110</sup> שיורש כולה וזהו ב' בחי' הוי' הנ\"ל שלפעמים הוא מקבל רק מבחי' הוי' דלתתא ולפעמים הוא מקבל גם מבחי' לפני הוי', ובכלל בר\"ה העולמות אינם מקבלים רק מבחי' הוי' דלתתא וזהו לה' הארץ שהארץ אינה מקבל רק מבחי' לה' משא\"כ ביו\"כ הארץ מקבל גם מבחי' לפני הוי' וזהו בחי' מקום קדשו שהוא בחי' הנה מקום איתי, כי יש ב' בחי' מקום כמ\"ש ברוך המקום<sup data-n=\"4113\">111</sup> שהוא בבחי' השתל' אבל בחי' הנה מקום אתי הוא בחי' שלמע' מהשתל' שהוא בחי' הוי' דלעילא ובזוהר נק' אתר טמיר וגניז<sup data-n=\"4114\">112</sup>, ולבחי' מקום זה אינה יכול' להגיע עדיין בר\"ה שעל מקום כזו כתי' מי יעלה כו'",[["4104","102","<b>מכה\"כ</b>: ישעי' ו, ג. ראה אוה\"ת תהלים כרך ג ע' א'רפב."],["4105","103","<b>תבל. . ב\"פ ארי'</b>: ראה גם לקו\"ת במדבר יח, ד. יט, ד. מאמרי אדה\"ז כתובים ח\"א ס\"ע רה וע' רטז. אוה\"ת שמות ע' צז. ואתחנן ע' קל. שה\"ש כרך ב ע' תקיג. סה\"מ תרנ\"ג ע' רעו. תרס\"ט ע' ה."],["4106","104","<b>הקרבת הקרבנות הי' יורד</b>: כנצ\"ל: אש — ראה תו\"כ ויקרא א, ז. ערובין סג, א. מאמרי אדה\"א דברים ח\"ד ע' א'תפה. וש\"נ."],["4107","105","<b>ארי' דאכיל קרבנין</b>: ראה זהר בהקדמה ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שה\"א עט, ב הערה 13."],["4108","106","<b>לה' הארץ. . א\"י ותבל. . שאר ארצות</b>: ראה אוה\"ת תהלים כרך ג ע' א'רפז. וש\"נ."],["4109","107","<b>מי יעלה</b>: ראה גם אוה\"ת תהלים שם ע' א'רצב ואילך."],["4110","108","<b>הוי' הוי' פסיק טעמ'</b>: תשא לד, ו. זהר אד\"ר נשא קלח, רע\"א. ראה הנסמן במאמרי אדה\"א נ\"ך ע' תקעז. תו\"ח בשלח ח\"א קנז, ב הערה 361."],["4111","109","<b>כל ישראל יש להם חלק לעוה\"ב</b>: סנהדרין ר\"פ חלק צ, ב. ראה גם אוה\"ת תהלים כאן ע' א'רצב. חנוכה כרך ה ע' תתקנה. סה\"מ תרכ\"ז ע' שנח. תרס\"ו ע' תלג."],["4112","110","<b>כל השונ'. . בן עוה\"ב</b>: מגילה כח, ב. ראה בהדרושים שבהערה שלפנ\"ז."],["4113","111","<b>ברוך המקום</b>: מדות ספ\"ה. ראה גם לקמן מאמר ד\"ה והתהלכתי בתוככם תר\"ב ובהערה 41."],["4114","112","<b>אתר טמיר וגניז</b>: זהר פקודי רלב, א."]]],[4801940563,"ומי יקום כו' שלא כל אדם יכולים להגיע לבחי' מקום זו, לבד במשה ובאברהם וביעקב הי' הגילוי מבחי' מקום זו כמ\"ש במשה הנה מקום אתי כו' ובאברהם כתי' וירא את המקום<sup data-n=\"4115\">113</sup> כו' וביעקב כתי' ויפגע במקום<sup data-n=\"4116\">114</sup> כו' אבל לבד ג' אילו אינם יכולים להגיע למעלה זו כ\"א כמ\"ש לקמן נקי כפים ובר לבב<sup data-n=\"4117\">115</sup> שלא יהי' לו שום פני' ולגרמי' אפי' אהבה שהיא חייך הוא ג\"כ לגרמי' רק שיהי' אהבתו להוי' עצמו, וזהו אשר לא נשא לשוא נפשו בלא שום פני' ולגרמי' ולא נשבע למרמה שהיא השבועה שמשביעין אותו תהי צדיק<sup data-n=\"4118\">116</sup> ואל תהי רשע שיקיים השבועה כמו שהוא בד' תנאים אלו<sup data-n=\"4119\">117</sup> אז יכול להגיע לבחי' מקום קדשו הנ\"ל, נמצא שאפי' בחי' צדיקים המקיימים תומ\"צ בשלימות אינם יכולים להגיע למעלה זו עדיין כ\"א כשימצא בהם ד' תנאים הנ\"ל.\n<b>אך</b> כתי' במקום שבעת\"ש עומדים<sup data-n=\"4120\">118</sup> צדיקים גמורים אינם יכולים לעמוד שבבחי' תשובה בחילי' יתיר<sup data-n=\"4121\">119</sup> מגיע לבחי' מקום זו ודווקא ג\"כ בד' תנאים כמ\"ש יעזוב רשע דרכו<sup data-n=\"4122\">120</sup> כו' שהיא בחי' עזיבת החטא, ולא נאמר עוד אלקינו למעשה ידינו<sup data-n=\"4123\">121</sup> כו' שהוא בחי' עקירת הרצון, אחרי שובי נחמתי<sup data-n=\"4124\">122</sup> כו' שהוא קבלה על להבא, קחו עמכם דברים<sup data-n=\"4125\">123</sup> ושובו אל הוי' כו' שהוא ווידוי בפה, בד' תנאים אלו שבתשובה מגיע לבחי' מקום זו. נמצא שבר\"ה שלא הי' לו עדיין בחי' תשובה הנ\"ל אינו מגיע אז לבחי' מקום הנ\"ל רק דווקא ביו\"כ מחמת התשובה של עשי\"ת שמקודם אז מגיע ביו\"כ לבחי' מקום הנ\"ל [... והגם שמבואר לעיל שבקיום התומ\"צ בגשמי' למטה בארץ מגיע ג\"כ לבחי' ארץ חפץ שהוא בחי' מל' דא\"ס בחי' לפני הוי', אך זהו רק שמעורר למע' בבחי' ארץ חפץ הנ\"ל מצד נסב\"ת אבל הגילוי בנפש אינה מאיר רק מבחי' הוי' דלתת' שורש התומ\"צ שהוא בחי' אא\"ס המלובש בתומ\"צ, ולמע' הוא בחי' אא\"ס המלובש בע\"ס דאצי' בחי' אדם שעל הכסא, ובעבודה הוא בחי' הביטול של הוי' אחד ביטול במציאות וזה הכל בא לו ע\"י קיום התומ\"צ שממשיך מבחי' הוי' למטה בנפש, אבל שיהי' הגילוי בנפשו מבחי' ארץ חפץ הנ\"ל זה אינו כ\"א שיהי' לו ד' תנאים הנ\"ל של צדיקי' כמבואר לעיל, וזה לא כל אדם יכול להגיע לזו אך ע\"י תשובה יכול להגיע לזו ג\"כ שיהי' הגילוי בנפשו מבחי' ארץ חפץ הנ\"ל בחי' אהבה בתענוגים בחי' מקום קדשו הנ\"ל, לכן ביו\"כ ע\"י התשובה של עשי\"ת שמקודם מתעלה כל אחד לבחי' מקום קדשו הנ\"ל. ..]. וזהו מה",[["4115","113","<b>וירא את המקום</b>: וירא כב, ד."],["4116","114","<b>ויפגע במקום</b>: ויצא כח, יא."],["4117","115","<b>נקי כפים ובר לבב</b>: תהלים כד, ד."],["4118","116","<b>שמשביעין אותו תהי צדיק</b>: נדה ל, ב."],["4119","117","<b>בד' תנאים אלו</b>: ראה גם אוה\"ת תהלים כאן ע' א'רצג."],["4120","118","<b>במקום שבעת\"ש עומדים</b>: ראה ברכות לד, ב. לקו\"ש נצבים כרך יד ע' 361 וע' 363. תו\"ח שמות ח\"א מא, א. וש\"נ. אוה\"ת בחוקותי כרך ב ע' תרעה ואילך. לקמן מאמר ד\"ה אם בחוקותי הג' על יד הערה 140. ביאור והתהלכתי בתוככם תר\"ב על יד הערה 33 ואילך."],["4121","119","<b>בחילי' יתיר</b>: ראה זהר ח\"ש קכט, ב. אגה\"ת פ\"ח. מאמרי אדה\"א בראשית ע' קעב. וש\"נ. תו\"ח שמות ח\"א לז, א. וש\"נ. לעיל ע' קפח ואילך."],["4122","120","<b>יעזוב רשע דרכו</b>: ישעי' נה, ז."],["4123","121","<b>ולא נאמר עוד אלקינו למעשה ידינו</b>: הושע יד, ד."],["4124","122","<b>אחרי שובי נחמתי</b>: ירמי' לא, יח."],["4125","123","<b>קחו עמכם דברים</b>: הושע יד, ג."]]],[4801940580,"שדרז\"ל כאן בישראל ערש\"מ<sup data-n=\"4126\">124</sup> כאן באין ישראל ערש\"מ, כי בפ' השני' לא כתי' מאודך לכן לא נק' עדיין עושין רש\"מ משא\"כ בפ' ראשונה כתי' בכל מאדך<sup data-n=\"4127\">125</sup> שזו בחי' בע\"ת שמגיעים לבחי' מקום קדשו הנ\"ל, וזהו ג\"כ מ\"ש זה דור דורשיו מבקשי פניך יעקב סלה כי בחי' יעקב הוא בחי' הקל קול יעקב<sup data-n=\"4128\">126</sup> קול התומ\"צ, גם בחי' יעקב הוא בחי' רחמים<sup data-n=\"4129\">127</sup> רבים שמגיע לפנימי' ועצמות א\"ס כמ\"ש ואשא אתכם על כנפי נשרים<sup data-n=\"4130\">128</sup> ואביא אתכם אלי ממש לעצמותי ומהותי ע\"י התעוררות ר\"ר על נפשו, וגם בעסק התומ\"צ מגיע ג\"כ לפנימי' ועצמות כמ\"ש פניך יעקב, אך הגילוי מפנימי' אינו כ\"א ע\"י תשובה כמבואר לעיל.\n<b>ויבוא</b> מלך הכבוד<sup data-n=\"4131\">129</sup> הוא בחי' סוכות, שר\"ה ויו\"כ הוא הכל מלמטה למעל' [... שהוא בחי' עלי' המקבלים שבר\"ה עולים כללות העולמות לבחי' הוי' הב' וביו\"כ לבחי' לפני הוי' שהוא הכל בדרך עלי' שהתחתון עולה ונכלל בהעליון אבל בסוכות הוא מלמעלמ\"ט שהעליון יורד למטה. ..] אבל בסוכות הוא מלמעלמ\"ט וזהו ויבוא מלמעלמ\"ט מלך הכבוד כי יש ב' בחי' כבוד כבוד עילאה וכבוד תתאה<sup data-n=\"4132\">130</sup> כי כבוד בגימ' ל\"ב<sup data-n=\"4133\">131</sup> שהוא בחי' ל\"ב נה\"ח<sup data-n=\"4134\">132</sup> שהוא בחי' ל\"ב שבהשתל' ול\"ב נהח\"כ שלמע' מהשתל', וזהו שביקש משה הראיני נא את כבודיך<sup data-n=\"4135\">133</sup> שביקש הגילוי של ל\"ב נהח\"כ שלמעל' מהשתל', אך באמת זה אינו יכול להיות בבחי' ראיה וזהו וראית את אחורי<sup data-n=\"4136\">134</sup> ופני לא יראו שאינו יכול להיות בבחי' ראיה כ\"א בחי' ל\"ב נהח\"כ של השתל', וזהו קש\"ת הראהו לו<sup data-n=\"4137\">135</sup> שהוא בחי' אחוריים בלבד, וגם בתומ\"צ מלובש בהעלם מבחי' כבוד עילאה הנ\"ל אבל לא בבחי' ראיה בגילוי, אך ע\"י תשובה ממשיכי' מבחי' כבוד עילאה הנ\"ל בגילוי ולכן בסוכות אז הגילוי מבחי' כבוד עילאה הנ\"ל ועיקר הגילוי יהי' לע\"ל כמ\"ש יהי כבוד ה' לעולם<sup data-n=\"4138\">136</sup> ישמח הוי' כו' שמח לא נאמר אלא ישמח<sup data-n=\"4139\">137</sup> לע\"ל שאז יהי' עיקר הגילוי ועכשיו בכל סוכות הוא ג\"כ מעין הגילוי דלע\"ל ולכן בסוכות הוא ג\"כ בחי' שמחה מעין דלע\"ל שענין השמחה הוא גילוי ההעלם ובסוכות מאיר אז מהעלם אל הגילוי מבחי' אתר טמיר וגניז הנ\"ל כנ\"ל וד\"ל.",[["4126","124","<b>כאן בישראל ערש\"מ</b>: ראה ברכות לה, ב. ראה גם לקמן מאמר ד\"ה והתהלכתי בתוככם תר\"ב על יד הערה 36 ואילך."],["4127","125","<b>בפ' השני'. . בכל מאדך</b>: ואתחנן ו, ה. ראה גם לקמן שם הערה 40. מאמרי אדה\"א הנחות תקע\"ז ע' רפו. וש\"נ."],["4128","126","<b>הקל קול יעקב</b>: תולדות כז, כב."],["4129","127","<b>יעקב. . רחמים</b>: ראה זהר לך פז, ב. תניא פמ\"ה. הנסמן במאמרי אדה\"א בראשית ע' קנו."],["4130","128","<b>ואשא אתכם על כנפי נשרים</b>: יתרו יט, ד."],["4131","129","<b>ויבוא מלך הכבוד</b>: תהלים כד, ז. ט."],["4132","130","<b>כבוד עילאה וכבוד תתאה</b>: ראה לקו\"ת שה\"ש מז, ב ואילך. לעיל מאמר ד\"ה בסוכות תשבו תרכ\"ב הערה 83."],["4133","131","<b>כבוד בגימ' ל\"ב</b>: זהר רע\"מ צו לג, א."],["4134","132","<b>כבוד. . ל\"ב נה\"ח</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"א מערכת כבוד. מאמרי אדה\"א בראשית ע' ג ואילך. דברים ח\"ב ע' שפ. וש\"נ."],["4135","133","<b>הראיני נא את כבודיך</b>: תשא לג, יח."],["4136","134","<b>וראית את אחורי</b>: תשא לג, כג."],["4137","135","<b>קש\"ת </b>[ קשר של תפילין]<b> הראהו לו</b>: ראה ברכות ז, א."],["4138","136","<b>יהי כבוד ה' לעולם</b>: תהלים קד, לא."],["4139","137","<b>שמח לא נאמר אלא ישמח</b>: ראה ויק\"ר פ\"כ, ב."]]],[4801940124,"<b>בס\"ד ליל ש\"ק פ' נשא שנת הנ\"ל [תר\"ט]</b>\n<b>כי</b> תבאו אל הארץ ושבתה הארץ<sup data-n=\"4140\">1</sup> שבת להוי'<sup data-n=\"4141\">2</sup> כו' שש שנים תזרע שדך<sup data-n=\"4142\">3</sup> כו' ובשנה השביעית שבת שבתון כו' שדך לא תזרע<sup data-n=\"4143\">4</sup> כו'. הנה לכאורה י\"ל מה שהקדים לומר ושבתה הארץ קודם שש שנים תזרע שדך כו' דהלא שנה השביעי' הוא אחר שש שנים שקדמו. אך הנה באמת פי' ושבתה הארץ הוא לשון נייחא ולכן אמר תיכף כאשר תבאו אל הארץ יהי' לה מנוחה והמנוחה הוא מן התימה<sup data-n=\"4144\">5</sup> ושממון שהי' לה כי הנה כתי' והארץ היתה תוהו<sup data-n=\"4145\">6</sup> שענין תוהו הוא מלשון תימה ושממון כדפירש\"י<sup data-n=\"4146\">7</sup> והו\"ע הסתלקות האור מן הכלי כמו אשתומם כשעה חדא<sup data-n=\"4147\">8</sup> מצד שנסתלק אור שכלו למקור השכל מצד הקושי' שהקשה לו, כן התימה ושממון שבארץ הוא מצד הסתלקות האור ממנה, ולזה א' כאשר יבואו בנ\"י אל הארץ אז תיכף תהי' לה מנוחה, וענין המנוחה הוא היפוך השממון והיינו התיישבות האור בכלי', וזה יהי' תיכף אשר יבואו בנ\"י לארץ.\n<b>אך</b> להבין הטעם לזה איך יהי' מנוחה לארץ ע\"י שיבאו בנ\"י לתוכה. ילה\"ק ענין אור זרוע לצדיק<sup data-n=\"4148\">9</sup> וענין הזריעה של האור הוא ע\"י תומ\"צ, כי הנה כל המצות נק' בשם זריעה<sup data-n=\"4149\">10</sup> ובפרט מצות הצדקה כמ\"ש זרעו לכם לצדקה<sup data-n=\"4150\">11</sup> כו' וכן נאמ' ויזרע יצחק<sup data-n=\"4151\">12</sup> וארז\"ל אין זריעה אלא צדקה<sup data-n=\"4152\">13</sup> כו'. ולהבין ענין זה יש להבין ענין המאמר דת\"ח עוסקים בבנינו של עולם<sup data-n=\"4153\">14</sup> שנא' וכל בנייך לימודי ה'<sup data-n=\"4154\">16</sup> כו' א\"ת בנייך אלא בונייך<sup data-n=\"4155\">17</sup>. ויש להבין מהו בניינו של עולם<sup data-n=\"4156\">15</sup> גם מה שא' בניך לשון נוק'",[["4140","1","<b>כי תבאו אל הארץ ושבתה הארץ</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nלהבא לקמן ראה גם מאמר ד\"ה וידבר וכו' ושבתה תקס\"ב (מאמרי אדה\"ז תקס\"ב ח\"א ע' קפה־ ח\"ב ע' תלב־ סהמ\"צ להצ\"צ ע' קסז). אוה\"ת ויקרא כרך ג ע' תתעז־ כרך ד ע' א'קכה.\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י כאן."],["4141","2","<b>כי תבאו. . ושבתה. . להוי'</b>: בהר כה, ב [בדילוג]."],["4142","3","<b>שש שנים תזרע שדך</b>: בהר שם, ג."],["4143","4","<b>ובשנה השביעית. . לא תזרע</b>: שם שם, ד."],["4144","5","<b>התימה</b>: ג: התהו."],["4145","6","<b>והארץ היתה תוהו</b>: בראשית א, ב."],["4146","7","<b>כדפרש\"י</b>: בראשית שם."],["4147","8","<b>אשתומם כשעה חדא</b>: דניאל ד, טז. שבת מז, א. ראה סידור שער נפ\"א צב, ג. שע\"ת מד, ב. מאמרי אדה\"א דברים ח\"ד ע' א'תט. וש\"נ."],["4148","9","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["4149","10","<b>כל המצות. . זריעה</b>: ראה תנחומא שלח טו. במדב\"ר פי\"ז, ה. תו\"א שמות נג, ג. אוה\"ת (יהל אור) תהלים ע' שנב ואילך."],["4150","11","<b>זרעו לכם לצדקה</b>: הושע י, יב."],["4151","12","<b>ויזרע יצחק</b>: תולדות כו, יב."],["4152","13","<b>אין זריעה אלא צדקה</b>: ראה תד\"א זוטא פ\"א."],["4153","14","<b>דת\"ח עוסקים בבנינו של עולם</b>: ראה ברכות סד, א. שבת קיד, א. מאמרי אדה\"א דברים ח\"ד ע' א'תכו. וש\"נ."],["4154","16","<b>וכל בנייך לימודי ה'</b>: ישעי' נד, יג."],["4155","17","<b>א\"ת בנייך אלא בונייך</b>: ברכות סד, א."],["4156","15","<b>שנא'. . של עולם</b>: ג: ליתא. וכנראה נשמט מפני תיבות הדומות: עולם. . עולם. ראה גם סה\"מ תרל\"ב ח\"ב ע' תלח."]]],[4801940188,"כו'. ילה\"ק ענין המשנה בעש\"מ נברא העולם<sup data-n=\"4157\">18</sup> והלא במאמר א' יכול להבראות אלא להפרע כו' וליתן שכר טוב לצדיקים כו' ויש בזה שני פירושים<sup data-n=\"4158\">19</sup> הא' דמאמר א' הוא גבוה מעשרה מאמרות<sup data-n=\"4159\">20</sup> דהנה העשרה מאמרות הוא בחי' דבר ה' שהם צירו\"א<sup data-n=\"4160\">21</sup> שנבראו בהם שמו\"א שיש בהם ריבוי צירופים לאין שיעור שמזה נמשך ריבוי התחלקות הנבראים לאין שיעור כי אעפ\"י שאין בתו' רק עשרה מאמרות מ\"מ העשרה מאמרות מתחלפים בחילופי' ותמורות רבות ע\"י האלפ\"א בית\"א דאלב\"ם [שיש בהם רל\"א שערים פנים ורל\"א שערים אחור כמבואר בעמק המלך<sup data-n=\"4161\">22</sup> כו'] וכל חילוף הוא<sup data-n=\"4162\">23</sup> מורה על ירידת האור והתעלמותו ע\"ד ועד בחילופי אתוון אחד<sup data-n=\"4163\">24</sup> כו' ולכן נמשך ריבוי הנבראים לאין שיעור כו', אך מאמר א' הוא במח' הכולל לכל המאמרות כידוע שהמח' תוכל לסקור ריבוי צירופים הנאמרים וסקירה<sup data-n=\"4164\">25</sup> א' ולכן אותיות שבמח' נק' אתוון רברבין כי ענין הגדולה ברוחניות הוא שהוא כולל יותר, ולכן בשבת אומרים אל<sup data-n=\"4165\">26</sup> אדון<sup data-n=\"4166\">27</sup> ובחול אומרים אל ברוך כו' כי הנה בחול העולמות מקבלים חיותם מבחי' צירו\"א הדיבור לכן החיות שבהם מצומצם יותר אך בשבת נעשה עליות העולמות מצד עליות הדיבור למקורו כו'. וא\"כ קשה מאין העולמות מקבלים חיותם והי' צריך שיחזרו לאין ואפס כו'. אך באמת שבשבת מאירים אותיות המח'<sup data-n=\"4167\">28</sup> לכן מקבלים אז חיות ואור יותר גדול דהיינו מבחי' אותיות המח' ולכן נק' עליות העולמות מצד שמתעלים לקבל חיות יותר נעלה מבימות החול כו'. וזהו הטעם שאומרים בשבת אל אדון כו' שנעשה ונמשך מכל אות דכ\"ב אותיות פסוק שלם בכמה תיבות מצד שאז מאירים אותיות המח' הכוללי' בעצמם יותר משא\"כ בימות החול שאינם מאירים רק אותיות הדיבור לכן אומרים אל ברוך כו' שמכל אות נעשה ונמשך רק תיבה אחת בלבד כו'. וזה\"ע מאמר א' שהוא בחי' המח' הכוללת לכל ריבוי פרטי המאמרות והצירופי' והחילופי' המתהווים מהם בדיבור שכולם נכללים בבחי' ביטול במח' א' וכמא' במח' א' נבראו כל העולמות<sup data-n=\"4168\">29</sup> כו', והנה בחי' מאמר א' הוא ג\"כ ענין המאמ' דבראשית<sup data-n=\"4169\">30</sup> כי בראשית ת\"י בחוכמתא<sup data-n=\"4170\">31</sup> והיינו ענין החכ\"ע שהוא בחי' מח' א' ובה נכללו כל פרטי הנבראי' בבחי' העלם וביטול כו'. וזהו\"ע את השמים ואת הארץ הנזכר במאמר דבראשית כי",[["4157","18","<b>בעש\"מ נברא העולם</b>: ראה אבות רפ\"ה."],["4158","19","<b>שני פירושים</b>: פי' הב' לקמן בפיסקא ומעתה יובן."],["4159","20","<b>דמאמר א' הוא גבוה מעשרה מאמרות</b>: ראה פרדס שער טעם האצילות ש\"ב, פ\"ו. מד\"ש שבהערה 30. רמ\"ז תולדות קלה, א. אוה\"ת חנוכה ח\"ב ע' שכט. ויקהל ע' ב'צט. ישעי' כרך ב ע' תתמ ואילך. סה\"מ תרכ\"ז ע' רפג ואילך. סה\"מ תרנ\"ט ס\"ע קמב ואילך. תש\"ד ע' 67 ואילך. וראה גם בסמוך בהערה 30. ולהעיר מפרדס שבהערה 40."],["4160","21","<b>צירו\"א</b>: צירופי אותיות."],["4161","22","<b>רל\"א שערים. . בעמק </b>[ג: בס' עמק]<b> המלך</b>: שער שעשועי המלך ש\"א, פ\"ה. ראה לקמן מאמר ד\"ה את שבתותי תקצ\"ח הערה 20."],["4162","23","<b>הוא</b>: ג: ליתא."],["4163","24","<b>ועד. . אחד</b>: ראה זהר תרומה קלד, א. מאמר ד\"ה זה במאמרי אדה\"א דברים ח\"א ע' רכד. וש\"נ."],["4164","25","<b>וסקירה</b>: ג: בדיבור בסקירה."],["4165","26","<b>אתוון רברבין. . אל אדון</b>: ראה זהר תרומה קלב, א. לקו\"ת ויקרא יז, ב. מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרסט. ביאוה\"ז להצ\"צ כרך ב ע' תתב ואילך."],["4166","27","<b>בשבת אומרים אל אדון </b>[ג ניתוסף: כו']: בברכת יוצר."],["4167","28","<b>בחול העולמות. . בשבת. . המח'</b>: ראה לקו\"ת ש\"ש סו, ג. ביאוה\"ז שם ע' תתג."],["4168","29","<b>במח' א' נבראו כל העולמות</b>: ראה זהר שמות כ, א. שם תוספות רעו, סע\"ב. מאמרי אדה\"א קונטרסים ע' תלג. וש\"נ."],["4169","30","<b>מאמר א'. . המאמ' דבראשית</b>: ראה אוה\"ת בהר כאן ע' תתעח: כן פי' במד\"ש ד\"צ סע\"א [אבות רפ\"ה ד\"ה ואפשר עוד לפרש]. מאמרי אדה\"א דברים ח\"ב ע' תעז. וש\"נ. תו\"ח וארא ח\"א פא, ג והערה 634."],["4170","31","<b>בראשית ת\"י בחוכמתא</b>: בראשית א, א. כ\"ה בכ\"מ בדא\"ח ובתרגום שם: בחוכמא — סה\"מ מלוקט ג ע' קסד."]]],[4801940245,"השמים והארץ הם ב' כללים הכוללי' לכל ההשתל' מריש כ\"ד עד סוף כ\"ד [ובחי' את ואת הוא לרבות<sup data-n=\"4171\">32</sup> כל הפרטים המסתעפי' מהם כמארז\"ל את השמים לרבות תולדותיהם<sup data-n=\"4172\">33</sup> ואת הארץ לרבות תולדותיהם כו'] וכולם נכללים במאמר הראשון שהוא מאמר דבראשית כו' וד\"ל.\n<b>ומעתה</b> יובן ענין פי' המשנה והלא במאמ' א' יכול להבראות והיינו שהי' יכול לישאר הבריאה במאמ' א' שהוא בחי' מח' א' הנ\"ל ולא הי' נמשך מהעלם אל הגילוי בעשרה מאמרות באותיות הדיבור, ולזה תירץ שאם הי' נשאר הבריאה במא' א' היו כל העולמות בתכלית הביטול ולא היו נראים ליש כלל<sup data-n=\"4173\">34</sup> ולא הי' מציאות הבחירה וא\"כ לא הי' שייך ענין שכר ועונש כלל ולזה נמשכו העשרה מאמרות בכדי שישתלשלו העולמות בבחי' יש וממילא יהי' הבחירה ויהי' מציאות שכר ועונש כו' וזש\"א ליפרע כו' וליתן שכר טוב כו'.\n<b>ומעתה</b> יובן ענין ת\"ח עוסקים בבנינו של עולם לפי' זה כי הנה עולם נק' בחי' המל'<sup data-n=\"4174\">35</sup> מקור כל העולמות שהוא בחי' דבר הוי' מקור העשרה מאמרות וחילופים ותמורות שלהם כו'. ובנינו של עולם היינו שממשיכים במדת המל' מבחי'<sup data-n=\"4175\">36</sup> מאמר א' הנ\"ל שהוא בחי' מאמר דבראשית שהוא בחי' חכ\"ע ורצוה\"ע [בחוכמא ובקדמין כת\"י ות\"א כו'], והיינו ע\"י עסק התומ\"צ שהתו' היא בחי' חכ\"ע והמצות הם בחי' רצונו ית' והוא וחכמתו א'<sup data-n=\"4176\">37</sup> והוא ורצונו א'<sup data-n=\"4177\">38</sup> וא\"כ ע\"י תומ\"צ הנעשים בבחי' עולם ממשיכי' רצונו וחכמתו המיוחד במהו\"ע ית' לבחי' המל' הנק' עולם כנ\"ל וזהו בנינו ש\"ע [וזהו\"ע בוניך לשון נוק' כי המל' הוא בחי' מקבל מאוא\"ס המלובש בי\"ס דאצי' כמאמ' איהו אמת ואיהי אמונה<sup data-n=\"4178\">39</sup> כו' וד\"ל]. והנה פי' הב' במשנה<sup data-n=\"4179\">40</sup> והלא",[["4171","32","<b>את. . לרבות</b>: ראה ירושלמי ברכות פ\"ט, ה\"ה. פסחים כב, ב."],["4172","33","<b>את השמים לרבות תולדותיהם</b>: ראה רש\"י בראשית א, יד. ב\"ר פ\"א, יד. תנחומא בראשית — באבער — ח. תוד\"ה ואת חגיגה יב, ב."],["4173","34","<b>ולא היו נראים ליש כלל</b>: ג: ליתא."],["4174","35","<b>עולם. . המל'</b>: ראה זהר רע\"מ פינחס רמב, סע\"א ואילך. פרדס שער עה\"כ שכ\"ג, פט\"ז מערכת עולם. מאו\"א מערכת עולם אות יב."],["4175","36","<b>מבחי'</b>: ג: ליתא."],["4176","37","<b>והוא וחכמתו א'</b>: תניא פ\"ב."],["4177","38","<b>והוא ורצונו א'</b>: ראה תניא פל\"ח [נ, ב]. פ\"מ [נד, ב. נה, סע\"א]."],["4178","39","<b>איהו אמת ואיהי אמונה</b>: ראה זהר בלק קצח, ב."],["4179","40","<b>פי' הב' במשנה</b>: ראה פרדס שער טעם האצילות ש\"ב, פ\"ה הובא באוה\"ת נצבים ר\"ע א'רמו. מדרש שמואל אבות רפ\"ה ד\"ה והחסיד קרוב לסופו וע\"ד האמת. סה\"מ תרנ\"ט ע' קמו. תש\"ד ע' 73. מאמר ד\"ה וכל בניך ש\"פ וישלח תשכ\"ז. אוה\"ת תשא ע' א'תתנא. קרח ע' תש. ישעי' כרך ב ע' תתמ ואילך. סה\"מ תרכ\"ו ע' קמד. תרל\"ב ח\"ב ע' תלח ואילך. ולהעיר מפרדס שבהערה 20."]]],[4801940298,"במאמ' א' יכול להבראות כו' היינו שאם הי' העולם נברא במאמ' א' הי' נמוך יותר כי מאמר א' הוא בחי' המל' והיינו בחי' חכ' שבמל' [ובו מאיר מבחי' חכ\"ע כנ\"ל לפי פי' הראשון כו'], לזאת נברא העולם בעשרה מאמרות בכדי שיהי' העולם במדריגה יותר גבוה כי בשעת בריאת העולמות האירו הי\"ס עצמן עד הכתר ועד בכלל בבחי' המל' ובהם נברא העולם וא\"כ העולם ביוקר ובחשיבות ולכן כאשר מקלקלין אותה ח\"ו העונש יותר גדול וכאשר מתקנים אותו השכר יותר גדול כמשל כאשר נותנים לאדם חפץ יקר לשומרו שכר השמירה הוא יותר. והנה פי' זה הוא מסכים עם פי' הפשוט כי לפי פי' הפשוט הוא כך שלכן נברא העולם בעשרה מאמרות בכדי שיהי' העולם דבר יקר וחשוב יותר, אך לפי פשוטו ממש אינו מובן<sup data-n=\"4180\">41</sup> וכי כאשר יתנו בעד איזה חפץ עשרה זהובים בזה הוא יקר יותר כיון שיכולין לקנותו בעד זהב א' כן בענין זה כיון שיכול העולם להיות נברא במאמר א' מהו יוקרו וחשיבותו כאשר נברא בע\"מ. אך לפי הנ\"ל הענין מובן שהכוונה שהאירו בו כל הע\"מ שלמעל' מבחי' המל' שהוא עצמו' הע\"ס דאצי' וא\"כ העולם הוא במדריגה גבוה יותר [וכן כאשר נפרש מאמ' א' לפי פי' זה כפי שפירשנו לפי פי' הא' דקאי על עצמות החכ\"ע נוכל לפרש ג\"כ שהעשרה מאמרות הם גבוהים מבחי' מאמר א' והיינו כי העש\"מ הם שרש הי\"ס דאצי' כמ\"ש כלולי' בעצמות הכתר שלמעלה מבחי' חכ\"ע כו' וד\"ל].\n<b>וביאור</b> הדברים ילה\"ק מארז\"ל שכינור של מקדש<sup data-n=\"4181\">42</sup> הי' של שבע נימין שנא' שובע שמחות את פניך<sup data-n=\"4182\">43</sup> וכינור של משיח הוא של שמונה נימין שנאמר למנצח על השמינית<sup data-n=\"4183\">44</sup> וכינור של לע\"ל הוא של עשרה נימין שנאמר בנבל עשור זמרו לו<sup data-n=\"4184\">45</sup>, וביאור הדברים הנה שיר הלוים הוא על היין דווקא כמארז\"ל אין אומרים שירה אלא על היין<sup data-n=\"4185\">46</sup>, כי הנה יין הוא מגלה ההעלם והו\"ע גילוי הפנימי' כמו חכמת אדם תאיר פניו<sup data-n=\"4186\">47</sup> כו' כי הנה יין הוא משמח אלקים<sup data-n=\"4187\">48</sup> וענין השמחה הוא גילוי המצפון והמוסתר ונעלם בשם אלקי' שיבא לידי גילוי מהעלמו, ונמצא שע\"י שיר הלוים גרמו שיהי' בכללות נש\"י בחי' שמחה ותענוג בעבודת התו' והמצות שלהם<sup data-n=\"4188\">49</sup> שזהו גילוי הפנימי' דייקא שזהו העיקר כידוע דתחת אשר לא עבדת<sup data-n=\"4189\">50</sup> בשמחה ובטוב לבב ועבדת את אויביך<sup data-n=\"4190\">51</sup> הגם שעושה כל התומ\"צ כ\"ז שאינו עושה אותם<sup data-n=\"4191\">52</sup> בשמחה יוכל להיות שהאויבים ימשלו עליו מצד שאין בזה גילוי פנימי' כו'. וזהו אור צדיקים ישמח<sup data-n=\"4192\">53</sup>",[["4180","41","<b>אך לפי פשוטו ממש אינו מובן</b>: ראה גם מדרש שמואל כאן."],["4181","42","<b>שכינור של מקדש</b>: ראה ערכין יג, ב."],["4182","43","<b>שובע שמחות את פניך</b>: תהלים טז, יא."],["4183","44","<b>למנצח על השמינית</b>: תהלים יב, א."],["4184","45","<b>בנבל עשור זמרו לו</b>: תהלים לג, ב."],["4185","46","<b>אין אומרים שירה אלא על היין</b>: ברכות לה, א."],["4186","47","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["4187","48","<b>יין. . משמח אלקים</b>: ס' שופטים ט, יג. ראה גם לקמן מאמר ד\"ה והתהלכתי בתוככם תר\"ב על יד הערה 55."],["4188","49","<b>שלהם</b>: ג: ליתא."],["4189","50","<b>דתחת אשר לא עבדת </b>[ג ניתוסף: כו']: תבוא כח, מז."],["4190","51","<b>ועבדת את אויביך</b>: תבוא שם, מח. ראה גם מאמרי אדה\"א שמות ח\"א ע' ס. נ\"ך ס\"ע צ ואילך."],["4191","52","<b>אותם</b>: ג: ליתא."],["4192","53","<b>אור צדיקים ישמח</b>: משלי יג, ט."]]],[4801940348,"כו'<sup data-n=\"4193\">54</sup> ונר רשעים ידעך, כי נר הוא נר מצוה שהוא המצות שעושין ידעך<sup data-n=\"4194\">55</sup> שקופץ האור ומסתלק מן הכלי מצד שאינם עושים אותה בשמחה, משא\"כ צדיקים שעושין בשמחה עי\"ז ממשיכים האור בבחי' התיישבות בתוך הכלי שזהו\"ע אור צדיקים ישמח כו'. והנה במקדש לא האיר גילוי הפנימי' בבחי' מאמר א' רק מבחי' ז' מדות עליונים<sup data-n=\"4195\">56</sup> דאצי' עצמן שלמעלה ממדת המל' [או מבחי' ז\"מ שבכתר שלמעלה מן החכמ' כנ\"ל] משא\"כ בימות המשיח יאיר מבחי' הבינה שנק' שמינית<sup data-n=\"4196\">57</sup>, ולע\"ל יאיר מבחי' הכתר עצמו [ולפי הנ\"ל הוא כשב\"כ עצמו כו' וד\"ל] והיינו שיאיר מדריגה גבוה בעולמות אותה שהאירה בתחילת הבריאה שאז האיר מדריגה גבוה מאוד כמארז\"ל אור שהי' מאיר בשימ\"ב<sup data-n=\"4197\">58</sup> כו' כמשי\"ת לקמן.\n<b>והנה</b> שמעתי מפיו<sup data-n=\"4198\">59</sup> שאמר<sup data-n=\"4199\">60</sup> שיש פי' ג' בכתבי אדמו\"ר נבג\"מ<sup data-n=\"4200\">61</sup> שמפרש שם דמאמר א' הוא בבחי' התוהו<sup data-n=\"4201\">62</sup>, וא' שע\"כ לומר שכוונתו הוא ג\"כ מבחי' המל' כמ\"ש<sup data-n=\"4202\">63</sup> בבחי' התוהו שהייתה רק נקודה א' בלבד ולכן נק' מאמר אחד, ופי' זה ג\"כ מסכים לפי' הפשוט כ\"א הי' נברא העולם מבחי' התוהו דמל' הי' בבחי' נמוכה יותר אך כאשר נברא בעש\"מ שהוא מבחי' המל' כמו שנבנית<sup data-n=\"4203\">64</sup> בפרצוף שלם בבחי' התיקון שנמשך בה האור דבחי' שם מ\"ה החדש<sup data-n=\"4204\">65</sup> שהוא בחי' מדריגה גבוה ולכן העולם במדריגה גבוה יותר כנ\"ל לפי פי' הב' כו' וד\"ל. והנה לפי פי' הנ\"ל בשעת הבריאה האיר בעולמות מדריגה גבוה מאד<sup data-n=\"4205\">66</sup> והיינו מבחי' העשרה מאמרות שבעצמות הכתר שהאירו בעצמו' הי\"ס דאצי' ומבחי' אור זה נמשך בגילוי בבחי' עולם הנברא מאין ליש, ונמצא שבששת ימ\"ב שהי' העולם במדריגה גבוה מאוד וזהו ג\"כ ענין הנאמר בזוהר [ויקרא דף י\"א ע\"ב]<sup data-n=\"4206\">67</sup>, ע\"פ עשרה עשרה הכף<sup data-n=\"4207\">68</sup> עשרה למתן תו' עשרה למע\"ב ומונה שם כנגד דבור אנכי הוא מאמר יהי אור וכנגד דיבור לא יהי' לך הוא מאמר יהי רקיע כו' וכנגד דבור זכור<sup data-n=\"4208\">69</sup> את יום השבת כו' הוא מאמר תדשא<sup data-n=\"4209\">70</sup> כו', ונמצא שכמו שבשעת מ\"ת האיר בחי' הי\"ס דאצי' כמ\"ש מקבלים",[["4193","54","<b>כו'</b>: כ\"ה בהכת\"י."],["4194","55","<b>כי נר. . ידעך</b>: ג: ליתא. וכנראה נשמט מפני תיבות הדומות: ידעך. . ידעך."],["4195","56","<b>עליונים</b>: ג: ליתא."],["4196","57","<b>הבינה שנק' שמינית</b>: ראה גם זהר רע\"מ פינחס רמה, ב. מאמרי אדה\"א דברים ח\"ד ע' א'שדמ. וש\"נ. לעיל ס\"ע קנו ואילך. וש\"נ."],["4197","58","<b>אור שהי' מאיר בשימ\"ב</b>: ראה חגיגה יב, א. ב\"ר פי\"ב, ו. פי\"א, ב. לקו\"ש בראשית כרך כה ע' 4 בהערות."],["4198","59","<b>שמעתי מפיו</b>: מכ\"ק אדמו\"ר הצ\"צ."],["4199","60","<b>שאמר</b>: ג: ליתא."],["4200","61","<b>בכתבי אדמו\"ר נבג\"מ</b>: כ\"ק אדה\"א [בהנחתו מדרוש כ\"ק אדה\"ז]."],["4201","62","<b>דמאמר א' הוא בבחי' התוהו</b>: מאמרי אדה\"ז תקס\"ב ח\"א ע' קפט. אוה\"ת בהר כרך ג ע' תתצא. ולהעיר מסהמ\"צ להצ\"צ ע' 340 (שהוא אותו המאמר)."],["4202","63","<b>כמ\"ש</b>: ג: כמו שהיא."],["4203","64","<b>שנבנית</b>: ג: שהיא נבנית."],["4204","65","<b>שם מ\"ה החדש</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ב."],["4205","66","<b>ולכן העולם. . מאד</b>: ניתוסף ע\"פ ג."],["4206","67","<b>בזוהר [ויקרא דף י\"א ע\"ב]</b>: ג: בזוהר."],["4207","68","<b>עשרה עשרה הכף</b>: נשא ז, פו."],["4208","69","<b>אנכי. . לא יהי' לך. . זכור</b>: יתרו כ, ב. ג. ח."],["4209","70","<b>יהי אור. . יהי רקיע. . תדשא</b>: בראשית א, ג. ו. יא."]]],[4801940395,"מעצמו' שרשיהם שבכתר שזהו\"ע עשה\"ד [וכידוע בפע\"ח דבשבועות ז\"א עולה עד הדיקנא דא\"א<sup data-n=\"4210\">71</sup> כמו במנחה דשבת כו' וד\"ל] כן בחי' זאת האירו בע\"מ שנמשכו בעת בריאת העולמות כו' וד\"ל, וזהו ג\"כ מארז\"ל אור שהי' מאיר בשי\"ב האיר מסוף העולם ועד סופו שהוא בחי' העש\"מ הנ\"ל שלמעל' ממאמר א' [וכפי המבואר במ\"א ברשימה דכי עמך מקו\"ח<sup data-n=\"4211\">72</sup> שיש ב' פירושים בבחי' אור זה הא' חסד דז\"א והב' חסד דא\"א כו' ושניהם אמת וכ\"ה בפי' העש\"מ ג\"כ הא' דקאי על י\"ס דאצי' שלמעל' ממאמר א' דמל' כו' והב' דקאי על י\"ס דכתר שלמעל' אפי' מח\"ע כנ\"ל וד\"ל]. [ושמעתי מפיו שהוא ג\"כ ענין הנזכר בס\"י בל\"ב נ\"ח חקק כו' את עולם<sup data-n=\"4212\">73</sup> כו', ונמצא שהאירו בעת בריאת העולם כל הל\"ב נתיבות כו', וידוע שענין הל\"א נתיבות הוא שם אל<sup data-n=\"4213\">74</sup> חלק העשירי מחצי התחתון שבכתר שהוא בחי' י\"ש<sup data-n=\"4214\">75</sup>. אך בנתיב הל\"ב הוא פנימי' אבא<sup data-n=\"4215\">76</sup> שבו מאיר מחצי העליון שבכתר כידוע דפנימי' אבא הוא פנימי' עתיק<sup data-n=\"4216\">77</sup> וכ\"ז האיר בשעת בריאת העולם נמצא שהי' העולם במדריגה גבוה מאוד וראי' לדבר ממלך המשיח שבזמנו יהי' העולם בתכלית העלי' כתי' בי' ישכיל עבדי ירום ונשא וגבה מא\"ד אותיות אד\"ם<sup data-n=\"4217\">79</sup> כו' והיינו כמו שהי' בזמן אדה\"ר קודם החטא<sup data-n=\"4218\">78</sup> כו' וד\"ל].\n<b>והנה</b> ארז\"ל שאור הראשון שהי' מאיר בשימ\"ב כו' גנזו לצדיקי' לע\"ל<sup data-n=\"4219\">80</sup>, ומבואר בשם הבעש\"ט שגנזו בתו'<sup data-n=\"4220\">81</sup>, וא\"כ ע\"י עסק התומ\"צ ממשיכים אור הראשון שיאיר בעולמות, וענין אור הראשון הוא העש\"מ שבכתר כנ\"ל. וזהו שעוסקים בבנינו של עולם והיינו שע\"י עסק התומ\"צ ממשיכים מבחי' העש\"מ בבחי' מאמר א' הנ\"ל שהוא מקור העולמות [ולפי פי' הא' הוא בהיפוך שע\"י עסק התומ\"צ ממשיכים",[["4210","71","<b>בפע\"ח דבשבועות ז\"א. . דא\"א</b>: שחה\"ש שכ\"ג, פ\"א."],["4211","72","<b>ברשימה דכי עמך מקו\"ח</b>: לא נדפסה לע\"ע."],["4212","73","<b>בס\"י בל\"ב נ\"ח. . עולם </b>[ג: עולמו]: בתחילתו."],["4213","74","<b>הל\"א נתיבות הוא שם אל</b>: ראה גם אוה\"ת בראשית כרך ג ע' 1136. מיכה ע' תצא. סה\"מ תרכ\"ט ע' רלד. תרל\"ח ס\"ע קצד ואילך. וש\"נ. בהערה הבאה."],["4214","75","<b>הל\"א נתיבות. . חלק העשירי. . י\"ש</b>: ראה גם לקו\"ת בהעלותך לו, ג. אוה\"ת בראשית שם. בהעלותך ס\"ע תיט. סה\"מ תר\"ל ס\"ע קנה. המשך והחרים תרל\"א ע' עה. סה\"מ תרל\"ב ח\"א ע' לח. ע' קנד וע' קנט. המשך וככה תרל\"ז פ\"י. סה\"מ תרל\"ח שם."],["4215","76","<b>בנתיב הל\"ב הוא פנימי' אבא</b>: ראה גם לקו\"ת בהעלותך שם. אוה\"ת מיכה ע' תצב. לך כרך ד ע' 1414. בהעלותך שם."],["4216","77","<b>דפנימי' אבא הוא פנימי' עתיק </b>[ג: ע\"י]: ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתסה. לקו\"ת נצבים מט, ד. תו\"ח שמות ח\"א כג, א הערה 951."],["4217","79","<b>ישכיל עבדי. . מא\"ד אותיות אד\"ם</b>: ישעי' נב, יג. ראה זהר רע\"מ פינחס רמו, ב. ב\"ר פ\"ח, ה. פ\"ט, יב."],["4218","78","<b>ממלך המשיח. . אדה\"ר קודם החטא</b>: ראה גם לקמן מאמר ד\"ה והתהלכתי תרכ\"ב על יד הערה 108. מאמרי אדה\"א קונטרסים ע' דש. וש\"נ. תו\"ח שמות ח\"א מז, ב ובהערה 156. אוה\"ת בחוקותי כרך ב ע' תרנב. ע' תרפא [ושם: כ\"כ בספר הגלגולים כמדומה פט\"ו]. קרח ע' תש. ברכה ע' א'תתפ. ישעי' כרך א ע' רסה [ושם: בספר הגלגולים פי\"ט]. סה\"מ תרל\"ה ח\"א ר\"ע רסו."],["4219","80","<b>גנזו לצדיקי' לע\"ל</b>: חגיגה יב, א."],["4220","81","<b>בשם הבעש\"ט שגנזו בתו'</b>: ראה לקו\"ת במדבר יח, ד ובהנסמן במ\"מ לשם. לעיל ע' קמא ובהערה 15."]]],[4801940438,"מבחי'<sup data-n=\"4221\">82</sup> מאמר אחד בעשרה מאמרות. אך שניהם אמת כו'<sup data-n=\"4222\">83</sup> כי בתו' יש ב' בחי' הא' שהוא בחי' מקור לעולמות כמא' באורייתא ברא הקב\"ה עלמא<sup data-n=\"4223\">84</sup> וכן מאמר אסתכל באורייתא<sup data-n=\"4224\">85</sup> כו' וכאומן הרואה בלוח כו' כמבואר במד\"ר ע\"פ ואהי' אצלו אמון כו' אומן<sup data-n=\"4225\">86</sup> כו'. והב' שהוא בחי' גילוי דעצמו' אוא\"ס שלמעל' מהשתל' לגמרי ולכן קדמה לעולם כו' והו\"ע אמון מוצנע ומכוסה ופדגוג<sup data-n=\"4226\">88</sup> כו' או בחי' שעשועי' יום יום<sup data-n=\"4227\">89</sup> כו' שכל בחי' אלו הם למעל' מהשתל' לגמרי<sup data-n=\"4228\">87</sup>. ולכן ע\"י עסק התו' ומצות נמשכים ב' גילויים הא' מבחי' מאמ' א' שבמח' בבחי' עש\"מ שבדיבור שהוא מבחי' מקור ההשתל' בהשתל', והב' בחי' גילוי דעש\"מ שלמעל' ממאמר א' שהוא בחי' אור הראשון כנ\"ל שלמעלה מהשתל' לגמרי ואור הנ\"ל נמשך בעולמות כו' וד\"ל כנלע\"ד בד\"א].\n<b>והנה</b> באדה\"ר כתי' ויניחהו בג\"ע<sup data-n=\"4229\">90</sup> לעבדה ולשמרה לעבדה אלו רמ\"ח מ\"ע ולשמרה אלו שס\"ה ל\"ת<sup data-n=\"4230\">92</sup> והיינו כדוגמת הגן שצריך לסקל ולעדור<sup data-n=\"4231\">93</sup> אותו ולהסיר הפסולת ואח\"כ נוטעים בו מיני מעדנים כו' כן ע\"י אמצעות הל\"ת דוחים הרע וע\"י מ\"ע ממשיכים אור ה' שגנזו כו' בג\"ע<sup data-n=\"4232\">91</sup>, והנה זה הי' עבודת אדה\"ר קודם החטא להמשיך תוס' אורות בעא\"ע מבחי' אור הראשון בג\"ע כו' אך ע\"י חטא עה\"ד נתקלקל ונתעלם האור בדורות שאחריו [וכידוע בענין וימנע<sup data-n=\"4233\">94</sup> כו' מצד דור המבול ודור הפלגה כו']. והנה אאע\"ה וכן יצחק ויעקב התחילו לתקן הקלקול ע\"י עבודתם ברוחניות כי ע\"י יחודים עליונים שפעלו בכל ימיהם המשיכו תוס' אורות מבחי' אור הגנוז בעולמות וממילא ניתוסף אורות בג\"ע. וזהו שנא' עליהם בדברי רז\"ל בירח שנולדו<sup data-n=\"4234\">95</sup> בו זיוותני עולם<sup data-n=\"4235\">96</sup> כי הנה ענין זיו השכינה שבג\"ע שנהנין הנשמות<sup data-n=\"4236\">97</sup> ממנו אין הכוונה זיו והארה בלבד רק הכוונה פנימי' הזיו והאור כמו חכמת אדם תאיר פניו<sup data-n=\"4237\">98</sup> היינו שפועל זיו קלסתר הפנים שענינו זיו הפנימי כו' ולכן נק' זיוותני עולם<sup data-n=\"4238\">99</sup>",[["4221","82","<b>העש\"מ בבחי'. . מבחי' </b>: ג: ליתא. וכנראה נשמט מפני תיבות הדומות: מבחי'. . מבחי'."],["4222","83","<b>כו'</b>: ג: ליתא."],["4223","84","<b>באורייתא ברא הקב\"ה עלמא</b>: ראה זהר בהקדמה ה, א. שמיני לה, ב."],["4224","85","<b>אסתכל באורייתא</b>: ראה זהר תולדות קלד, א. תרומה קסא, א. מאמרי אדה\"א דברים ח\"א ע' רעט."],["4225","86","<b>במד\"ר ע\"פ ואהי' אצלו אמון כו' אומן</b>: ר\"פ בראשית. משלי ח, ל."],["4226","88","<b>אמון מוצנע ומכוסה ופדגוג</b>: ראה ב\"ר שם."],["4227","89","<b>שעשועי' יום יום</b>: משלי שם."],["4228","87","<b>ולכן קדמה. . לגמרי</b>: ג: ליתא. וכנראה נשמט מפני תיבות הדומות: לגמרי. . לגמרי."],["4229","90","<b>ויניחהו בג\"ע</b>: בראשית ב, טו."],["4230","92","<b>לעבדה אלו רמ\"ח מ\"ע. . שס\"ה ל\"ת</b>: ראה זהר בראשית כז, א. תרומה קסה, ב. הנסמן במאמרי אדה\"א דברים ח\"ב ע' שצט־ בראשית ע' עג־ קונטרסים ע' שי."],["4231","93","<b>הגן שצריך לסקל ולעדר</b>: ראה גם זהר שמות ד, א."],["4232","91","<b>לעבדה. . בג\"ע</b>: ניתוסף ע\"פ ג."],["4233","94","<b>בענין וימנע</b>: איוב לח, טו. ראה גם זהר לך עח, ב. סה\"מ תרס\"ח ע' קלז."],["4234","95","<b>בדברי רז\"ל בירח שנולדו</b>: ג: בירח זיו האתנים שנברא."],["4235","96","<b>בירח שנולדו בו זיוותני עולם</b>: ר\"ה יא, א."],["4236","97","<b>זיו השכינה. . הנשמות</b>: ראה ברכות יז, א. אוה\"ת ח\"ש כרך ד ע' תשפח ואילך. סה\"מ תר\"ס ע' קלב."],["4237","98","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["4238","99","<b>זיוותני עולם</b>: ראה גם ביאוה\"ז להצ\"צ ע' שנה. אוה\"ת ויקרא כאן ע' תתעט ואילך. סה\"מ תר\"ס שם."]]],[4801940476,"היינו שבמעשיהם המשיכו פנימי' הזיו והאור בבחי' עולם כו', אך הם לא עשו רק התחלת התיקון כו' אבל גמר התיקון נעשה ע\"י תומ\"צ שקבלו עמב\"י בה\"ס<sup data-n=\"4239\">100</sup> כי ע\"י תומ\"צ בגשמיות<sup data-n=\"4240\">101</sup> ממשיכים אור הראשון הגנוז בהם שיהי' נמשך למטה בבי\"ע כמו למעלה בעולם האצי' ולכן נמשך ממילא ע\"י תומ\"צ אורות בגעה\"ת והעליון וכנ\"ל בענין עוסקי' בבנינו ש\"ע כו'. וזהו\"ע אור הזרוע לצדיק כו' וג\"כ ענין זורע צדקות<sup data-n=\"4241\">102</sup> כו' כמו זריעת הגרעין שזורעים דבר הגרוע שבפרי שאין בו טעם כלל וממנו דווקא צומח הפרי בטעם ועונג נפלא כן ע\"י תומ\"צ המתלבשים בגשמי' [כי התו' מתלבשת באותיות גשמי' וכן המצות מתלבשים בדברים גשמי' כו'] עי\"ז מצמיח תוס' אורות בתענוג נפלא לאין קץ בג\"ע העליון והתחתון כו'.\n<b>אך</b> הנה ידוע שעיקר הצמיחה הוא להוציא מן ההעלם אל הגילוי כי בגרעין יש בהעלם<sup data-n=\"4242\">103</sup> כל<sup data-n=\"4243\">104</sup> מה שנצמח ממנו לבסוף והיינו כל הפירות בטעמיהם שהם כלולי' בבחי' רוחני' של<sup data-n=\"4244\">105</sup> הגרעין אך אח\"כ יוצאים מהעלם אל הגילוי כו'. אך מי הוא המוציאם מהעלם אל הגילוי הוא כח הצומח שבארץ דייקא, אך מאין יש<sup data-n=\"4245\">106</sup> כח זה בארץ הוא מבחי' התוהו שקדם לתיקון<sup data-n=\"4246\">107</sup> [שהם בחי' אורות בלתי מוגבלים בכלים ולכן הם מעוררי' בחי' א\"ס כידוע]. ולכן יש כח בארץ להצמיח כל צמח וזהו\"ע ונתנה הארץ יבולה<sup data-n=\"4247\">109</sup>, והיינו שתתן כל כח הגנוז בה להצמיח כל צמח<sup data-n=\"4248\">108</sup>, וממילא מצמיח בתוס' ברכה כו'. כ\"ה בתומ\"צ שבחי' האורות הרוחני' דתומ\"צ ירדו מלמעלמ\"ט ומתצמצמים להתלבש בגשמיות עוה\"ז ואז כאשר נתצמצמו נתעלם מהם רוחניותם כמ\"ש<sup data-n=\"4249\">110</sup> למעל' והם כדוגמת הגרעין כו'. אך ההגשמה שנתלבשו בהם אורות הרוחני' דתומ\"צ הוא כדוגמת עפר הארץ הנותנת כח בהם שיצאו מהעלם אל הגילוי ויעלו למעל' לעורר אורות עליוני' בתוס' וריבוי ולהמשיכם בגעה\"ע והתחתון כו' וד\"ל.\n<b>אך</b> הנה ידוע שכח הצומח שבארץ גופא צריך לאדם שיעבוד את האדמה בחרישה וזריעה או בנטיעה ואז יוצאו מהעלם אל הגילוי להצמיח תוס' ברכה וכמאמר וכל שיח השדה<sup data-n=\"4250\">111</sup> כו' ואדם אין לעבוד את האדמה כו'. וביאור הדברים הנה ידוע דכח הצומח שבארץ הוא בחי' שם ב\"ן שהוא בחי' ניצוצין דעולם התהו שנפלו למטה והם המתבררי' ע\"י שם מ\"ה<sup data-n=\"4251\">112</sup> הנמשך בהם ומברר אותם ובחי' שם מ\"ה הוא",[["4239","100","<b>עמבנ\"י בה\"ס</b>: ג: בנ\"י על ה\"ס."],["4240","101","<b>בגשמיות</b>: ניתוסף ע\"פ ג."],["4241","102","<b>זורע צדקות</b>: ברכת יוצר."],["4242","103","<b>בגרעין יש בהעלם</b>: ראה גם שער האמונה צב, א ובהערה 7."],["4243","104","<b>כל</b>: ניתוסף ע\"פ ג."],["4244","105","<b>של</b>: ניתוסף ע\"פ ג."],["4245","106","<b>יש</b>: ניתוסף ע\"פ ג."],["4246","107","<b>התוהו שקדם לתיקון</b>: ראה תו\"א בשלח סה, ד. לקו\"ת אמור לז, ד. וש\"נ."],["4247","109","<b>ונתנה הארץ יבולה</b>: בחוקותי כו, ד."],["4248","108","<b>וזהו\"ע. . כל צמח</b>: ג: ליתא. וכנראה נשמט מפני תיבות הדומות: כל צמח. . כל צמח."],["4249","110","<b>כמ\"ש</b>: כמו שהם."],["4250","111","<b>וכל שיח השדה</b>: בראשית ב, ה."],["4251","112","<b>ב\"ן. . המתבררי'. . מ\"ה</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."]]],[4801940511,"בחי' האדם [כידוע דאדם בגימט' מ\"ה<sup data-n=\"4252\">113</sup> כו'<sup data-n=\"4253\">114</sup> ] וכ\"ה בעבודה האלקי' הנה בסדר התפלה שמתבונן בשבחו ש\"מ שזהו הכנה לבא למס\"נ בק\"ש שהו\"ע ביטול רצון בלבד ואח\"כ נמשך בחי' ביטול זה בכל כחות הנפש שכל ומדות בשמ\"ע הנק' תפלה והו\"ע גילוי דבחי' שם מ\"ה בנפשו ואז יוכל כל היום לברר בירורין בתומ\"צ כו' [וכן באכילת מאכלים משא\"כ קודם התפלה אסור לאכול<sup data-n=\"4254\">115</sup> וכן עסק התומ\"צ עיקרו אחר התפלה וכל האומר אין לי אלא תורה<sup data-n=\"4255\">116</sup> אפי' תו' אין לו כו'] וכ\"ה עד\"ז ענין השבת עם ששת ימים שבחי' ששת ימים הוא עסק הבירורים ע\"י תומ\"צ כו' והשבת הוא בחי' המשכת שם מ\"ה ליתן כח ועוז בימי החול לברר בירורים, ולכן מבואר בזהר הנ\"ל דמאמר זכור את יום השבת הוא כנגד מאמ' תדשא הארץ כו' כי מאמ' תדשא הוא אותיות א\"ש ד\"ת<sup data-n=\"4256\">117</sup> והו\"ע הבירורים המתבררי' ע\"י תומ\"צ המתלבשים בגשמיות שנק' עפר הארץ כו'<sup data-n=\"4257\">118</sup>. והשבת נותן כח ועוז בארץ שתוכל לבררם ולהוציאם מהעלם אל הגילוי כנ\"ל, וכמבואר בזהר שם, וענין השבת הוא ג\"כ בחי' גילוי שם מ\"ה בנפש האלקי' באופן יותר גבוה מהגילוי שבתפלה דימות החול כו' וד\"ל.\n<b>ומעתה</b> יובן ענין כי תבאו אל הארץ כו' ושבתה הארץ<sup data-n=\"4258\">119</sup> כו' להיות כי א\"י בה הוא עיקר הניצוצין שנפלו מז' מלכין קדמאין דעולם התוהו (כידוע דז' עממין הוא כנגד ז' מדות שבעולם התוהו<sup data-n=\"4259\">120</sup> כו'), והנה הניצוצין הנ\"ל נתרחקו משרשם שהם האורות דתוהו שעלו למעל' כידוע ולכן הם בבחי' תהו שהוא בחי' התימה ושממון שמורה על הסתלקות האור כנ\"ל, אך תיכף כאשר תבאו אל הארץ אז תמשיכו בה בחי' שם מ\"ה וממילא יתגלו האורות עליונים בניצוצי' המובלעי' בה וממילא ושבתה כו' שיהי' לארץ מנוחה ונייחא מן השממון שקודם מצד המשכות והתיישבות האורות בה כו'. ואז שש שנים תזרע שדך כו' שהו\"ע עבודת הבירורים שבשית אלפי שנין דהוי עלמא<sup data-n=\"4260\">121</sup> שמתבררי' ע\"י כח הצומח שבה שהו\"ע הניצוצין דעולם התוהו כנ\"ל באריכות, אך אח\"כ אמר ובשנה השביעית שבת שבתון יהי' לארץ כו' שדך לא תזרע וכרמך לא תזמור כו'. הנה להבין ענין שבת זה שכפלו פעם אחרת וע\"כ לומר שהוא בחי' יותר גבוה מבחי' שבת הראשון שיהי' תיכף בבואם לארץ כו', ומתחילה י\"ל ענין כרמך לא תזמור",[["4252","113","<b>דאדם בגימט' מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ג. לקו\"ת ושער הפסוקים להאריז\"ל בראשית ג, כ. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסז ובהנסמן במ\"מ לשם. תו\"ח בראשית ט, א הערה 14."],["4253","114","<b>כו'</b>: ג: ליתא."],["4254","115","<b>קודם התפלה אסור לאכול</b>: ראה ברכות י, ב. לעיל ע' כו ובהערה 92."],["4255","116","<b>וכל האומר אין לי אלא תורה</b>: ראה יבמות קט, ב."],["4256","117","<b>תדשא. . א\"ש ד\"ת</b>: בלקו\"ת בהר מ, ב: ”כ\"כ הש\"ך בשם הר\"ש\" והוא בס\"פ בראשית [בחלק גימטריאות יב, ד — ר' שמשון]. ברכה לג, ב [פה, ב]. תוספות השלם בראשית א, יא אות ג."],["4257","118","<b>כו'</b>: ג: כנ\"ל."],["4258","119","<b>הארץ</b>: ניתוסף ע\"פ ג."],["4259","120","<b>דז' עממין. . ז' מדות שבעולם התוהו</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תשמז. וש\"נ. תו\"ח שמות ח\"א כב, סע\"ג ובהערה 939. סה\"מ תר\"ל ע' רפח."],["4260","121","<b>שבשית אלפי שנין דהוי עלמא</b>: ראה ר\"ה לא, א. מאמרי אדה\"א בראשית ע' נג. וש\"נ."]]],[4801940541,"הנה ענין זמר יש ב' פי' הא' מלשון שירה וזמרה והב' מלשון זמיר עריצים ושניהם אמת והא בהא תלי' כי הנה ידוע ענין פסוד\"ז<sup data-n=\"4261\">122</sup> שהוא ג\"כ ענין שירה וזמרה וג\"כ להכרית יניקת החיצוני' וכמ\"ש רוממות אל בגרונם<sup data-n=\"4262\">123</sup> וחרב פיפיות בידם כי ההתבוננות מבחי' רוממות א\"ס דייקא והיינו איך שהוא קדוש ומובדל מבחי' העולמות גם בעת שהוא מלובש בהם להחיותם [כי אני הוי' לא שניתי<sup data-n=\"4263\">124</sup> פי' אפי' מצד הבריאה כו' כמבואר במ\"א] הנה מזה יתפעל בשיר וזמרה בבחי' כלות הנפש מצד עריבות ומתיקות האור כו' וממילא יהי' כריתת יניקת החיצוני' כמאמר ואתה מרום לעולם ה'<sup data-n=\"4264\">125</sup> כי הנה אויביך<sup data-n=\"4265\">126</sup> כו' יאבדו יתפרדו כל פועלי און, והנה כ\"ז הוא עכשיו שצריך לעבודת הבירורים וממילא צריך להפריד הרע בכדי שיצא אור הגנוז בו מהעלם אל הגילוי ויעלה ויוכלל בשרשו, אך לעתיד כאשר יהי' תשלום הבירורים וממילא יבוער רוח הטומאה וממילא אין צריך עוד לעבודת הבירורים ולהפריד הרע מן הטוב וזהו וכרמך לא תזמור, וטעם הדברים מצד שבשלימות הבירורים יעלה שם ב\"ן לשרשו כמו שהי' קודם הנפילה בבחי' שם ס\"ג וממילא יתגלה בחי' שם ס\"ג שלמעל' משם מ\"ה<sup data-n=\"4266\">127</sup> המברר וממילא יהי' ביטול והעברת הרע לגמרי מכל וכל וזהו\"ע שבת שבתון שיהי' לארץ שהוא בחי' גילוי דשם ס\"ג שלמעל' משם מ\"ה המברר אותו משא\"כ מש\"א בתחילה ושבתה הארץ הוא בחי' שם מה שנותן כח ועוז לברר כו', ושמעתי מפיו שבכתבי אדמו\"ר נבג\"ם מבואר ושבתה הארץ הראשון הוא עליית שם ב\"ן<sup data-n=\"4267\">128</sup> לאחר הבירור וא\"כ אינו מובן מש\"א כפל לשון אח\"כ ובשנה השביעית שבת שבתון ומוכרח לומר כנ\"ל וד\"ל.",[["4261","122","<b>זמיר עריצים. . פסוד\"ז</b>: ישעי' כה, ה. ראה זהר וילך רפד, א. לקמן מאמר ד\"ה אם בחוקותי תר\"י על יד הערה 54. מאמרי אדה\"א הנחות תקע\"ז ע' שדמ. וש\"נ. מאמרי אדה\"ז תקע\"א ע' רצז."],["4262","123","<b>רוממות אל בגרונם</b>: תהלים קמט, ו. ראה גם לקמן מאמר ד\"ה אם בחוקותי תר\"י על יד הערה 47."],["4263","124","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["4264","125","<b>ואתה מרום לעולם ה'</b>: תהלים צב, ט."],["4265","126","<b>כי הנה אויביך</b>: תהלים שם, י."],["4266","127","<b>שם ס\"ג שלמעל' משם מ\"ה</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. הנסמן במאמרי אדה\"א דברים ח\"א ע' ה הערה ד\"ה: שם."],["4267","128","<b>שבכתבי. . ושבתה. . ב\"ן</b>: מאמרי אדה\"ז תקס\"ב ח\"א ע' קעג."]]],[4801940125,"<b>תו' אדמו\"ר נאמר בפ' בהר ובחוקתי בליבאויטש שנת הנ\"ל [תקצ\"ח]</b>\n<b>את</b> שבתותי תשמרו<sup data-n=\"4268\">1</sup> ומקדשי תיראו<sup data-n=\"4269\">2</sup> אני הוי'. י\"ל מש\"א שבתותי ל' רבים, ומה שייכות ענין שמירת שבתות למורא מקדש כו'. ילה\"ק מארז\"ל אלמלא שמרו ישראל שתי שבתות<sup data-n=\"4270\">3</sup> כו' פי' שבכל שבת יש בחי' שתי שבתות כמבואר בזה\"ק שיש שבת עילאה ושבת תתאה<sup data-n=\"4271\">4</sup> כו', וענין שבת הוא אותיות תשב<sup data-n=\"4272\">5</sup> שהוא ענין עליות העולמות<sup data-n=\"4273\">6</sup> וגם עליות התומ\"צ<sup data-n=\"4274\">7</sup> שבכל ימי השבוע כו', אך מתחלה נעשה עליות דתומ\"צ שבכל יום ויום העבר בתפלה<sup data-n=\"4275\">8</sup> הבא אחרי' ונק' התפלה עולת תמיד<sup data-n=\"4276\">9</sup> ואח\"כ עליות כל התפלות נק'<sup data-n=\"4277\">11</sup> שבת<sup data-n=\"4278\">10</sup> שהוא שבת תתאה ונק' עולת שבת ואח\"כ נעשה עליות שבת תתאה בשבת עילאה וזהו עולת שבת בשבתו<sup data-n=\"4279\">12</sup> כו' וד\"ל. ולהבין ביאור הדברים הנה תחלה י\"ל ענין עליות העולמות עלי' זו למה היא הלא אין שייך עלי' רק למה שהוא בגדר מקום אבל באוא\"ס ב\"ה כתי' כי הוי' הוא אלקי'<sup data-n=\"4280\">13</sup> בשמים ממעל כו' וכמ\"ש בזוהר דלית אתר פנוי מיני'<sup data-n=\"4281\">14</sup> וא\"כ למה צריך עלי' אליו הלא הגילוי שלו יוכל להיות למטה ג\"כ כמו למעלה, וקושי' זאת יקשה ג\"כ בענין ירידת הנשמה בגוף שהוא צורך עלי'<sup data-n=\"4282\">15</sup> הלא תכלי' הכוונה אינו געה\"ת והעליון רק פנימי' הכוונה הוא",[["4268","1","<b>את שבתותי תשמרו</b>: הנחת ר\"ה מדרוש כ\"ק אדמו\"ר הצ\"צ.\nמאמר הצ\"צ נדפס בלקו\"ת בהר מא, א. וראה גם הנסמן במ\"מ לשם. מאמרי אדה\"א ויקרא ח\"ב ע' תשיט.\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י כאן."],["4269","2","<b>את שבתותי תשמרו ומקדשי תיראו</b>: קדושים יט, ל. בהר כו, ב."],["4270","3","<b>אלמלא שמרו ישראל שתי שבתות</b>: ראה שבת קיח, ב. מאמרי אדה\"א בראשית ע' מז. שמות ח\"א ס\"ע קפט ואילך. הנחות תקע\"ז ע' קכג ובהנסמן בהנ\"ל. תו\"ח בשלח ח\"א רח, ד. וש\"נ."],["4271","4","<b>שבת עילאה ושבת תתאה</b>: זהר בהקדמה ה, ב. ראה גם לעיל ע' רמח ובהערה 62."],["4272","5","<b>שבת הוא אותיות תשב</b>: ראה אגה\"ת ספ\"י. מאמרי אדה\"א דברים ח\"ד ע' א'קפ. וש\"נ. לעיל שם ובהערה 63."],["4273","6","<b>שבת. . עליות העולמות</b>: ראה ע\"ח שער פנימיות וחיצוניות ש\"מ, דרוש ג. ח. טו. תו\"ח בא ח\"א קכז, א הערה 667. לעיל ע' רמג."],["4274","7","<b>שבת. . עליות התומ\"צ</b>: ראה (בנוסף להערה 1). לקו\"ת יוה\"כ סט, ד. לעיל ע' שנג ובהערה 91. מאמרי אדה\"א שמות שם."],["4275","8","<b>עליות דתומ\"צ. . בתפלה</b>: ראה (בנוסף להערה 1). תו\"א משפטים עו, א. תרומה פ, ב. לקו\"ת כאן בהביאור מד, א־ יוה\"כ סח, סע\"ב־ ד־ שבהערה הבאה. מאמרי אדה\"א שמות ח\"א ע' רמט וע' רנב."],["4276","9","<b>התפלה עולת תמיד</b>: פינחס כח, ו. ראה (בנוסף להמצויין בהערה 1). תו\"א משפטים שם. מאמרי אדה\"ז תקס\"ט ע' רלז. לקו\"ת בשלח [בהוספה] ח, ד."],["4277","11","<b>התפלות נק' שבת</b>: ראה תו\"א ויקהל פח, א. לקו\"ת האזינו עב, ג. תו\"ח נח סא, ג ובהערה 29. ויקהל שם. וש\"נ. סה\"מ תרכ\"ז ס\"ע קפא ואילך."],["4278","10","<b>עליות כל התפלות. . שבת</b>: ראה (בנוסף להערה 1) תו\"א תרומה שם. מאמרי אדה\"א נ\"ך ע' שכ ואילך. ע' של. תו\"ח ויקהל ח\"ב תטו, ג. וש\"נ."],["4279","12","<b>עולת שבת. . בשבתו</b>: פינחס כח, י. ראה לקו\"ת שה\"ש מג, סע\"ד."],["4280","13","<b>כי הוי' הוא אלקי' </b>[ב: האלקי']: ואתחנן ד, לט."],["4281","14","<b>דלית אתר פנוי מיני'</b>: ראה ת\"ז תנ\"ז צא, ב. ת\"ע קכב, ב. ס' האמונות והדעות לרס\"ג מ\"ב, פי\"ג. תניא פכ\"א ובמ\"מ הגהות והע\"ק לשם. לקו\"ת בהר כאן מא, א. שם בהוספות נב, ג."],["4282","15","<b>ירידת. . צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."]]],[4801940189,"קיבול השכר דלעתיד שיהי' לנשמות שבגופי' דווקא וא\"כ יהי' הגילוי למטה וא\"כ למה נק' בשם עלי' כו'.\n<b>והנה</b> מתחלה י\"ל שרש הנשמה מה היא ואח\"כ יובן ענין הירידה מה היא והעלי' המתהווה מן הירידה ההוא<sup data-n=\"4283\">16</sup> כו'. והנה ההפרש בין שרש הנשמות לשרש המלאכים<sup data-n=\"4284\">17</sup> ושרש כל העולמות הוא ששרש כל העולמות הוא מבחי' דיבור כמאמר בדבר הוי' שמים נעשו<sup data-n=\"4285\">18</sup> וברוח פיו כו' שזהו ענין עשרה מאמרות מקור כל הנבראים כמבו' בלק\"א<sup data-n=\"4286\">19</sup> ע\"י חילופי' ותמורו' דרל\"א שערים<sup data-n=\"4287\">20</sup> כו' וכן אפי' מלאכים עליונים ג\"כ נתהוו מבחי' מאמרות וכמארז\"ל ע\"פ ועוף יעופף<sup data-n=\"4288\">21</sup> ועוף<sup data-n=\"4289\">22</sup> זה מיכאל יעופף זה גבריאל כו' אבל שרש הנשמות הוא מבחי' מח' שלמעלה הרבה מבחי' דיבור וכמאמר ישראל עלה במח'<sup data-n=\"4290\">23</sup> כו'. והנה אנו רואים למטה ההפרש בין מח' לדיבור שמח' הוא נק' בחי'<sup data-n=\"4291\">24</sup> לבוש הפנימי ודיבור נק' לבוש החיצון, ויובן ע\"ד דוגמא לבוש הפנימי הסמוך לגופו בגשמיו' אע\"פ שיכול לפושטו מ\"מ הוא לבוש בו תמיד משא\"כ לבוש החיצון אינו לובשו רק בצאתו לשוק כ\"ה לבוש המח' אע\"פ שהוא רק לבוש שפושטו ולובשו כי יכול להלביש שכלו באותיות מח' ואח\"כ לפשוט מאותיו' אלו ולהלבישו באותיות אחרות כו' מ\"מ הוא לבוש עצמי היינו שכשצריך נפשו להתגלות בעצמו בחומר המוח והלב הגילוי הוא ע\"י אותיות המח' כמו גילוי השכל בכלי מוחו לעצמו ממקור השכל שכלול בנפש הוא ע\"י אותיות המח' וכן גילוי התשוקה בלב הוא ג\"כ ע\"י הרהור הלב ונמצא שאותיות המחשבה המה לבוש פנימי שמתגלה בהם לעצמו ולא לזולתו, ועוד שהוא לבוש בהם תמיד פי' שהוא נצחי<sup data-n=\"4292\">25</sup> שאין אדם יכול להיות בלי מח'<sup data-n=\"4293\">26</sup> אע\"פ שבכל רגע פושט ממח' זו ומתלבש במח' אחרת מ\"מ הוא מלובש בכח מחשבתו תמיד שבלא מח' א\"א לו להיות אפי' רגע א' משא\"כ לבוש הדיבור שאינו לבוש עצמי כי אינו צריך אותם להתגלות ע\"י לעצמו רק לזולתו הוא מתגלה ע\"י אותיות הדיבור וגם אינו נצחי כנצחי' הנפש כי יכול להיות שלא ידבר כלל כשלא ירצה לדבר כו', ועד\"ז הנמשל למעלה ההפרש בין נשמות לעולמות ומלאכים כי כל העולמות ומלאכים בבחי' דבר הוי' שהוא כח נבדל מן העצמות להיותו בא ע\"י הסתר והעלם עצמו' האור עד שלא נגלה רק הארה בעלמא כמ\"ש כי נשגב כו' הודו על ארץ<sup data-n=\"4294\">27</sup> כו' ונמצא ששרשם בבחי' מקום",[["4283","16","<b>ההוא</b>: ב: מה היא."],["4284","17","<b>ההפרש. . הנשמות. . המלאכים</b>: ראה גם אגה\"ת פ\"ד. דרושים שבהערה 1. תו\"ח שמות ח\"א לט, ד. וש\"נ."],["4285","18","<b>בדבר הוי' שמים נעשו</b>: תהלים לג, ו."],["4286","19","<b>כמבו' בלק\"א</b>: שער היחוד והאמונה פ\"א."],["4287","20","<b>דרל\"א שערים</b>: ראה ס\"י פ\"ב, מ\"ד-ה ובמפרשיו. פי' הראב\"ד שם [מב, ד]. פרדס שער הצרוף ש\"ל, פ\"ה. עמק המלך שער שעשועי המלך ש\"א, פ\"ה."],["4288","21","<b>ועוף יעופף</b>: בראשית א, כ. ראה זהר בראשית מו, ב. מאמרי אדה\"א קונטרסים ע' שעו. וש\"נ. תו\"ח בראשית יט, א ובהערה 5."],["4289","22","<b>ועוף</b>: ניתוסף ע\"פ ב."],["4290","23","<b>ישראל עלה במח'</b>: ראה ב\"ר פ\"א, ד. שע\"ת קטו, ב. תו\"ח שמות ח\"א לב, ב ובהערה 248."],["4291","24","<b>בחי'</b>: ניתוסף ע\"פ ב."],["4292","25","<b>שהוא נצחי</b>: ב: שהמח' נצחית."],["4293","26","<b>שאין אדם יכול להיות בלי מח'</b>: ראה שערי אורה ז, א ובהערה 15."],["4294","27","<b>כי נשגב. . ארץ </b>[ב: נשגב שמו לבדו כו' הודו על או\"ש]: תהלים קמח, יג."]]],[4801940246,"דוקא כמ\"ש הנה מקום אתי<sup data-n=\"4295\">28</sup> והוא כאשר מתלבש אוא\"ס בבחי' לבוש הדיבור שבזה שייך בחי' מקום אבל כאשר היו מתעלים<sup data-n=\"4296\">29</sup> ונכללי' בבחי' המהו\"ע האור שהוא למעלה מבחי' מקום רק מתאחד בעצמו' היו בטלים ממציאותם לגמרי [... וכמאמר הושיט אצבעו הקטנה<sup data-n=\"4297\">30</sup> שהוא בחי' עצמי'<sup data-n=\"4298\">31</sup> מדת המל' ושרפן שנתבטלו ממציאותן כי שרשם הוא מל' דמל' הנק' דיבור וארץ כו'] וגם המה בבחי' זמן כמארז\"ל במדרש ועוד כל ימי הארץ<sup data-n=\"4299\">32</sup> כ\"ז שהיום והלילה קיימים וכידוע דשית אלפי שני<sup data-n=\"4300\">33</sup> בלבד הוי עלמא כו' וכמ\"ש עת לעשות כו'<sup data-n=\"4301\">34</sup> ועת לחשות<sup data-n=\"4302\">35</sup> כו'<sup data-n=\"4303\">36</sup> שהוא כאשר פוסק מלדבר כבי' שזה יהי' לעתיד דכתי' ונשגב ה' לבדו<sup data-n=\"4304\">37</sup> כו' אבל בחי' הנשמות שרשם במח' שהוא בחי' עצמות האור האלקי שכח ביטולם והתכללותם הוא בבחי' עצמות האור האלקי כמו שהוא באצי' למעלה מבחי' מקום ואעפ\"כ אינם בטלים ממציאותם וגם המה נצחי'<sup data-n=\"4305\">38</sup> כי עלייתם הוא בלי שיעור כי אע\"פ שאינו מוזכר בספרים רק געה\"ע והתחתון<sup data-n=\"4306\">39</sup> אבל באמת יש עלי' לאין שיעור וכמ\"ש וקדושי' בכ\"י<sup data-n=\"4307\">40</sup> [שזהו בחי' הנשמות שנק' קדושים כמשי\"ת] יהללוך סלה בעא\"ע בלי הפסק, וענין העלי' שלהם הוא לפ\"ע ההשגה שמשיגים באוא\"ס וכמ\"ש לפי שכלו יהולל איש<sup data-n=\"4308\">41</sup> כו', והיינו מפני שרשם שהוא במח' עליונה בחי' בינה המקבלת מבחי' חכ\"ע דאצי' [כידוע דחו\"ב נק' תרדל\"מ<sup data-n=\"4309\">42</sup> ] בתמידות בלי הפסק וכמו למטה המח' הנמשכת בתמידות מכח החכ' שבנפש וידוע דהחכ' מקבל מבחי' אוא\"ס בלי הפסק כן המחשבה דבינה מקבל מבחי' החכ' בתמידות, וכן הוא בחי' הנשמות שמקבלת מבחי' מח' דבינה שקבלתם הוא בבחי' נצחי' בלי הפסק כלל כו'.\n<b>והנה</b> אמר בורא קדושים ישתבח שמך<sup data-n=\"4310\">43</sup> כו', כי הנשמות נק' קדושה<sup data-n=\"4311\">44</sup> והטעם הוא להיותם בעלי צורה בלי חומר כלל כי המלאכים בעלי חומר וצורה<sup data-n=\"4312\">45</sup> כמאמר",[["4295","28","<b>הנה מקום אתי</b>: תשא לג, כא."],["4296","29","<b>היו מתעלים</b>: ב: הי' מתעלם."],["4297","30","<b>הושיט אצבעו הקטנה</b>: ראה סנהדרין לח, ב. מאמרי אדה\"א ויקרא ח\"א ע' קסא. וש\"נ. תו\"ח שמות ח\"א ל, ב ובהערה 127."],["4298","31","<b>עצמי'</b>: ניתוסף ע\"פ ב."],["4299","32","<b>ועוד </b>[ב: עוד]<b> כל ימי הארץ</b>: נח ח, כב. ב\"ר פל\"ד, יא."],["4300","33","<b>דשית אלפי שני</b>: ראה ר\"ה לא, א. מאמרי אדה\"א בראשית ע' נג. וש\"נ."],["4301","34","<b>עת לעשות כו'</b>: עד\"ז מובא בתו\"ח וירא ק, רע\"ד ושם: עת לעשות לה' כו' — תהלים קיט, קכו. ב: עת לדבר — קהלת ג, ז [ושם: ועת — ראה תו\"ח שם ובהערה 45]."],["4302","35","<b>ועת לחשות</b>: קהלת שם [ושם: עת — עת לחשות ועת לדבר]."],["4303","36","<b>כו'</b>: ב: ליתא."],["4304","37","<b>ונשגב ה' לבדו</b>: ישעי' ב, יא. יז."],["4305","38","<b>הנשמות. . המה נצחי'</b>: ראה תו\"א מקץ לח, ג. לט, ד. הנסמן בסה\"מ תרל\"ח ע' עד הערה 260."],["4306","39","<b>שאינו מוזכר בספרים רק געה\"ע והתחתון</b>: ראה גם לקמן מאמר ד\"ה וזכרתי הר\"ת על יד הערה 78. לקו\"ת [בהר כאן מא, ב] במדבר יח, א. מסעי צא, ב. תו\"א מקץ לב, ד. שמות מט, סע\"א. סה\"מ תרל\"ח ע' תקה ובהערה 14."],["4307","40","<b>וקדושי' בכ\"י</b>: תפלת שמו\"ע."],["4308","41","<b>לפי שכלו יהולל איש</b>: משלי יב, ח."],["4309","42","<b>דחו\"ב נק' תרדל\"מ</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. תו\"ח בראשית כא, ב ובהערה 8."],["4310","43","<b>בורא קדושים ישתבח שמך</b>: ברכת יוצר."],["4311","44","<b>הנשמות נק' קדושה </b>[ב: קדושים]: ראה גם [בנוסף לדרושים שבהערה 1] תו\"א מקץ לב, ד. לקו\"ת במדבר יח, א. שה\"ש לד, ג. מאמרי אדה\"א נ\"ך ס\"ע שכ ואילך. ע' תסה ואילך. וש\"נ. שע\"ת כח, ד. פא, א. תו\"ח שמות ח\"א ד, ג. וש\"נ. יתרו ח\"ב רנב, ג ואילך."],["4312","45","<b>המלאכים בעלי חומר וצורה</b>: ראה [בנוסף להנסמן בהערה 1]. תניא פ\"מ. מאמרי אדה\"א בראשית ע' קיב. וש\"נ. סה\"מ תרל\"ח ע' סד ובהערה 111."]]],[4801940299,"וגווייתו כתרשיש<sup data-n=\"4313\">46</sup> משא\"כ הנשמות אע\"פ שלמטה המה מלובשים בחומר גוף גשמי יותר מהמלאכים מ\"מ בשרשם אינם בעלי חומר כלל והיינו ג\"כ מטעם הנ\"ל להיות כי שרשם באותיות המח' ואותיות המח' נמשכים מן השכל כהדין קמצא דלבושי' מיני' ובי'<sup data-n=\"4314\">47</sup> כי<sup data-n=\"4315\">48</sup> בעת המשכת גילוי השכל ממקורו שהוא בחי' אין אז נמשכים עמו גם בחי' האותיות מאין ליש לכן אינם מסתירים כלל על אור השכל שבתוכם רק מקבלים אותו בבחי' גילוי כמ\"ש וכן הנשמות מקבלים גילוי אוא\"ס בלי הסתר כלל משא\"כ המלאכים מקבלים מבחי' אותיות הדיבור ואותיות הדיבור המה נמשכים בדרך צורה וחומר [כידוע דשרש האותיות הוא מעצמו' הנפש<sup data-n=\"4316\">49</sup> רק שבאים ומתלבשים בהבל הלב הבא בדרך התחלקות בה\"מ הפה כו' וראי' ממה שכשצריך לדבר איזה אות אין כוונתו להניע המוצא רק כוונתו לדבר האות ותנועת המוצא ממילא נעשה כו'] ונמצא ששרש האותיות הוא הוא<sup data-n=\"4317\">50</sup> בחי' הצורה שלהם והבל הלב המתחלק הוא בחי' החומר שלהם ולכן גם המלאכים המקבלים מבחי' אותיות הדיבור המה מקבלים גילוי אוא\"ס בבחי' הסתר מצד החומר המסתיר כו' ולכן נק' הנשמות בשם קדושים דייקא כו' אך הנה גם הנשמות שנק' קדושים המה רק בריאה מאין ליש בלבד וכל השבח וההילול שלהם בעא\"ע הוא רק בחי' שמך בלבד וזהו בורא קדושים שהמה בריאה מאין ליש ולכן ישתבח ע\"י רק בחי' שמך בלבד.\n<b>וביאור</b> הדברים הנה מתחלה צ\"ל ענין השם מהו שהוא כמו עד\"מ שם של אדם שאינו צריך אותו לעצמו כלל רק שהוא נתפס ע\"י לזולתו<sup data-n=\"4318\">*51</sup> ונמצא שהוא כמו בחי' האור שאינו רק כח הגילוי לזולתו ולכן שם ואור הוא בחי' אחת<sup data-n=\"4319\">51</sup> ומה<sup data-n=\"4320\">52</sup> שנק' במקובלים בחי' אוא\"ס נק' בפדר\"א שמו כמאמר הי' הוא ושמו בלבד<sup data-n=\"4321\">53</sup> כו', אך אעפ\"כ אנו רואים שהשם הוא שייכות להעצם<sup data-n=\"4322\">54</sup> וראי' שהוא נתפס ע\"י לקוראו ועוד זאת מצינו בקריאת שמות דאדה\"ר<sup data-n=\"4323\">55</sup> שניסה אותו<sup data-n=\"4324\">56</sup> הוי' אם יש בו חכ' זאת לקרוא",[["4313","46","<b>וגווייתו כתרשיש</b>: דניאל י, ו."],["4314","47","<b>כהדין קמצא דלבושי' מיני' ובי'</b>: ראה ב\"ר פכ\"א, ה. מאמרי אדה\"א ויקרא ח\"ב ע' תשכא בהערה. סה\"מ תרכ\"ז ע' שנ ואילך. תרכ\"ט ע' שעג ואילך."],["4315","48","<b>כי</b>: ניתוסף ע\"פ ב."],["4316","49","<b>דשרש האותיות הוא מעצמו' הנפש</b>: ראה אגה\"ק ס\"ה. מאמרי אדה\"ז תקע\"א ( ע' נז)־ נביאים (ע' רנח). ש\"א ו, ב ובהנסמן במ\"מ לשם. תו\"ח בשלח ח\"א קמח, א. וש\"נ. סה\"מ תרל\"ח ע' כא ובהערה 194."],["4317","50","<b>הוא</b>: ב: ליתא."],["4318","*51","<b>שם. . נתפס ע\"י לזולתו</b>: ראה גם לקמן מאמר ד\"ה וזכרתי הר\"ת על יד הערה 18. מאמרי אדה\"א דברים ח\"ד ע' א'רסח. וש\"נ (ובריש המאמר שם). המשך זאת חנוכת תר\"ם רפ\"ד. וש\"נ."],["4319","51","<b>שם ואור הוא בחי' אחת</b>: ראה סה\"מ תרכ\"ז ע' שס־ תרכ\"ט ע' קלה ואילך־ תרל\"ב ח\"א ע' כא וע' קלב ובהנסמן בהנ\"ל."],["4320","52","<b>ומה</b>: ב: והוא."],["4321","53","<b>בפדר\"א. . ושמו בלבד</b>: ראה שם פ\"ג. תו\"ח וארא ח\"א נג, ב הערה 6."],["4322","54","<b>שהשם הוא שייכות להעצם</b>: ראה גם [בנוסף להנסמן בהערה 1] מאמרי אדה\"א קונטרסים ס\"ע תקס ואילך. תו\"ח יתרו ח\"ב רנב, ד. סה\"מ תרל\"ב ח\"א ע' קלא. וש\"נ. תרל\"ח ע' סב. וש\"נ."],["4323","55","<b>בקריאת שמות דאדה\"ר</b>: בראשית ב, כ. ראה ב\"ר פי\"ז, ד. של\"ה בית אחרון יד, א. סה\"מ תרל\"ח ע' קסב ובהנסמן שם."],["4324","56","<b>אותו</b>: תוקן ע\"פ ב."]]],[4801940349,"שמות ואם הי' השם הסכמה בעלמא אין זה חכ' כלל וע\"כ לומר שבאותיות השם נתפס ומלובש בהם עצם החיות ולכן חכ' גדולה היתה בו להרגיש שרש ומקור החיות של כל א' באיזה אותיות הוא מלובש וכן באותיות אלו קרא לו השם ולכן אמר לכל אשר יקרא לו האדם הוא שמו<sup data-n=\"4325\">57</sup> המיוחד לו וכן הטעם בלידת ראובן כי ראה ה'<sup data-n=\"4326\">58</sup>. אך לכאורה אנו רואין ג\"כ להיפוך והוא מה שנשמה א' יוכל להיות שיקראו לה שמות מחולפים כמו נשמת רשב\"י ששרשו נשמת מרע\"ה<sup data-n=\"4327\">59</sup> ואעפ\"כ נק' בשם שמעון ואם הי' השם שייכות להעצם הי' לו להיות נקרא בשם משה כו'. אך הענין יובן ע\"פ הידוע שיש ב' בחי' בנשמה הא' שרש הנשמה כמו שהוא למעלה כלולה במקורה כמו האור של השמש שנכלל תמיד במאור השמש והב' בחי' המתפשטת ממנה בגוף שזהו רק הארה בעלמא משרש ומקור הנשמה וכמו אור הנר שעומד על השולחן ומאיר לעצמו ומחמת זה מתפשטת ההארה גם בכל הבית וכן גם בנשמה שמצד אור עצמה המאירה בעא\"ע באוא\"ס ממילא מאיר ג\"כ בגוף [וראי' שאין מהות הנפש מתלבשת מנפש בגלגולים שמתגלגל בבחי' בהמה<sup data-n=\"4328\">60</sup> שהוא בחי' חי וכן בדומם<sup data-n=\"4329\">61</sup> כמ\"ש כי אבן מקיר תזעק<sup data-n=\"4330\">62</sup> כו'].\n<b>ומעתה</b> יובן ענין הנ\"ל שהשם הוא שייכות לבחי' הנשמה המתלבשת בגוף בכל אברי הגוף שזהו ע\"י השם דווקא [כי השם הוא ממוצע בין האור והחיות<sup data-n=\"4331\">63</sup> לבחי' הכלים וע\"י נתפס האור בכלי] והטעם הוא להיותו מקור האור כי הוא המעורר לעצמי' הנפש שיהי' נמשך ומתפשט בגוף לכן הוא המחבר ג\"כ אח\"כ בחי' האור בכלי כו' והענין<sup data-n=\"4332\">64</sup> הוא כי אינו דומה התפשטות הנפש להתפשטות האור שהתפשטות אור השמש הוא בחיוב והכרח משא\"כ התפשטות הנפש הוא ע\"י הרצון והרצון הוא בחי' השם מקור האור והחיות המתלבש בגוף שמעורר אותם להיות מתגלה מעצם הנשמה ובלא הרצון הי' נשאר גילוי האור נכלל בהעלם ואח\"כ הוא בא בדרך האמצעי בין האורות לכלים כו' אבל הרצון גופא נכלל ובטל בעצמות הנשמה עד שאין תופס מקום כלל כביטול זיו השמש במקורו כו' וד\"ל וכמשי\"ת]. אבל לגבי בחי' עצמות הנשמה כמ\"ש כלולה במקורה אינו נוגע כלל רק שהוא בטל ונכלל בו כביטול זיו השמש במקורו. ועתה יובן שלכן בבחי' משה שהי' ירידת",[["4325","57","<b>לכל אשר יקרא לו האדם הוא שמו</b>: בראשית ב, יט [ושם: וכל. בדילוג]."],["4326","58","<b>כי ראה ה'</b>: ויצא כט, לב."],["4327","59","<b>נשמת רשב\"י ששרשו נשמת מרע\"ה</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפז־ מאמרי אדה\"א נ\"ך ע' שס־ תו\"ח ויצא קעח, ג ובהנסמן בהנ\"ל. שה\"א צח, ב."],["4328","60","<b>בגלגולים שמתגלגל בבחי' בהמה</b>: ראה ת\"ז ת\"ע קלג, א ובכס\"מ שם אות ת (קעח, א). רקאנטי נח ט, ד (ובאבן יקרה שם יט, ד ואילך). אמור כב, ב. שיעור קומה — להרמ\"ק — מערכת גלגול ספ\"ד. שער הגלגולים הקדמה כב. עמק המלך שער תיקוני התשובה פ\"א. שער רישא דז\"א שט\"ז, פמ\"ה (קנב, ג). סידור שחרית מח, ג. מאמרי אדמ\"ר הצ\"צ תרי\"ד ע' כא. סה\"מ תרכ\"ט ע' יח. וש\"נ. ע' ריח. וש\"נ. ע' שצה."],["4329","61","<b>בגלגולים שמתגלגל. . בדומם</b>: ראה מאמרי אדה\"א קונטרסים ע' ה. וש\"נ. תו\"ח נח סח, ב ובהערה 9. שמות ח\"א כח, ב. וש\"נ."],["4330","62","<b>כי אבן מקיר תזעק</b>: חבקוק ב, יא. ראה עמה\"מ שם פכ\"ט (קלח, ד)."],["4331","63","<b>והחיות</b>: ב: וחיות של הנפש."],["4332","64","<b>והענין</b>: אולי צ\"ל: [והענין."]]],[4801940396,"נשמתו בגופו לצורך הגילוי דמ\"ת פב\"פ לכן הי' המשכות אור נשמתו ע\"י אותיות משה אבל ברשב\"י הי' צריך מקור הנשמה להתגלות באופן אחר רק ניצוץ בלבד לכן הי' צריך להתגלות באותיות שמעון אבל עצם הנשמה כמ\"ש כלולה במקורה אחת היא רק שכח ההתפשטות שנתגלה בגוף היא באופנים ומדריגות שונות כו' וד\"ל.\n<b>ועתה</b> י\"ל בחי' השם למעלה כי הנה כתיב לכו חזו מפעלות אלקים<sup data-n=\"4333\">65</sup> אשר שם שמות בארץ א\"ת שמות אלא שמות<sup data-n=\"4334\">66</sup> דהנה בנשמה אין כאן רק ב' מדריגות עצם הנשמה והארתה המתפשטת ומתלבשת בגוף שזהו בחי' שם אבל למעלה<sup data-n=\"4335\">67</sup> בבחי' אא\"ס יש ריבוי שמות כי יש ריבוי מדריגות הארה והארה דהארה וכל מדריגה לגבי מדריגה שלמעלה הימנו אינו רק הארה בעלמא ממנו ונק' בחי' שם וד\"פ<sup data-n=\"4336\">68</sup> הנה יש בחי' שמו הגדול (... ואפשר שהוא בחי' שמו בלבד הנק'<sup data-n=\"4337\">69</sup> בפדר\"א שזהו בחי' אותיו' דרל\"א שערים הנז' בעומק<sup data-n=\"4338\">70</sup> המלך ואינו מלובש בהם רק רשימו מעצמות האור דאוא\"ס כו') ויש בחי' שם הוי' שנחלק לכמה פרטי' בחי' יו\"ד דהוי' וה' דשם הוי' ובחי' וא\"ו דשם הוי' וה\"א אחרונה כו' [וכל אותיות<sup data-n=\"4339\">71</sup> מהוי' יש בו הוי' שלימה כמו היו\"ד כי<sup data-n=\"4340\">72</sup> הוא שם ע\"ב<sup data-n=\"4341\">73</sup> במילוי יודי\"ן<sup data-n=\"4342\">74</sup> והה' הוא בחי' שם ס\"ג<sup data-n=\"4343\">75</sup> כו'] ויש ז' שמות שאינן נמחקין<sup data-n=\"4344\">76</sup> כמו שם אל אלקים כו', וכללות כל הרבות<sup data-n=\"4345\">77</sup> מדריגות אינם רק שם והארה בעלמא מעצמות אוא\"ס כו', והנה עז\"א בורא קדושים ישתבח שמך שכל עלי' הנשמות בעא\"ע הגם שנתגלה בהם האור בלי הסתר כלל מ\"מ אינו רק שם והארה ובבחי' זאת יהללוך בעא\"ע והטעם הוא כי הם נחשבים נבראים מאין ליש לגבי עצמות האור כמ\"ש בורא קדושים כי שרשם הוא בחי' חכ' ראשית הגילוי<sup data-n=\"4346\">78</sup> וגם בבחי'<sup data-n=\"4347\">79</sup> החכ' מאין תמצא<sup data-n=\"4348\">80</sup> ונק' בריאה מאין ליש לגבי עצמות המאציל וכמאמר",[["4333","65","<b>לכו חזו מפעלות אלקים</b>: תהלים מו, ט. וראה במנחת שי שם. זהר בראשית נח, ב ובמפרשים שם. שה\"א מז, ב ובהערה 21. תו\"ח וארא ח\"א ס, ד. וש\"נ."],["4334","66","<b>א\"ת שמות אלא שמות</b>: ברכות ז, ב. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשצב. וש\"נ. נ\"ך ע' תעב."],["4335","67","<b>למעלה</b>: ב: ליתא."],["4336","68","<b>וד\"פ</b>: ב: וד\"כ."],["4337","69","<b>הנק'</b>: ב: הנז'."],["4338","70","<b>בעומק</b>: כנצ\"ל: בעמק."],["4339","71","<b>אותיות</b>: ב: אות."],["4340","72","<b>כמו היו\"ד כי</b>: ב: כי היו\"ד."],["4341","73","<b>שם ע\"ב</b>: ראה זהר תרומה קלב, ב. פרדס שער פרטי השמות שכ\"א, פ\"ה. מכתב להרב בראנדט נדפס ברשימות חוב' מא לפ' אחו\"ק."],["4342","74","<b>שם ע\"ב במילוי יודי\"ן</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. שער רפ\"ח ניצוצין שי\"ח, פ\"א. מאמרי אדה\"א דברים ח\"ד ע' א'קצב. וש\"נ."],["4343","75","<b>והה'. . שם ס\"ג</b>: ראה גם סידור שחרית לשבת קצב, סע\"ב. סהמ\"צ להצ\"צ ע' 70. תו\"ח וירא צז, ד ובהערה 48. שעה\"י קכח ב הערה 44. פיה\"מ נא, ד. תו\"ח תרומה ח\"ב שיב, רע\"ג. (שם ס\"ג — ראה זהר רע\"מ פינחס רמו, ב)."],["4344","76","<b>ז' שמות שאינן נמחקין</b>: שבועות לה, א. רמב\"ם הל' יסודי התורה פ\"ו, ה\"ב. תו\"ח בא ח\"א קיב, א ואילך ובהנסמן בריש המאמר שם. סה\"מ תרכ\"ז ע' יב."],["4345","77","<b>הרבות</b>: ב: הריבוי."],["4346","78","<b>חכ' ראשית הגילוי</b>: ראה גם סה\"מ תרל\"ח ע' נ ובהערה 260."],["4347","79","<b>בבחי'</b>: ב: בחי'."],["4348","80","<b>החכ' מאין תמצא</b>: איוב כח, יב. ראה הנסמן במ\"מ ללקו\"ת כאן מא, ד. ס' המצות להצ\"צ לו, א. אוה\"ת בהר כאן ע' א'קסב. המשך וככה תרל\"ז ר\"פ לה ע' מז. לעיל ע' רטז."]]],[4801940439,"בראשית ברא<sup data-n=\"4349\">81</sup> שגם מאמר דבראשית שהוא בחי' החכ' כתי' בראשית בחוכמתא<sup data-n=\"4350\">82</sup> הוא ג\"כ ברא שהוא בחי' בריאה מאין ליש לגבי עצמות המאציל והגם שחכ' הוא ראשית הגילוי מאין מלובש בה<sup data-n=\"4351\">83</sup> הארת האין [... כידוע דאוא\"ס שורה בחכ'<sup data-n=\"4352\">84</sup> ] אינו רק הארת האין אבל לא בחי' אין אמיתי שהוא בחי' עצמות אוא\"ס שאינו נמצא בה בבחי' גילוי רק בהעלם עד שנמצא גם בעשי' גשמי' למטה כמו למעלה בחכ' בהשוואה ממש כמאמר את השמים ואת הארץ אני מלא<sup data-n=\"4353\">85</sup> ונק' סוכ\"ע כו' וד\"ל.\n<b>והנה</b> ע\"ז<sup data-n=\"4354\">86</sup> יובן ענין ירידת הנשמה בגוף שזהו לצורך עלי' שזהו קיבול שכר שיהי' לע\"ל בתחה\"מ בנשמות שבגופי' שיתגלה בהם הארת הסובב שהוא אין האמיתי שיתגלה גם בגופם ונשמתם כאחד כו', אך היום לעשותם<sup data-n=\"4355\">87</sup> שההכנה לזה הוא בעוה\"ז ע\"י מעהמ\"צ כי ידוע דשכר מצוה היא מצוה עצמה<sup data-n=\"4356\">88</sup> כי הנה כללות המצות נחלקים לג' בחי' תורה ועבודה וגמ\"ח, והנה בעבודת הקרבנות נראה ונגלה בחי' ביטול היש לאין בגילוי כי שורפין הבהמה וההגשמה שבה נופל ונעשה דשן וחיות הרוחני מתעלה למעלה בשרשה שהוא בחי' אין האלקי [... ע\"ד<sup data-n=\"4357\">89</sup> שרשה בעולם התוהו], וכן בתורה עיקר הלימוד הוא לבטל א\"ע מכל וכל בכדי לשמוע בחי' דבר ה' המדבר בפיו בעת דיבורו אותיות התורה וכמו שאמר המגיד אני המשנה המדברת בפיך<sup data-n=\"4358\">90</sup> כו', אבל לא ללמוד בבחי' יש היינו להנאת עצמו אפי' לידע ההשכלה שלא ישכון בזה אור ה', וזהו שאנו אומרים ובכל נפשך קודם והיו הדברים האלה<sup data-n=\"4359\">91</sup> אשר אנכי כו' כי בכל נפשך הוא ביטול כל נפשו וכחותיו לגבי אוא\"ס לא להיות בבחי' יש בכדי שלא יהי' דבר מפסיק בינו לבין אוא\"ס המתלבש בדיבורו בעת עסקו בתורה ואז והיו הדברים אשר אנכי מי שאנכי<sup data-n=\"4360\">92</sup> כו' דהיינו שישכון אוא\"ס בנפשו ונמצא שעיקר לימוד התורה הוא ג\"כ ביטול היש לאין וכן גמ\"ח שהוא הצדקה שנותן רכושו אשר מסר נפשו ע\"ז לעני ושפל רוח אשר לית לי' מג\"כ והוא בחי' אין שזהו ג\"כ ביטול היש לאין ולכן עיקר הגמ\"ח נמשך מצד השפלות כמו באברהם דעביד",[["4349","81","<b>וכמאמר </b>[ב: וכמ\"ש]<b> בראשית ברא</b>: בראשית א, א."],["4350","82","<b>בראשית ברא. . החכ'. . בחוכמתא</b>: ראה תרגום ירושלמי שם. רקאנטי ר\"פ בראשית. מאמרי אדה\"א בראשית ע' א. וש\"נ."],["4351","83","<b>מאין מלובש בה</b>: ב: מן האין ומלובש בה."],["4352","84","<b>דאוא\"ס שורה בחכ'</b>: תניא פל\"ה בהגהה."],["4353","85","<b>כמאמר </b>[ב: וכמ\"ש]<b> את השמים. . מלא</b>: ירמי' כג, כד. ראה גם לעיל ע' קס. ע' רכא. לקמן ד\"ה והתהלכתי תרט\"ו על יד הערה 46. פלח הרמון ויחי קטז, סע\"ג. תו\"ח בשלח ח\"א קסו, ג. וש\"נ."],["4354","86","<b>ע\"ז</b>: אוצ\"ל: עד\"ז."],["4355","87","<b>היום לעשותם</b>: ואתחנן ז, יא."],["4356","88","<b>דשכר מצוה היא מצוה עצמה</b>: אבות פ\"ד, מ\"ב. ראה תניא רפל\"ז. מאמרי אדה\"א דברים ח\"ג ע' תתצט. וש\"נ. תו\"ח שמות ח\"א ז, ב. וש\"נ. סה\"מ תרכ\"ט ע' כא. וש\"נ. לעיל ע' שא."],["4357","89","<b>ע\"ד</b>: ב: עד."],["4358","90","<b>אני המשנה המדברת בפיך</b>: ראה מגיד משרים פ' ויחי. בא. תשא. שע\"ת פ, ג ובהערה 26. תו\"ח תצוה ח\"ב שסב, ד. וש\"נ."],["4359","91","<b>ובכל נפשך קודם והיו הדברים האלה</b>: ואתחנן ו, ה. ו."],["4360","92","<b>אנכי מי שאנכי</b>: ראה תניא מהדו\"ק ספמ\"ט. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."]]],[4801940477,"טיבו יתירא<sup data-n=\"4361\">93</sup> שזה הי' מצד השפלות שבו אב\"ר מ\"ה<sup data-n=\"4362\">94</sup> וכמאמרו ואנכי עפר ואפר<sup data-n=\"4363\">95</sup> אך עכשיו הוא רק ביטול היש לאין ונמצא שבחי' האין הוא בחי'<sup data-n=\"4364\">96</sup> ההעלם אבל לע\"ל יתגלה אמיתית עצם האין מהעלמו שהוא<sup data-n=\"4365\">97</sup> בחי' אין האמיתי בחי' סוכ\"ע שזהו קיבול שכר מצוה והוא מצוה עצמה שהוא בחי' הביטול לאין שבהעלם עכשיו ובו שורה בהעלם בחי' אין האמיתי ולע\"ל יתגלה כו' וד\"ל.\n<b>ועתה</b> יובן ענין עלית הנשמה למה נק' בשם עלי' כי באמת אין הפי' עלי' בבחי' מקום רק שהוא ע\"ד דוגמא דכורע בברוך וזוקף בשם<sup data-n=\"4366\">98</sup> כי הנה כורע בברוך הוא הרכנת עצם המשפיע למקבל להתייחד עם המקבל במקומו ונמצא שאין נעשה שינוי כלל בכלי המקבל וכמו במ\"ת דכתיב וירד הוי' על ה\"ס<sup data-n=\"4367\">99</sup> כו' וידבר כו' אנכי<sup data-n=\"4368\">100</sup> כו' כי<sup data-n=\"4369\">101</sup> הגם שנתגלה בחי' אנכי מי שאנכי סדכ\"ס<sup data-n=\"4370\">102</sup> למטה מ\"מ מצד שהי' בבחי' ירידה למטה במקום המקבל לא נשתנה כלל ההר סיני ממהותו וכן נש\"י שבגופים לא נשתנה מהות גופם רק שהגילוי הי' מלובש בהם בהעלם לפי\"ע הכלי שלהם כו' אבל ענין זוקף בשם הוא עלי' המקבל לקבל השפעת עצם המשפיע כמ\"ש במקום המשפיע מצד שנשתנה כלי המקבל ממהותו לגמרי ונזדכך עד שיוכל לקבל מהות עצם המשפיע כמ\"ש במקומו ועד\"ז יהי' לע\"ל דכתי' וכל קרבי את שם קדשו<sup data-n=\"4371\">103</sup> שגוף גשמי יקבל שפע וחיות דאוא\"ס הסוכ\"ע והיינו מצד שיהי' זיכוך הגוף עד שישתנה ממהותו לגמרי ויוכל לקבל שפע וחיות מאוא\"ס בגילוי, וראי' לזה שאם יהיו הגופים באופן שהם עכשיו איך א' בעוה\"ב אין בו לא אכילה<sup data-n=\"4372\">104</sup> ולא שתי' ואיך יוכל גוף גשמי לחיות בלא אכילה וע\"כ לומר שישתנה ויזדכך ממהותו לגמרי כנ\"ל וזהו בחי' עלי' כו' וד\"ל. והנה עד\"ז יובן פי' ענין עליו' העולמות דשבת וענין שתי שבתות כו' כי הנה ענין השבת הוא כמ\"ש כי בו שבת<sup data-n=\"4373\">105</sup> והוא עד\"מ אדם השובת ונח ממלאכתו שבתחלה בעת המלאכה הי' מלובש שכלו ומדותיו במעשה המלאכה שעשה ואח\"כ כשגמר מלאכתו נתעלו כל הכחות כמו המדות שהיו מלובשי' במעשה המלאכה שהמה רק הארה והתפשטות מעצם מדותיו נתעלו למקורם בכח המדות שבלב וכן שכלו שהי' מלובש במעשה שהוא רק הארה והתפשטות מעצם שכלו נתעלה בכח שכלו. וכך הוא למעלה כתי'<sup data-n=\"4374\">106</sup> כי",[["4361","93","<b>באברהם דעביד טיבו יתירא</b>: ראה זהר ואתחנן רסב, ב. סידור שער התפילין יב, א. אמ\"ב שם קלז, א."],["4362","94","<b>באברהם. . אב\"ר מ\"ה</b>: ראה זהר בהקדמה ד, רע\"א. ראה גם ש\"א נד, ב."],["4363","95","<b>וכמאמרו </b>[ב: וכאמרו]<b> ואנכי עפר ואפר</b>: וירא יח, כז."],["4364","96","<b>בחי'</b>: ב: בבחי'."],["4365","97","<b>שהוא</b>: ב ניתוסף: הוא."],["4366","98","<b>דכורע בברוך וזוקף בשם</b>: ראה ברכות יב, סע\"א. שו\"ע אדה\"ז הל' תפלה סקי\"ג, ס\"ה. לקו\"ת כאן בהר מב, ג. סידור תפלת ר\"ה רלח, ד. עט\"ר שער ר\"ה פי\"ד. סה\"מ תרל\"ח ע' ריב."],["4367","99","<b>וירד הוי' על ה\"ס</b>: יתרו יט, כ."],["4368","100","<b>וידבר כו' אנכי</b>: יתרו כ, א. ב."],["4369","101","<b>כי</b>: ניתוסף ע\"פ ב."],["4370","102","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["4371","103","<b>וכל קרבי את שם קדשו</b>: תהלים קג, א. ראה גם לקמן מאמר ד\"ה אם בחוקותי תר\"י על יד הערה 104."],["4372","104","<b>בעוה\"ב אין בו לא אכילה</b>: ברכות יז, א."],["4373","105","<b>כי בו שבת</b>: בראשית ב, ג. ראה גם לעיל ע' רמב."],["4374","106","<b>כתי'</b>: ב: ליתא."]]],[4801940512,"ששת ימים עשה הוי'<sup data-n=\"4375\">107</sup> שית יומין עילאין שהמה המדות דאצי' שהמה מלובשים בבי\"ע כל יומא בעבידתי' וכן כולם בחכ' עשית<sup data-n=\"4376\">108</sup> שגם החכ' דאצי' נמשכה ונתלבשה בבי\"ע למדוד כו' ובתשלום הששת ימים שבתו ונתעלו במקורם היותר ראשון שהוא בחי' החכ' דאצי', אך כתיב עולת שבת בשבתו כי הנה כתי' ויכל אלקי'<sup data-n=\"4377\">109</sup> כו' וישבות כו' מכל מלאכתו אשר עשה ואחר ויברך ויקדש<sup data-n=\"4378\">110</sup> כתי' כי בו שבת כו' אשר ברא.\n<b>והענין</b> הוא<sup data-n=\"4379\">111</sup> דגם במע\"ב יש שני בחי' בריאה ועשי' דמאמר דבראשית<sup data-n=\"4380\">112</sup> שהוא בחי'<sup data-n=\"4381\">113</sup> החכ' עצמה הוא בחי' בריאה מאין ליש כמאמר בראשית ברא כי גילוי החכ' שהוא ראשית הגילוי מאין הנעלם נק' בשם בריאה שהוא מאין ליש כמאמר והחכ' מאין תמצא משא\"כ מחכ' למח' וממח' לדיבור הוא בחי' יש מיש ולכן נק' בשם עשי' וכמאמר כולם בחכ' עשית שההמשכה מחכ' ולמטה נק' בשם עשי' כו' ולכן בשאר המאמרות כתי' ל' עשי' ויעש אלקים את הרקיע<sup data-n=\"4382\">114</sup> כו'. והנה כמו דבמע\"ב יש שני בחי' בחי' בריאה ובחי' עשי' כן יש שתי בחי' שבת הא' השביתה מכל אשר עשה שהוא עלי' העולמות דבי\"ע במל' דאצי' ומל' דאצי' עולה בחכ' שזהו בד\"כ שבת תתאה, והב' הוא השביתה מכל אשר ברא שהוא עלי' החכ' במקורה באין האמיתי בחי' סוכ\"ע שזהו שבת עילאה כו', וזהו ענין עלי' העולמות שהוא השתנות כלי המקבל לקבל הארת האין האמיתי כמ\"ש במקומו שנק' בשם עלי' כנ\"ל בענין זוקף בשם, אך לע\"ע אין הזיכוך שלהם והארת אין האמיתי בהם רק בפנימי' העולמות<sup data-n=\"4383\">115</sup> אבל בחיצוני' העולמות אין שינוי אבל לע\"ל יהי' הזיכוך בחיצוני' העולמות כו' וד\"ל.\n<b>והנה</b> ע\"ד דוגמא זאת הוא ג\"כ בחי' שביעית שהוא ענין מה ששובת ממלאכה שזהו בחי' ביטול היש לאין ועי\"ז נתגלה אין האמיתי הארת סוכ\"ע ולכן כתי' והיתה שבת הארץ לך ולבהמתך<sup data-n=\"4384\">116</sup> וארז\"ל כלה לחי' מן השדה<sup data-n=\"4385\">117</sup> כלה לבהמתך וכן אכילת אדם תלוי באכילת חי' ובהמה<sup data-n=\"4386\">118</sup>, וכ\"ז הוא מצד הארת סוכ\"ע המחי' לאדם ובהמה בהשוואה (משא\"כ מצד ממכ\"ע חיות האדם נבדל בערך מחיות הבהמה כי יש ד' חילוקי מדריגות דצח\"מ כו') וכן בשבת מצד הארת סוכ\"ע נצטוו ג\"כ על שביתת בהמה<sup data-n=\"4387\">119</sup> אע\"פ שאין בה דעת כלל לשבות אך מצד שהארת שבת הוא מבחי' אין",[["4375","107","<b>כי ששת ימים עשה הוי'</b>: תשא לא, יז. ראה זהר ויחי רמז, א. אמור צד, רע\"ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ. ראה גם לעיל ע' קכט. ע' רמג. לקמן מאמר ד\"ה את שבתותי תרי\"ב על יד הערה 19 ואילך."],["4376","108","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["4377","109","<b>ויכל אלקי'</b>: בראשית ב, ב."],["4378","110","<b>ויברך ויקדש</b>: בראשית שם, ג."],["4379","111","<b>הוא</b>: ניתוסף ע\"פ ב."],["4380","112","<b>דמאמר דבראשית</b>: ר\"ה לב, א."],["4381","113","<b>בחי'</b>: ב: ליתא."],["4382","114","<b>ויעש אלקים את הרקיע</b>: בראשית א, ז."],["4383","115","<b>העולמות</b>: ניתוסף ע\"פ ב."],["4384","116","<b>והיתה שבת הארץ לך ולבהמתך</b>: חיבור שני כתובים בהר כה, ו [ושם: והיתה שבת הארץ לכם לאכלה לך]. ז [ושם: ולבהמתך]."],["4385","117","<b>כלה לחי' מן השדה</b>: תענית ז, א. רש\"י ותו\"כ בהר שם, ז."],["4386","118","<b>אכילת אדם תלוי באכילת חי' ובהמה</b>: ראה רמב\"ם רפ\"ז מהל' שמיטה ויובל."],["4387","119","<b>בשבת. . שביתת בהמה</b>: יתרו כ, י."]]],[4801940542,"האמיתי שהוא למעלה מן הדעת ומאיר לאדם ובהמה בהשוואה כו' וד\"ל [רק<sup data-n=\"4388\">120</sup> ששבת הארץ דשביעית היא העלי' רק במל' דאצי' שהוא בחי' סובב לגבי בי\"ע אבל בשבת אפי' בחי' שבת תתאה הוא ג\"כ למעלה ממדריגת שביעית שהעלי' הוא בחכמה דאצי' ועלי' הב' דחכ' עצמה שנק' שבת עילאה הוא באין האמיתי סובב הכללי כו' וד\"ל]. וזהו את שבתותי תשמרו ששתי השבתות הנ\"ל א\"צ רק לשמור אותם שלא יפסידו אותם ע\"ד לא תחללו<sup data-n=\"4389\">121</sup> שלא לעשות חלל<sup data-n=\"4390\">122</sup> והפסק בינו לבין הא\"ס ע\"י מעשיו הרעים ח\"ו או ע\"י גיאות והתנשאות או בחי' לגרמי' ומזה צריך לשמור א\"ע שלא יהי' בבחי' יש ודבר וממילא יתגלה בנפשו הארת שתי שבתות הנ\"ל בו<sup data-n=\"4391\">123</sup> בדרך מתנה ממילא ומאילי' כמאמר מתנה טובה<sup data-n=\"4392\">124</sup> כו', ואפי' בחי' שבת תתאה שהוא בחי' ביטול היש אין הכוונה לעשות כמה הכנות בנפשו לבטל א\"ע כי כל הפעולות וההכנות יכול לפעול הרגשת הביטול שזהו היפוך ממש מביטול האמיתי כידוע בשם הה\"מ ז\"ל<sup data-n=\"4393\">125</sup> ע\"פ ופלגשו ושמה ראומ\"ה<sup data-n=\"4394\">126</sup> ראו שאני בטל, אך כל ההכנות יהי' באופן זה שישמור א\"ע בתכלית אפי' מבחי' פירוד כ\"ש דק תכלית הדקות ובזה יהי' כלי מוכן שישרה בנפשו בחי' ביטול היש וגם ביטול האמיתי לאין האמיתי והשראה זאת תבוא עליו מלמעלה כמאמר אלמלא הקב\"ה עוזרו<sup data-n=\"4395\">127</sup> כו' אבל עסק שלו לא יהי' רק בשמירה א\"ע בתכלית שלא יהי' נפרד כנ\"ל, וזהו את שבתותי תשמרו תשמרו בלבד וממילא יתגלה בנפשיכם שתי שבתות הנ\"ל כו' וד\"ל<sup data-n=\"4396\">128</sup>.\n<b>ומקדשי</b> תיראו הנה מקדשי קאי על התורה שהוא מקדשו של הקב\"ה [כי המקדש שלמטה שלמה בנה אותו<sup data-n=\"4397\">129</sup> כו'] וכמאמר אין לו להקב\"ה בעולמו<sup data-n=\"4398\">130</sup> אלא ד\"א של הלכה בלבד, והנה התורה שרשה בחכ' ונמשכה בבחי' ממלא בכל העולמות בכאו\"א לפי מדריגתו והעיקר הוא למטה בנש\"י שבגופים בכאו\"א לפי ערכו עד שנק' מזון כמאמר ותורתך בתוך מעי<sup data-n=\"4399\">131</sup> וא\"כ לכאורה מעלת התורה למטה ממעלת השבת שהוא בחי' גילוי האין האמיתי, לזה הזהיר דאע\"פ שתשמרו את שבתותי מ\"מ גם מזה אל תנח ידך להיות ואת מקדשי תיראו, כי הנה ידוע שאע\"פ דאוריית' מחכ\"ע נפקית<sup data-n=\"4400\">132</sup> היינו רק דרך מעביר בלבד אבל שרשה",[["4388","120","וד\"ל [רק: תוקן ע\"פ ב. ובבוך זה: וד\"ל] רק."],["4389","121","<b>לא תחללו</b>: אמור כב, לב [ושם: ולא — ראה תו\"ח תצוה ח\"ב שנז, ב. וש\"נ]."],["4390","122","<b>לא תחללו שלא לעשות חלל</b>: ראה גם לעיל ע' רכט ובהערה 86."],["4391","123","<b>בו</b>: ב: כי בא."],["4392","124","<b>מתנה טובה</b>: שבת י, ב."],["4393","125","<b>בשם הה\"מ ז\"ל</b>: כ\"ה גם לעיל ע' קכו. לקמן מאמר ד\"ה אם בחוקותי הא' על יד הערה 27. פלח הרמון תשא ע' שי. מאמרי אדה\"א דברים ח\"א ע' ח."],["4394","126","<b>ופלגשו ושמה ראומה</b>: וירא כב, כד. ראה הנסמן בלקו\"ת בהר כאן מג, א. מאמרי אדה\"א דברים ח\"ד ע' א'תצג. וש\"נ. שעה\"י קמא, א ובהערה 16."],["4395","127","<b>אלמלא הקב\"ה עוזרו</b>: קדושין ל, ב. סוכה נב, ב. ראה תניא רפי\"ג."],["4396","128","<b>וד\"ל</b>: ניתוסף ע\"פ ב."],["4397","129","<b>המקדש שלמטה שלמה בנה אותו</b>: מל\"א פ\"ו. ז, יג ואילך."],["4398","130","<b>אין לו להקב\"ה בעולמו </b>[ב: ליתא]: ראה ברכות ח, א. מאמרי אדה\"ז תקע\"א ע' צח. תורת חיים תרומה ח\"ב שיז, ב ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. הנחות תקע\"ז ע' ש. וש\"נ."],["4399","131","<b>ותורתך בתוך מעי</b>: תהלים מ, ט. ראה תניא פ\"ה."],["4400","132","<b>דאוריית' מחכ\"ע נפקית</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."]]],[4801940564,"למעלה מן החכ' [כמבו' במ\"א בענין<sup data-n=\"4401\">133</sup> וממדבר מתנה<sup data-n=\"4402\">134</sup> כו'] בבחי' סוכ\"ע אין האמיתי וא\"כ אדרבה בזה יתרון מעלתה שבאה ונמשכה בדרך או\"פ ממכ\"ע שבזה גורם בחי' תיראו בקירוב ממש כי ראי' אותיות יראה<sup data-n=\"4403\">135</sup> שהיראה מלפני המלך אינו אלא כאשר רואין אותו בקירוב ולא מרחוק<sup data-n=\"4404\">136</sup> ולכן ע\"י התורה נמשך בחי' אוא\"ס בקירוב ממש [יותר מבשבת שאינו אלא בבחי' מקיף בגילוי] בבחי' או\"פ, וזהו אני הוי' שבתו' מלובש מעצמות הוי' כו' וד\"ל.",[["4401","133","<b>בענין</b>: ב: ליתא."],["4402","134","<b>וממדבר מתנה</b>: חוקת כא, יח. ראה לקו\"ת שה\"ש כב, א. מאמרי אדה\"א נ\"ך ע' רסג ואילך."],["4403","135","<b>ראי' אותיות יראה</b>: ראה גם סידור שער הל\"ג בעומר שו, א. ש\"א מ, א ובהערה 16. תו\"ח בשלח ח\"א קנד, ג. אוה\"ת תהלים כרך ב ע' תתקס."],["4404","136","<b>שהיראה. . בקירוב ולא מרחוק</b>: ראה תו\"ח בשלח ח\"א קמט, ד. וש\"נ. אוה\"ת שם."]]],[4801940126,"<b>רישומי דברים מש\"א אדמו\"ר שליט\"א יום ש\"ק פ' נשא שנת ברי\"ת</b>\n<b>את</b> שבתותי תשמרו<sup data-n=\"4405\">1</sup> ומקדשי תיראו<sup data-n=\"4406\">2</sup> אני ה'. להבין מהו ענין את שבתותי ל' רבים כו' וגם להבין מהו שסמך מורה מקדש לשמירת השבת כו'. הנה ארז\"ל אלמלא שמרו ישראל שתי שבתות<sup data-n=\"4407\">3</sup> כהלכתן מיד נגאלין הנה ענין שתי שבתות הוא בחי' שבת עילאה ושבת תתאה<sup data-n=\"4408\">4</sup> כי שבת אותיו' תשב<sup data-n=\"4409\">5</sup> ויש בחי' תשובה עילאה ובחי' תשובה תתאה<sup data-n=\"4410\">6</sup>. וביאור הדברים הנה כתיב זכור את יום השבת לקדשו<sup data-n=\"4411\">7</sup> דמשמע מזה שישראל צריכין לקדש את השבת והלא ארז\"ל דמה שאו' מקדש ישראל והזמנים<sup data-n=\"4412\">8</sup> היינו משום דישראל מקדשינהו לזמנים<sup data-n=\"4413\">9</sup> משא\"כ שבת מיקדשא וקיימא<sup data-n=\"4414\">10</sup> לכן אנו אומרים מקדש השבת<sup data-n=\"4415\">11</sup> בלבד וא\"כ למה או' לקדשו.",[["4405","1","<b>את שבתותי תשמרו</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nלמאמר זה ראה אוה\"ת בהר כרך ד ע' א'קלז ואילך ובהנסמן שם.\nביאור על המאמר מר\"ה נדפס לאחר מאמר זה."],["4406","2","<b>את שבתותי תשמרו ומקדשי תיראו</b>: קדושים יט, ל. בהר כו, ב."],["4407","3","<b>אלמלא שמרו ישראל שתי שבתות</b>: ראה שבת קיח, ב. מאמרי אדה\"א בראשית ע' מז. שמות ח\"א ס\"ע קפט ואילך. הנחות תקע\"ז ע' קכג ובהנסמן בהנ\"ל. תו\"ח בשלח ח\"א רח, ד. וש\"נ."],["4408","4","<b>שבת עילאה ושבת תתאה</b>: זהר בהקדמה ה, ב. ראה גם לעיל ע' רמח ובהערה 62."],["4409","5","<b>שבת אותיו' תשב</b>: ראה אגה\"ת ספ\"י. מאמרי אדה\"א דברים ח\"ד ע' א'קפ. וש\"נ. לעיל שם ובהערה 63. לקמן פיסקא והנה עלי'."],["4410","6","<b>תשובה עילאה. . תתאה</b>: זהר רע\"מ נשא קכג, א."],["4411","7","<b>זכור את יום השבת לקדשו</b>: יתרו כ, ח. ראה גם תו\"א יתרו סט, ג ואילך (ובהנסמן בריש המאמר שם). תו\"ח יתרו ח\"ב רסד, א ואילך."],["4412","8","<b>דמה שאו' מקדש ישראל והזמנים</b>: נוסח ברכת היום דיו\"ט."],["4413","9","<b>דישראל מקדשינהו לזמנים</b>: ראה ברכות מט, א."],["4414","10","<b>שבת מיקדשא וקיימא</b>: ביצה יז, א."],["4415","11","<b>אנו אומרים מקדש השבת</b>: נוסח ברכת היום דשבת."]]],[4801940190,"<b>והנה</b> הרמב\"ן תי'<sup data-n=\"4416\">12</sup> דלקדשו הוא כמו שאמ' ביובל וקדשתם את שנת החמישים שנה<sup data-n=\"4417\">13</sup> אע\"פ שהוא מקודש מעצמו צריך ראש ב\"ד לאמר בתחלת השנה מקודש השנה<sup data-n=\"4418\">14</sup>, כן בשבת צריכים לקדש אותו בכניסתו והיינו על היין<sup data-n=\"4419\">15</sup> כו', אך אכתי קשה למה צריך לקדשו על היין כיון שהוא מעצמו מקודש כו'. אך הענין יובן בהקדם ענין השבת שנא' בו וביום השביעי שבת וינפש<sup data-n=\"4420\">16</sup> שזה\"ע המנוחה מן היגיעה<sup data-n=\"4421\">17</sup> ולכאורה איך שייך מנוחה למע' דבשלמא באדה\"ת שעושה בידיו וכוחו מוגבל שייך בו יגיעה שהוא אפיסת הכח מצד הגבלתו משא\"כ למע' במאמרו ברא הכל ועוד דכתי' לא ייעף ולא ייגע<sup data-n=\"4422\">18</sup> כו' כי כחו בלתי מוגבל ולא שייך בו אפיסה שהו\"ע היגיעה א\"כ מהו ענין המנוחה מן היגיעה כו'. אך הענין דזהו דוגמא בלבד להמנוחה שבאדה\"ת שכמו שבאדה\"ת כאשר בונה בנין או עושה כלי אזי כל כחות נפשו מלובשים בעסק המלאכה וכאשר גומר את מלאכתו אזי נפשטים כל כחות נפשו ועולים לעצמות נפשו, כך למע' ענין השביתה הוא בחי' העלי' מן הירידה כו'.\n<b>וביאור</b> ענין הירידה והעלי' שאחרי', הנה כתיב כי ששת ימים עשה ה' את השמים ואת הארץ, ומבואר בזהר<sup data-n=\"4423\">19</sup> דזהו בחי' המדות דאצי' שנק' ששת ימים דבהון עביד קוב\"ה שו\"א כו'. והנה גם בחי' המוחין דחו\"ב נמשכים במדות לצורך השתל' העולמות היינו למדוד איכות שפע המדות איך יומשך בכל עולם ובכל נברא בפרט הן לצורך התהוות היש שלו הן לצורך חיותו שהוא בחי' הביטול שלו וזהו בראשת ברא בחוכמתא ברא<sup data-n=\"4424\">20</sup> כו' כי כל בחי' מדה ושיעור להגביל ולצמצם צ\"ל ע\"פ קו המדה דחכ', אך בחי' המדות עם המוחין שבהם נמשכים מעצמות חו\"ב עילאין [... הנק' בכהאריז\"ל בשם או\"א עילאין<sup data-n=\"4425\">21</sup> כו'. ..] ע\"י צמצום שעצמות אור",[["4416","12","<b>הרמב\"ן תי'</b>: יתרו שם."],["4417","13","<b>וקדשתם את שנת החמישים שנה</b>: בהר כה, י."],["4418","14","<b>אע\"פ שהוא. . מקודש השנה</b>: ועד\"ז הוא לקמן ריש פיסקא והנה ביובל. ברמב\"ן: שהי' טעון קדוש בב\"ד לומר ביובל מקודש מקודש. וראה אוה\"ת בהר כרך ד כאן ע' א'קלז ובהנסמן בריש המאמר שם. סה\"מ עטר\"ת ע' תז ואילך. ש\"ת ע' 82 ואילך. אנציק' תלמודית חכ\"ב מערכת יובל ע' קלג ואילך־ ע' קמ ואילך ובהנסמן במקומות הנ\"ל."],["4419","15","<b>בשבת צריכים לקדש. . על היין</b>: ראה רמב\"ן שם. אוה\"ת־ סה\"מ עטר\"ת־ ש\"ת שבהערה שלפנ\"ז. תו\"ח בא ח\"א קכ, ג ובהערה 295."],["4420","16","<b>וביום השביעי שבת וינפש</b>: חיבור שני כתובים, בראשית ב, ג. תשא לא, יז [ראה גם לעיל ע' רמב. ס\"ע שנג. מאמרי אדה\"א ויקרא ח\"ב ע' תשסה. וש\"נ. תו\"ח בשלח ח\"א רט, ד הערה 12. סה\"מ תרכ\"ז ע' עד]."],["4421","17","<b>המנוחה מן היגיעה</b>: ראה גם לעיל ס\"ע רמב ואילך ובהערה 12."],["4422","18","<b>לא ייעף ולא ייגע</b>: ישעי' מ, כח. ראה גם תו\"ח בשלח ח\"א ריח, סע\"ד ואילך ובהערה 471. תצוה ח\"ב שכה, ד."],["4423","19","<b>כי ששת ימים עשה. . ומבואר בזהר</b>: תשא לא, יז. ראה זהר ויחי רמז, א. אמור צד, רע\"ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ."],["4424","20","<b>בראשית ברא בחוכמתא ברא</b>: בראשית א, א ובתרגום ירושלמי שם. כ\"ה בכ\"מ בדא\"ח ובתרגום שם: בחוכמא — סה\"מ מלוקט ג ע' קסד."],["4425","21","<b>או\"א עילאין</b>: ראה ע\"ח שער הזווגים שט\"ו, פ\"א (מ\"ב). פ\"ד. מבו\"ש ש\"ד ח\"ב פ\"ז. רמ\"ז לזהר אמור צט, א ד\"ה וכד אתער (פד, רע\"ב). לזהר קרח קעז, ב ד\"ה אבל כהני (קלט, ב). מאו\"א מערכת חוקקי אות נ\"ב. לעיל ע' קכג. ע' קכט. לקמן בהביאור פיסקא והנה ראשית. מאמר ד\"ה והתהלכתי תרט\"ו על יד הערה 101. פלח הרמון וארא ע' סב."]]],[4801940247,"המוחין מתעלמין כו' ורק הארה בעלמא מהם נמשכת דרך ירידה להתלבש במדות [... וכמו באדה\"ת שעצמות המוחין הוא להשכיל חכמות עמוקות ורמות שאינם שייכים לשום דבר רק כשצריך להשכיל איזה השכלה איך להתנהג במדותיו אזי נמשך מעצם השכל הארה בעלמא ע\"י צמצום, והארה זאת יורדת ומתלבשת במדות שבלב כו'. ..] וזהו כי ששת ימים עשה שבחי' שית יומין עילאין שהם המדות ע\"י המוחין שבתוכם הם בבחי' עשה היינו שהם בבחי' ירידה והשפלה מעצמות המוחין כנ\"ל. ועוד יתפרש בחי' עשה שהן באין ונמשכים בבחי' ירידה והשפלה למטה בבי\"ע, כי עצמו' המדות הגם שהם נמשכים ע\"י צמצום המוחין כנ\"ל ועי\"ז הם בבחי' מקור לנבראים מאין ליש וכמאמר כי אמרתי עולם חסד יבנה<sup data-n=\"4426\">22</sup> מ\"מ לא יתהווה מהם בחי' נברא בפועל נראה ליש רק כל הנבראים הם בבחי' ביטול במקורם שהוא עצמות המדות כביטול זיו השמש בשמש כמ\"ש בלק\"א ח\"ב<sup data-n=\"4427\">23</sup>, לכן צריך עוד צמצום שני בבחי' המדות דאצי' שירדו ונתלבשו במדת המלוכה ומדת המלוכה היא משפעת<sup data-n=\"4428\">24</sup> בריחוק מקום ובדילוג הערך כו' לכן מבחי' המלוכה דייקא יתהווה הנברא מאין ליש להיות נראה בבחי' יש ונמצא דעשה קאי על המדות היינו שהם באים בבחי' עשי' כנ\"ל וד\"ל.\n<b>אך</b> גם מבחי' המלוכה לא הי' מתהווה רק בחי' מקור היש בכלל אך כדי שיתהווה כל פרטי הנבראים בריבוי והתחלקות לזאת צריכה מדת המלוכה להתלבש בבחי' ג' מיני אותיו' אותיות המח' ואותיות הדבור ואותיות המעשה שזה\"ע לכבודי בראתיו יצרתיו אף עשיתיו<sup data-n=\"4429\">25</sup> כו', והן הן ג\"כ ל' כלים דמל'<sup data-n=\"4430\">26</sup>, יו\"ד כלים הפנימים נעשים נשמה לעולם הבריאה שזה\"ע אותיות המח' ויו\"ד כלים האמצעים נעשים נשמה לעולם היצי' שזהו בחי' אותיות הדבור ויו\"ד כלים החיצונים נעשים נשמה לעולם העשי' שזהו\"ע אותיות המעשה, וע\"י התלבשות מדת המלוכה בג' מיני אותיות אלו נמשך ריבוי התחלקות בכל הנבראים דג' עולמות דבי\"ע כו' וד\"ל. והתלבשות מדת המלוכה באותיות המחשבה דבריאה הוא ג\"כ ע\"י צמצום וכן אותיות המח' דבריאה באותיות המח'<sup data-n=\"4431\">*27</sup> דיצירה הוא ע\"י צמצום וכן מיצי' לעשי' הוא ע\"י צמצום כו', ונמצא שאור וחיות האלקי נמשך ע\"י רבוי צמצומים עד למטה מטה בעולם העשי', וכללות המשכות אור האלקי ע\"י צמצומים רבים הנ\"ל נק' בשם ירידה והשפלה. וכ\"ז הי' בוי\"ו ימי בראשית, אך לאחר גמר הבריאה נעשה בחי' עלי' כמשל המנוחה בנפש מן היגיעה שהוא עליות הכחות לגבי עצמות נפשו כ\"ה למעלה עליות אור האלקי והוא מה שנפשט מהלבושים שנתלבש בהם ע\"י צמצומים ועולה",[["4426","22","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה לעיל ע' קיג ובהערה 90."],["4427","23","<b>בלק\"א ח\"ב</b>: פ\"ג."],["4428","24","<b>ומדת המלוכה היא משפעת</b>: ראה לעיל ע' רמה ובהערה *36."],["4429","25","<b>לכבודי. . אף עשיתיו</b>: ישעי' מג, ז. ראה גם לעיל ע' קז. ע' קפג. תו\"ח בשלח ח\"א קמד, סע\"ב ואילך. וש\"נ."],["4430","26","<b>ל' כלים דמל'</b>: ראה ע\"ח שער השמות שער מ\"ד, פ\"א-ב. מאמר ד\"ה בשעה שהקדימו חה\"ש העת\"ר (קה\"ת תשנ\"ח) ע' 17. וש\"נ. לעיל ע' פב. ע' קנח. ע' שנט. לקמן מאמר ד\"ה והתהלכתי תרט\"ו על יד הערה 39."],["4431","*27","<b>המח'</b>: ב: הדיבור."]]],[4801940300,"להכלל במקורם נק' בשם מנוחה [אע\"פ שאין שייך שם יגיעה כו'] וזה\"ע שבת וכמאמרם באת שבת באת<sup data-n=\"4432\">27</sup> כו' שענין העלי' למע' אינו דומה לענין העלי' למטה שמתעלים כחות נפשו בלבד ואין נעשה שום שינוי בעצם דבר הנעשה כו' מצד שההתהוות הוא מיש ליש ונפרד דבר הנעשה ממנו, משא\"כ למע' כאשר עולה אור האלקי במקורו הוא פועל שינוי בגוף העולמות מצד שההתהוות הוא מאין ליש ומוכרח היש להיות בתכלית היחוד כ\"א יפרד יחזור לאין ואפס כו' שגם הם נפשטים מהצמצומים שלהם ומתרחבים לקבל האור אלקי כמ\"ש במקום יותר נעלה ממקומם הקדום [... רק שהעלי' בשבת דעכשיו הוא רק בפנימי' העולמות<sup data-n=\"4433\">28</sup> בלבד כו'. ..], וענין העלי' היינו שעולים אותיות המעשה והדיבור ונכללים באותיות המח' ונמצא שחיות העולמות בשבת הוא ממקום יותר נעלה מבימות החול כי בחול חיותם הוא מאותיות המעשה אבל בשבת מקבלים חיות מבחי' אותיות המח' [... רק שחיות זה דאותיות המח' אינו מאיר רק בפנימי' שלהם כנ\"ל. ..] כו'.\n<b>והנה</b> עלי' זאת הוא בבחי' ג' העולמות דבי\"ע שכולם מקבלים מבחי' אותיות המח' [... והגם שעולם הבריאה בלא\"ה מקבל מבחי' אותיות המח' אפי' בחול הנה במח' גופא יש חילוק שיש מח' השייך לדיבור והיינו מה שחושב איך לדבר ויש מח' בעצם היינו מה שחושב לעצמו כו' ובשבת עולים ג' העולמות לקבל מעצמו' המח' עליונה שלמעל' אפי' ממקור עולם הבריאה שאינו רק מח' השייך לדבור וא\"כ יש עלי' גם בעולם הבריאה כו' וד\"ל. ..] אך אח\"כ עולים כל העולמות דבי\"ע באצי' ע\"י עליות המל' דאצי' שעולה מברי' לאצי'. והנה עלי' שלהם פועל עלי' גם בעצמו' מקורם שהוא בחי' המדות דאצי' כנ\"ל שגם הם נפשטים מצמצומם שהם מקבלים מבחי' הבינה ע\"י צמצום כנ\"ל ועולים ומתרחבים לקבל אור עצמות הבינה דאצי' וזהו\"ע עלי' שלהם שהם עולים ונכללים בעצם הבינה, וזהו\"ע השבת אותיות תש\"ב היינו שכל הדברים שבים למקורם ושרשם היותר ראשון שהוא בחי' הבינה דאצי' שהוא מקור למדות שהם מקור העולמות כו', ועד\"ז הוא ענין היובל כי יובל הוא בבחי' בינה<sup data-n=\"4434\">29</sup> בבחי' פנימיותה שהוא שער החמישים דבינה<sup data-n=\"4435\">30</sup> ולכן הוא בשנת החמישים ולכן נק' יובל כי<sup data-n=\"4436\">31</sup> כמאמרם מה שמי' דההוא נהר יובל שמו<sup data-n=\"4437\">32</sup> ע\"ש שע\"י נמשך השפע מבחי' חכ' לבחי' בינה כו' ולכן בשנת היובל עולים כל העולמות למקורם ושרשם היותר ראשון שהוא בחי' הבינה וזהו בשנת היובל תשובו איש אל אחוזתו כו' וד\"ל.",[["4432","27","<b>באת שבת באת</b>: ראה רש\"י בראשית ב, ב. רש\"י מגילה ט, א ד\"ה ויכל. תוד\"ה חצבה סנהדרין לח, א. ב\"ר פ\"י, ט."],["4433","28","<b>שהעלי' בשבת. . בפנימי' העולמות</b>: ראה סידור שער המילה קמא, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תשסה. וש\"נ. מאמרי אדה\"א קונטרסים ע' תקלז. וש\"נ. תו\"ח ויקהל ח\"ב תלז, א. לעיל ס\"ע רמג."],["4434","29","<b>יובל. . בינה</b>: ראה זהר תצוה קפג, א. מאו\"א מערכת דרור אות יג. הנסמן במאמרי אדה\"א נ\"ך ע' שסד."],["4435","30","<b>יובל. . שהוא שער החמישים דבינה</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"י מערכת יובל. אוה\"ת בהר כרך ב ע' תרט. נצבים ע' א'רעג."],["4436","31","<b>כי</b>: ב: ליתא. וגם בכת\"י זה משמע שהיא מיותרת."],["4437","32","<b>מה שמי'. . יובל שמו</b>: ראה זהר יתרו פג, א. אחרי נח, א. וראה גם בכורות נה, ב. ויק\"ר ספכ\"ב."]]],[4801940350,"<b>והנה</b> ביובל נא' וקדשתם את שנת החמישים שנה והיינו שראש ב\"ד צ\"ל מקודש בתחלת השנה כנ\"ל<sup data-n=\"4438\">33</sup>, הענין הוא דכתיב ונהר יוצא מעדן<sup data-n=\"4439\">34</sup> להשקות את הגן, והנה בחי' עדן הוא בחי' התענוג המלובש בחכ\"ע<sup data-n=\"4440\">35</sup> דאצי' שהוא למעלה מבחי' התלבשות בבינה [... ונק' עדן תתאה כו' כי עדן עילאה הוא עצמות התענוג הפשוט שלמעלה מהתלבשות אפי' בחכ\"ע כמשי\"ת. ..] ונהר הוא בחי' שער החמישים שנק' יובל כנ\"ל ע\"ש שהוא מוביל השפע מבחי' החכ' לבינה<sup data-n=\"4441\">36</sup> כו' והוא משקה את הגן שהוא התגלות התענוג בחיצוני' בינה<sup data-n=\"4442\">37</sup> ומשם נמשך במדות ואח\"כ נמשך בבחי' המל'<sup data-n=\"4443\">38</sup> דאצי' שכל בחי' אלו נק' בשם גן עד למטה מאיר התענוג בג\"ע דברי' ובג\"ע דיצי' ועשי' הנק' געה\"ע וגעה\"ת<sup data-n=\"4444\">39</sup> כו'. והנה לזה צריך לקדש את שנת החמישים שנת היובל כי חזרת כל העולמות למקורם בחי' פנימי' בינה הוא מצד עצם השנה כנ\"ל אך אח\"כ צריך להמשיך בו הארת חכ\"ע בעצם שלמעלה הרבה מבחי' התלבשות החכ' בבינה, והמשכה זאת הוא ע\"י ראש ב\"ד שאומר מקודש כי בראש ב\"ד מאיר הארת חכ\"ע כי אתפשטותא דמשה<sup data-n=\"4445\">40</sup> שהוא בחי' חכ' כח מ\"ה<sup data-n=\"4446\">41</sup> מאיר בראש ב\"ד שבכל דור לזאת ביכולתו לומר מקודש להמשיך הארת חכ\"ע בבינה כו'. ועד\"ז יובן תירוץ הרמב\"ן בענין השבת שצריך לקדשו בכניסתו על היין כו' כי מה דשבת מיקדשא וקיימא היינו עליות כל העולמות לבחי' פנימי' בינה כנ\"ל ובחי' זאת נק' שבת תתאה בלבד אך אח\"כ צריכין ישראל לקדש אותו בכדי להמשיך בבחי' בינה הארת חכ\"ע בעצם עם התענוג המלובש בחכ\"ע, וממילא עולים כל העולמות בפנימי' חכ\"ע וזהו בחי' שבת עילאה שנמשך בשבת תתאה שזהו ע\"י ישראל דייקא מצד שרש כל נש\"י הם בבחי' חכ\"ע<sup data-n=\"4447\">*42</sup> כמ\"ש קדש ישראל להוי'<sup data-n=\"4448\">42</sup> כו' [... וע' בזהר פ' אמור דצ\"ד ע\"א אמרי ולאו דילך כו' אמר לון וכי לא קדש נינהו כו'. ..] לכן ביכולתם להמשיך בחי' חכ\"ע בבחי' בינה וזהו וקראת לשבת עונג<sup data-n=\"4449\">43</sup> להמשיך בשבת תתאה בחי' עונג המלובש בחכ\"ע הנק' עדן כנ\"ל. וזהו ע\"י הקידוש על היין כו' וד\"ל.\n<b>אך</b> הנה אמרז\"ל מחד בשבתא לשבתא<sup data-n=\"4450\">44</sup> כו' הענין הוא שצריך כל איש ישראל לעשות הכנה בימות החול להמשיך קדושת השבת במעשה ואז יוכל אח\"כ",[["4438","33","<b>כנ\"ל</b>: בריש פיסקא והנה הרמב\"ן."],["4439","34","<b>ונהר יוצא מעדן</b>: בראשית ב, י. ראה גם תו\"ח בשלח ח\"א קמא, א ובהערה 98. לעיל ע' קז. ס\"ע שעח."],["4440","35","<b>עדן. . התענוג המלובש בחכ\"ע</b>: ראה תו\"א מג\"א קכב, סע\"ב."],["4441","36","<b>ונהר. . שהוא מוביל השפע מבחי' החכ' לבינה</b>: ראה גם תו\"ח שמות ח\"א מ, א."],["4442","37","<b>הגן. . בינה</b>: ראה פרדס שער עה\"כ שכ\"ג, פ\"ג מערכת גן."],["4443","38","<b>הגן. . המל'</b>: ראה גם לעיל ע' קז ובהערה 30."],["4444","39","<b>בג\"ע דברי' ובג\"ע דיצי' ועשי' הנק' געה\"ע וגעה\"ת</b>: ראה תו\"א מקץ לב, ד. מאמרי אדה\"ז הנחות הר\"פ ע' קכג. מאמרי אדה\"א במדבר ח\"ג ע' א'רב ובהנסמן שם ס\"ע א'רעט ואילך. אוה\"ת שה\"ש כרך ג' ע' א'יז. פלח הרמון שה\"ש קכב, ב. לקמן ביאור מאמר ד\"ה וזכרתי הר\"ת על יד הערה 30."],["4445","40","<b>אתפשטותא דמשה</b>: ראה ת\"ז תס\"ט (קיב, רע\"א. קיד, רע\"א-ס\"א). תכ\"א (נ, ב). ב\"ר פנ\"ו, ז. מאמרי אדה\"א שמות ח\"ב ע' שצט."],["4446","41","<b>חכ' כח מ\"ה</b>: זהר רע\"מ צו כח, א. לד, א."],["4447","*42","<b>וזהו בחי'. . חכ\"ע</b>: ניתוסף ע\"פ ב."],["4448","42","<b>קדש ישראל להוי'</b>: ירמי' ב, ג."],["4449","43","<b>וקראת לשבת עונג</b>: ישעי' נח, יג."],["4450","44","<b>מחד בשבתא לשבתא</b>: ראה ביצה טז, א."]]],[4801940397,"להמשיך קדושת השבת בכניסתו בדיבור [... כי לכל המשכות צ\"ל עובדא ומילולא<sup data-n=\"4451\">45</sup> כמבו' בזהר ובפרע\"ח כו'. ..], וענין ההכנה הנעשה בחול הוא ע\"י תומ\"צ כו'. וביאור הדבר יש להק' ענין הקב\"ה מניח תפילין כו' ויש בזה ב' פי'<sup data-n=\"4452\">46</sup> ושניהם אמת הא' הוא שבחי' הקב\"ה הוא בחי' עצמות אא\"ס כפי' ההמון שקוראין הקב\"ה לפשוט בתכלית הפשיטות [... ולפ\"ז יתפרש קדוש הוא קדושת עצמותו שהוא מובדל מכל מיני גילוי, וברוך הוא מה שביכולתו לבוא לכל מיני גילוי, כי קדושתו הוא מובדל מכל מיני קדושות בזה שאע\"פ שהוא קדוש בתכלית אעפ\"כ הוא מקור כל מיני המשכה וכמאמר הזהר כמה קדישאין אית לעילא<sup data-n=\"4453\">47</sup> ובכולהו אין קדוש כהוי'<sup data-n=\"4454\">48</sup> כו', וכח זה שביכולתו לבוא לכל מיני גילוי הוא קדושת העצמו' ממש ואינו נבדל ממנו כלל לכן לא נא' קדוש וברוך כמבו' במ\"א והוא הוא בחי' הרצון הפשוט ירידת היכולת להיות מקור להשפעה כו' וד\"ל. ..] והוא מניח תפילין היינו שיורד ומתלבש בבחי' המוחין עליונים שנק' תפילין דמארי עלמא<sup data-n=\"4455\">49</sup> והמוחין הם ארבע בחי', בחי' חכ' ובחי' בינה ובחי' חו\"ג שבדעת שזהו\"ע ארבע פרשיות<sup data-n=\"4456\">50</sup>, וטעם מספר ארבע בכדי שעל ידם יאיר ויתגלה בד' עולמות דאבי\"ע בבחי' תוס' אורות יותר מכפי המדה שבתחלת ההשתל' כו' [... כי הנה ידוע שכל המשכות אא\"ס בכל עולם הוא ע\"י אמצעות החכ' דוקא כי אין אא\"ס שורה אלא בחכ'<sup data-n=\"4457\">51</sup> והנה מבחי' חכ' נמשכין כל ד' המוחין נמצא יש כח החכ' בכל ד' המוחין ועל ידי החכ' שבהם הוא מאיר בכל הד' עולמות, כי ע\"י החכ' בעצם הוא מאיר בכל עולם האצי' וע\"י החכ' הנמשך במוח הבינה הוא מאיר בעולם הברי' כי אימא עילאה מקננא בכורסייא<sup data-n=\"4458\">52</sup> כו' וע\"י החכ' המאיר בחסדים דדעת הוא מאיר בבחי' המדות דאצי' כי בנין הדכר מהחסדים<sup data-n=\"4459\">53</sup> כידוע והמדות מאירים בעולם היצי' כידוע דשית סיטרין מקננין ביצי'<sup data-n=\"4460\">54</sup> וע\"י החכ' המאיר בגבורות שבדעת הוא מאיר בבחי' המל' דאצי' כי בנין המל' מהגבורות<sup data-n=\"4461\">55</sup> ומל' דאצי' מאיר בעשי' כמאמר",[["4451","45","<b>לכל המשכות צ\"ל עובדא ומילולא</b>: ראה זהר וירא צט, ב. ק, א. ויחי רכ, רע\"ב."],["4452","46","<b>הקב\"ה מניח תפילין. . ב' פי'</b>: ברכות ו, א. ראה תו\"א מקץ לה, ב-ג. אוה\"ת בהר כאן כרך ג ע' תתקטז. כרך ד ע' א'קמב ואילך. סה\"מ תרכ\"ז ס\"ע קיא ואילך. וש\"נ. ע' תכב."],["4453","47","<b>כמה קדישאין אית לעילא</b>: ראה זהר תזריע מד, א."],["4454","48","<b>אין קדוש כהוי'</b>: שמו\"א ב, ב."],["4455","49","<b>תפילין דמארי עלמא</b>: ברכות שם. לקמן על יד הערה 62 ”דמרי\" — ראה מאמר ד\"ה את הוי' האמרת ח\"י אלול תש\"ל הערה 10 [קונט' ח\"י אלול תשמ\"ז — סה\"מ מלוקט ב ע' פז]."],["4456","50","<b>והמוחין הם ארבע. . ארבע פרשיות</b>: ראה זהר רע\"מ בא מג, ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'רמא."],["4457","51","<b>אא\"ס. . בחכ'</b>: ראה תניא פי\"ח (ובמ\"מ הגהות והע\"ק שם). פל\"ה בהגהה (ובמ\"מ הגהות והע\"ק שם). לקו\"ת במדבר יד, ב [ושם מציין: ”בע\"ח שער מ\"ז פ\"ג\" ולפנינו הוא פ\"ב ”ושער ב במה\"ב פ\"א פ\"ג\" ולפנינו הוא בשער סדר אצי' ש\"ג]. תו\"ח שמות ח\"א ז, ד הערה 333."],["4458","52","<b>אימא עילאה מקננא בכורסייא</b>: ת\"ז ת\"ו כג, א. ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["4459","53","<b>בנין הדכר מהחסדים</b>: ראה זהר תזריע מח, ב. נשא קמה, ב. ע\"ח שער מ\"ן ומ\"ד שט\"ל, דרוש י. ראה גם לעיל ע' ט."],["4460","54","<b>דשית סיטרין מקננין ביצי'</b>: ראה ת\"ז ת\"ו כג, א. ע\"ח שער סדר אבי\"ע שמ\"ז, פ\"ב. תניא פל\"ט ובמ\"מ הגהות והע\"ק שם. פנ\"ב. מאמרי אדה\"ז הקצרים ע' תקנב."],["4461","55","<b>בנין המל' מהגבורות</b>: ראה ע\"ח שער תיקון הנוקבא של\"ד, פ\"ה. מאמרי אדה\"א דברים ח\"א ע' ריח. וש\"נ. תו\"ח בשלח ח\"א רמד, א. וש\"נ. לעיל ע' רצא ואילך."]]],[4801940440,"אימא תתאה מקננא באופן<sup data-n=\"4462\">56</sup> כו' ונמצא שע\"י הד' מוחין מאיר מא\"ס בכל הד' עולמות דאבי\"ע כו' וד\"ל. ..].\n<b>פי'</b> הב' הוא שהקב\"ה הוא מקור ההשתל' שזה\"ע קדוש בוי\"ו<sup data-n=\"4463\">57</sup> שהוא בחי' ירידת קדושת הא\"ס להתלבש במדות דאצי' להיות מקור לעולמות משא\"כ עצמות קדושת הא\"ס נק' קדוש<sup data-n=\"4464\">58</sup> כו', ומה שנק' קדוש הוא מחמת שאע\"פ שהוא מקור עולמות הנבראים מאין ליש מ\"מ אינו מתלבש בתוכם בבחי' פנימי' רק מאיר עליהם בבחי' סובב ומקיף כו', ומה שמניח תפילין היינו מה שנמשך בו אורות עליונים מלמעלה מבחי' הזאת דמדות שה\"ע המשכת עצמו' המוחין דאו\"א שהם אורות הנמשכים מקדושת עצמו' הא\"ס שלמעלה ממקור העולמות ולכן פ' ראשונה דתפילין הוא קדש בלא וי\"ו שהוא המשכת קדושת העצמו', ולפ\"א הנחת תפילין שלו הוא ע\"ד אדה\"ת שהנחת התפילין שלו הוא מלמטה<sup data-n=\"4465\">*59</sup> הימנו כו' [... ובזה יתפרש ברוך הוא ל' נפעל שמתברך מבחי' המוחין דאו\"א והוא הוא בחי' ת\"ת דאימא הנעשה כתר לז\"א<sup data-n=\"4466\">59</sup> שע\"י נמשכו המוחין מאו\"א לז\"א כו' וד\"ל. ..] וכללות ענין ב' הפי' שניהם אמת ומורים על ענין אחד שהתפילין הם ממוצעים להמשיך קדושת עצמות אא\"ס [... הנק' הקב\"ה לפי פי' הא'. ..] בבחי' המדות מקור ההשתל' [... הנק' הקב\"ה לפי פי' הב'. ..] כו' וד\"ל. והנה כ\"ה עד\"ז בכל בחי' תומ\"צ בפרט ממשיכים קדושת עצמות אא\"ס להאיר בתוס' אור בבחי' המדות דאצי' [... והו\"ע תו' אור ועוד פועלים הכנה בבחי' המדות שיהיו כלים לאור הניתוסף וזהו ע\"י המצות וזהו נר המצוה<sup data-n=\"4467\">60</sup> כמשנ\"ת במאמר כפלח הרמון דלעיל כו'. ..]<sup data-n=\"4468\">61</sup>.\n<b>והנה</b> ארז\"ל תפילין דמרי<sup data-n=\"4469\">62</sup> עלמא מה כתיב בהו ומי כעמך ישראל גוי אחד בארץ<sup data-n=\"4470\">63</sup> והטעם לזה הוא מחמת שישראל הם הגורמים להמשיך קדושת עצמות אא\"ס להתלבש בבחי' תפילין שלמעלה וגם להמשיכם בבחי' המדות דאצי', והיינו ע\"י הנחת תפילין שלהם גורמים למעלה להיות הקב\"ה מניח תפילין [כב' הפי' הנ\"ל], וכח זה אינו רק לישראל בלבדם ולא לזולתם, וזהו מי כעמך ישראל גוי אחד בארץ<sup data-n=\"4471\">64</sup> שנבדלים בזה מכל העמים אשר על פני הארץ. ועוד יתפרש שהם ממשיכים בחי' אחד שהוא אחדות הפשוטה דעצמות אא\"ס [... שנק' אחד האמת. ..] שיתגלה בארץ מקור השתלשלו' עולמות הנבראים מאין ליש והיינו ע\"י",[["4462","56","<b>אימא תתאה מקננא באופן</b>: ראה ת\"ז ת\"ו (כג, א)."],["4463","57","<b>קדוש בוי\"ו</b>: ראה פלח הרמון בשלח ע' קנו. לקמן ביאור למאמר ד\"ה והתהלכתי תרי\"ב ובהערה 75. ד\"ה רפאיני הא' על יד הערה 59. לעיל ע' שנ. מאמרי אדה\"א הנחות תקע\"ז ע' רסג. וש\"נ. תו\"ח וארא ח\"א נח, ב. וש\"נ."],["4464","58","<b>קדוש</b>: ב: קדש."],["4465","*59","<b>מלמטה</b>: ב: מלמעלה."],["4466","59","<b>ת\"ת דאימא הנעשה כתר לז\"א</b>: ראה ע\"ח שער מוחין דצלם שכ\"ג, רפ\"ה ורפ\"ז. מאמרי אדה\"א דברים ח\"ג ע' תתעג. וש\"נ."],["4467","60","<b>תו' אור. . נר המצוה</b>: ע\"פ משלי ו, כג."],["4468","61","<b>במאמר כפלח הרמון דלעיל</b>: מליל ש\"ק פ' נשא — פלח הרמון שה\"ש ע' נג."],["4469","62","<b>דמרי</b>: ב: דמארי. ראה הערה 49."],["4470","63","<b>ומי כעמך ישראל גוי אחד בארץ</b>: דהי\"א יז, כא."],["4471","64","<b>ממשיכים בחי' אחד. . בארץ</b>: ראה גם לעיל ע' שעה ובהערה 68."]]],[4801940478,"שממשיכים בחי' מוחין עליונים במדות ע\"י הנחת תפילין בכלל [... וע\"י כל המצות בפרט. ..] עי\"ז מתגלה תוס' אורות הנ\"ל בבחי' המל' דאצי' וממילא נתגלה אחדות הפשוטה למטה בעולמות הנבראים מאין ליש. והנה כח זה בישראל הוא בירושה להם מבחי' יעקב אע\"ה כמשי\"ת כי הנה ביעקב כתי' ויקרא לו אל אלקי ישראל<sup data-n=\"4472\">65</sup>, ויש בזה ב' פי', הא' שיעקב ע\"ה קרא אל המזבח אל<sup data-n=\"4473\">66</sup> ע\"ש שבו ועל ידו נגלה אליו האלקים כו', והב' שהקב\"ה קראו ליעקב אל<sup data-n=\"4474\">67</sup>. וביאור הענין הנה עובדא זאת שאנו עושין ע\"י הנחת תפילין עשה זאת יעקב אע\"ה ע\"י המקלות<sup data-n=\"4475\">68</sup> שפיצל והמשיך בהם מחשוף הלבן בחי' גילוי לובן העליון ואח\"כ הציב אותם ברהטים בשקתות המים והיינו שהמשיך בחי' הלובן דעצמות אא\"ס בבחי' המוחין שנק' רהטים [... כמאמר<sup data-n=\"4476\">69</sup> מלך אסור ברהטים ברהיטי מוחא<sup data-n=\"4477\">70</sup>. ..] וממילא נמשכו אח\"כ מוחין אלו בבחי' המדות דאצי' כנ\"ל [... בשביל תולדות הנשמות כידוע דיחוד פנימי דאו\"א הוא ממשיך מוחין לזו\"נ<sup data-n=\"4478\">71</sup> ואח\"כ מתייחדי' בחי' זו\"נ בפנימיותם להוליד נשמות<sup data-n=\"4479\">72</sup> מאין ליש, וזהו צאן רבות<sup data-n=\"4480\">73</sup> אשר המשיך כו' כידוע. ..] והנה ארז\"ל יקר זה תפילין<sup data-n=\"4481\">74</sup> שעצמות המוחין נק' בשם יקר [... כי הם המוחין דאו\"א ומוחין אלו נמשכים מפנימיותם כמ\"ש נמשכים ממקורם והמקור והעיקר<sup data-n=\"4482\">76</sup> שלהם הוא הגרון דאריך<sup data-n=\"4483\">75</sup> שהוא מבחי' חצי התחתון שבכתר שהוא מקור לנאצלים<sup data-n=\"4484\">77</sup> וחצי הכתר בגי' יש<sup data-n=\"4485\">78</sup> ונחלק לחצאין להאיר בבחי' חו\"ב שזה בחי'<sup data-n=\"4486\">79</sup> קנה חכ' קנה בינה<sup data-n=\"4487\">80</sup>",[["4472","65","<b>ויקרא לו אל אלקי ישראל</b>: וישלח לג, כ."],["4473","66","<b>שיעקב ע\"ה קרא אל המזבח אל</b>: ראה אבן עזרא־ רש\"י־ רמב\"ן־ לקח טוב וישלח שם."],["4474","67","<b>שהקב\"ה קראו ליעקב אל</b>: מגילה יח, א. הובא ברש\"י ורמב\"ן וישלח שם. ראה גם לעיל ע' שעב. תו\"ח בשלח ח\"א רמו, ד ואילך. ויקהל ח\"ב שפט, ג ובהנסמן בהנ\"ל. אוה\"ת בהר כרך ד כאן ע' א'קמד ואילך. סה\"מ תרכ\"ז ס\"ע קיג ואילך. תרל\"ב ח\"א ע' לז ואילך ובהנסמן שם. תרל\"ג ח\"א ע' מח ואילך. וש\"נ. סה\"מ תרל\"ח ע' קצה."],["4475","68","<b>תפילין. . המקלות</b>: ויצא ל, לז-ח. ראה זהר ס\"ת ויצא קסב, א. מאמרי אדה\"ז תקס\"ב ח\"א ע' יב. תו\"ח בראשית מה, ד הערה 45."],["4476","69","<b>[כמאמר</b>: תוקן ע\"פ ב."],["4477","70","<b>מלך אסור ברהטים ברהיטי מוחא</b>: שה\"ש ו, ז. ת\"ז תקונא שתיאה קמד, ב. ראה גם מאמרי אדה\"א דברים ח\"א ע' לב. וש\"נ. פיה\"מ נח, א. אוה\"ת נצבים ר\"ע א'קצו."],["4478","71","<b>דאו\"א. . מוחין לזו\"ן</b>: ראה ע\"ח שער ז\"א שי\"ז, פ\"ב. שער מוחין דצלם שכ\"ג, פ\"ו. שער מ\"ן ומ\"ד של\"ט, דרוש ד. שער המלכים שי\"א, רפ\"ו. שער הכונות ענין הק\"ש דרוש ו. לקו\"ת להאריז\"ל פ' וירא עה\"פ והנה בן לשרה אשתך (קרוב לתחלתו). ד\"ה דרוש מהחבירים. לקו\"ת שה\"ש כ, א."],["4479","72","<b>זו\"נ. . נשמות</b>: ראה ע\"ח שער הכללים פי\"ג (מכת\"י מורי). שער הזווגים שט\"ו, פ\"א מ\"ק. שער מוחין דצלם שכ\"ג, פ\"ו. שער מ\"ן ומ\"ד של\"ט, דרוש ד. שער המלכים שי\"א, רפ\"ו. שער הכונות ענין הק\"ש דרוש ג. דרוש ו. לקו\"ת להאריז\"ל פ' וירא ד\"ה דרוש מהחבירים. לעיל ע' קמג ובהערה 23. אגה\"ק ס\"כ. לקו\"ת שה\"ש יט, ג."],["4480","73","<b>צאן רבות</b>: ויצא ל, מג. ראה גם תו\"ח וישלח קפ, ד ואילך. אוה\"ת ויצא ח\"א ע' 442 ואילך (ביאוה\"ז להצ\"צ כרך ב ע' תשג)."],["4481","74","<b>יקר זה תפילין</b>: ראה אסתר ח, טז. מגילה טז, ב."],["4482","76","<b>והעיקר</b>: תיבה זו אינה ברורה. ב: ליתא."],["4483","75","<b>המוחין דאו\"א. . הגרון דאריך</b>: ראה כללי הרח\"ו (בסוף ע\"ח) כלל יז. ע\"ח שער א\"א שי\"ג, פ\"ה. פ\"ח."],["4484","77","<b>דאריך. . חצי התחתון שבכתר. . לנאצלים</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א."],["4485","78","<b>וחצי הכתר בגי' יש</b>: ראה הקדמת הראב\"ד לס\"י (ד, א). שע\"ת יב, א. לעיל ע' קיח."],["4486","79","<b>חו\"ב שזה בחי'</b>: ניתוסף ע\"פ ב."],["4487","80","<b>קנה חכ' קנה בינה</b>: משלי ד, ה."]]],[4801940513,"וב\"פ קנה בגי' יקר<sup data-n=\"4488\">81</sup> כו', או יתפרש קנה בבחי' יסוד כמבואר במא\"א ערך קנה<sup data-n=\"4489\">82</sup> ויתפרש קנה קנה<sup data-n=\"4490\">83</sup> חכ' קנה בינה על היסודות דאו\"א הממשיכים המוחין כו'. ..]. והנה הארה בעלמא מבחי' המוחין נמשך למטה בבחי' המדות דאצי' [... הנק' גופא כו'. ..] ומהם נמשך בבחי' המל' דאצי' מקור נש\"י והארה הוא חלק עשירי ברוחני' וזהו בחי' א\"ל<sup data-n=\"4491\">84</sup> שהוא חלק עשירי ממספר יקר<sup data-n=\"4492\">85</sup>, וזהו אל הוי' ויאר לנו<sup data-n=\"4493\">86</sup> שההארה הנמשך לנו הוא ע\"י שם א\"ל, ולזה זכה יעקב אע\"ה להיות מרכבה לשם זה, ועי\"ז הי' בכחו להמשיך אחדות הפשוטה דעצמות אא\"ס למטה בבחי' המדות ובמל' דאצי', ולזה קרא הקב\"ה אותו א\"ל. והנה כח זה הוריש לבניו אחריו שהם כללות נש\"י כו' שגם הם ימשיכו אחה\"פ למטה ע\"י תומ\"צ שעושין כו' [... ולזה נק' בשם ישראל ישר אל<sup data-n=\"4494\">87</sup>. ..].\n<b>והנה</b> עם כל הנ\"ל יובן ענין ההכנה שנעשית בימות החול ע\"י הנחת התפילין ועסק התומ\"צ על בחי' שבת עילאה שיומשך בשבת תתאה כי מבואר למעלה שבחי' שבת עילאה הוא בחי' עצמות אור חכ\"ע שבו מאיר בחי' תענוג והעונג הוא בחי' גילוי דעצמות אא\"ס שלמעלה מהשתלשלות וכאשר נמשך בחי' זאת בשבת תתאה שהוא בחי' בינה ממילא נמשך תוס' אורות אלו גם בבחי' המדות דאצי' [... כי בחי' בינה נק' אם הבנים<sup data-n=\"4495\">88</sup> מקור המדות ושרשן כו'. ..]. והנה בחי' גילוי זה הם ממשיכין ג\"כ בימות החול ע\"י עסק התפילין בכלל וע\"י עסק תומ\"צ בפרט ואעפ\"כ אינה נקראת רק בשם הכנה בלבד מטעם שהמשכות אלו נמשכים בבחי' מקיף בלבד ולזה התפילין בולטין מבחוץ ואינם נכנסים לפנים מצד שלא נקלטו בבחי' או\"פ בבחי' הכלים דאצי' ולכן נק' המשכה זאת הכנה בלבד לבחי' השבת כי ע\"י ההמשכה בתחלה בבחי' מקיף נמשך אח\"כ ביום השבת בבחי' או\"פ [... וזהו ע\"י הדיבור דקידוש כנ\"ל. ..] כו', ולכן אין תפילין למעלה בשבת כי המקיפים נכנסו בפנים כו' וד\"ל. וכ\"ה עד\"ז באדה\"ת בנשמתו שהוא דוגמא שלמעלה יש ה' בחי' נר\"נ ח\"י<sup data-n=\"4496\">89</sup>, ובחי' נר\"נ הם מלובשים בכלים<sup data-n=\"4497\">90</sup> הוא דוגמת התלבשות אא\"ס למעלה בבחי'",[["4488","81","<b>וב\"פ קנה בגי' יקר</b>: ראה גם ביאוה\"ז תרומה — להצ\"צ — כרך ב ע' תתח."],["4489","82","<b>במא\"א ערך קנה</b>: במאו\"א ערך קנה — אות לו."],["4490","83","<b>קנה</b>: ב: ליתא."],["4491","84","<b>והארה. . א\"ל</b>: ראה אוה\"ת בהר כאן ע' א'קמד. סה\"מ תרכ\"ז ע' רסא. סה\"מ תרל\"ח ע' קצד."],["4492","85","<b>א\"ל שהוא חלק עשירי ממספר יקר</b>: ראה גם מאו\"א מערכת יקר אות כה. תו\"ח פקודי תמו, ד. לעיל מאמר ד\"ה כי תבואו וכו' ושבתה תר\"ט ובהערה 75."],["4493","86","<b>אל הוי' ויאר לנו</b>: תהלים קיח, כא. ראה אגה\"ק ס\"ז (קיב, א)."],["4494","87","<b>ישראל ישר אל</b>: [תוקן ע\"פ ב]. ראה פרדס שער עה\"כ שכ\"ג, פ\"י מערכת ישראל. תו\"ח בשלח ח\"א רמו, ב. וש\"נ."],["4495","88","<b>בינה נק' אם הבנים</b>: ראה זהר ויחי ריט, א. יתרו פד, א. פה, ב. פרדס שעה\"כ שכ\"ג, פ\"א מערכת אם הבנים. לקו\"ת שמ\"ע פח, ד. לעיל ע' רנא הערה 108."],["4496","89","<b>נר\"נ ח\"י</b>: ראה ב\"ר פי\"ד, ט. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תכח."],["4497","90","<b>נר\"נ הם מלובשים בכלים</b>: בסה\"מ תרל\"ח ע' תסב כותב: ”כ\"ה בזהר ובס\"י\" ראה בהערה שם — ראה אבן עזרא משפטים כג, כה. יסוד מורא — להנ\"ל — ש\"ז. ע\"ח שער אח\"פ ש\"ד, פ\"א. מאמרי אדה\"ז תקס\"ה שבהערה הבאה. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקיז־ בראשית ע' שסה־ קונטרסים ע' שכא־ אמ\"ב שער התפילין קכד, א."]]],[4801940543,"הכלים המלבישים את האור כו' ובחי' ח\"י שהם בבחי' מקיפים בלתי מלובשים בכלים<sup data-n=\"4498\">91</sup> הוא דוגמת עצמות אא\"ס שלמעלה מהתלבשות בבחי' הכלים דאצי' וזהו\"ע בצלמו בצלם אלקים<sup data-n=\"4499\">92</sup> כו'. והנה ע\"י התפילין שמניחים בימות החול ממשיכים בחי' ח\"י מהעלם אל הגילוי להאיר בנר\"נ אך הארה זאת נמשכת רק בבחי' מקיף בלבד ולזאת התפילין הם בבחי' בליטה ע\"ג הראש כו' אך בשבת מאירים המקיפים דחי' יחידה ונכנסים בבחי' קליטה בדרך או\"פ בנר\"נ ולכן אין מניחים תפילין בשבת<sup data-n=\"4500\">93</sup>, וזה\"ע נשמה יתירה<sup data-n=\"4501\">94</sup> הניתוספת בשבת שאין הכוונה דבר חדש לגמרי רק שהמקיפים הנ\"ל דחי' יחידה נתגלו ונמשכו בנר\"נ בבחי' או\"פ כו' וד\"ל.\n<b>והנה</b> כל הנ\"ל הוא שתי בחי' שבת שבת עילאה ושבת תתאה כו'. אך יש עוד בחי' שלישית בשבת הנק' שבת שבתון<sup data-n=\"4502\">95</sup>, והענין הוא כי שבת עילאה הוא בחי' התענוג שבחכ\"ע בעצם שלמעלה הרבה מבחי' התלבשות בבינה כו' וגם זה נק' עונג מורכב כו' אבל בחי' תענ\"פ הוא עצמות התענוג שלמעלה מבחי' התלבשות אפי' בבחי' חכ\"ע ונק' רעדכ\"ר<sup data-n=\"4503\">96</sup> כו' [... ובאמת הוא למעלה אפי' מבחי' התלבשות ברצון הנק' גולגלתא<sup data-n=\"4504\">98</sup> וזהו ג\"ר דע\"י ובשרשו לפני הצמצום הוא בחי' שעשועי המלך בעצמותו הנז' בס' עמ\"ה<sup data-n=\"4505\">99</sup> כו'. ..], המתגלה במצחא<sup data-n=\"4506\">97</sup> והוא מאיר במנחה דשבת<sup data-n=\"4507\">100</sup> ובסעודה שלישית<sup data-n=\"4508\">101</sup>, והנה על שבת עילאה נאמר לקדשו שממשיכין אותו ע\"י אתעדל\"ת דתומ\"צ דכל השבוע אבל בחי' זאת דשבת שבתון אינו מגיע שם בחי' אתעדל\"ת רק שמאיר מעצמו בבחי' מתנה<sup data-n=\"4509\">102</sup> ונק' מתנה טובה<sup data-n=\"4510\">103</sup> יש לי בבית גנזי כי בחי' תענוג הפשוט הוא גנוז בעצמות ונק' סדכ\"ס<sup data-n=\"4511\">104</sup> כו' [... ונמצא יש ג' בחי' בשבת הא' בחי' שבת תתאה הנ\"ל דמיקדשא וקיימא גם בלי אתעדל\"ת כנ\"ל, והב' שבת עילאה שנמשך ע\"י אתעדל\"ת דייקא דתומ\"צ כו' והג' שבת שבתון שנמשך ג\"כ ממילא ומאיליו בדרך מתנה רק שבאה אחרי הגילוי דשבת עילאה דייקא כי אין",[["4498","91","<b>ח\"י. . בלתי מלובשים בכלים</b>: ראה שעה\"י קכח, ב ובהערה 51. מאמרי אדה\"ז תקס\"ה ח\"ב ס\"ע תשטו ואילך. אוה\"ת בראשית כרך ו ע' תתרלא ואילך. מאמרי אדה\"א קונטרסים ע' רנג. וש\"נ."],["4499","92","<b>בצלמו בצלם אלקים</b>: בראשית א, כז."],["4500","93","<b>אין מניחים תפילין בשבת</b>: ראה שו\"ע אדה\"ז הל' תפילין רסל\"א. אוה\"ת בהר כאן ע' א'קמח. ר\"ה כרך ו ע' ב'תפט. וש\"נ. סה\"מ תרכ\"ז ע' עה."],["4501","94","<b>נשמה יתירה</b>: ביצה טז, א. ראה אוה\"ת בהר כאן. לעיל ע' רנ הערה 89."],["4502","95","<b>שבת שבתון</b>: ויקהל לה, ב. ראה גם בענין שבת שבתון לעיל ע' רסג ובהערה 108."],["4503","96","<b>ונק' רעדכ\"ר</b>: ראה זהר ספדצ\"נ תרומה קעו, ב. תו\"ח בראשית לו, ג הערה 23. תצוה ח\"ב שעו, ג."],["4504","98","<b>ברצון הנק' גולגלתא</b>: ראה לקו\"ת שלח מח, ב. ר\"ה נד, ב. תו\"ח בא ח\"א צ, א."],["4505","99","<b>שעשועי המלך בעצמותו הנז' בס' עמ\"ה</b>: ראה שם שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. קונטרסים ע' שמה ובהנסמן בהנ\"ל."],["4506","97","<b>רעדכ\"ר. . המתגלה במצחא</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א."],["4507","100","<b>והוא מאיר במנחה דשבת</b>: ראה זהר יתרו פח, ב. אד\"ר נשא קכט, א. אד\"ז האזינו רפח, ב. רצג, סע\"א."],["4508","101","<b>ובסעודה שלישית</b>: ראה גם לעיל ע' שנג."],["4509","102","<b>אינו מגיע שם בחי' אתעדל\"ת. . מתנה</b>: ראה לקו\"ת תזריע כב, א. במדבר ה, א. ואתחנן ב, ד."],["4510","103","<b>ונק' </b>[ב: וע\"ז נאמר]<b> מתנה טובה</b>: שבת י, ב."],["4511","104","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."]]],[4801940565,"נותנין המתנה רק למי שטרח<sup data-n=\"4512\">105</sup> באתעדל\"ת כי קוב\"ה לא שרי' רק באתר שלים<sup data-n=\"4513\">106</sup> ולכן מי שטרח והמשיך בחי' שבת עילאה בשבת תתאה הוא בחי' אתר שלים ממילא שורה בו בחי' שבת שבתון הנ\"ל רק שאינה באה ע\"י התעוררות כי אין התעוררות מגיע לשם כו' וד\"ל. ..], וזהו את שבתותי ל' רבים שיש כמה בחי' בשבת אחת שהו\"ע שלושה שבתות הנ\"ל ועל כולם באה האזהרה תשמרו שצריך לשמור אותם שלא לחללם והיינו שלא יעשה דבר המחלל את השבת<sup data-n=\"4514\">107</sup> ויסלק השראת אא\"ס ממנו והיינו כשמדבר שקר שנא' דובר שקרים לא יכון לנגד עיני<sup data-n=\"4515\">108</sup> או כשמתגאה שנא' עליו אין אני והוא יכולים לדור<sup data-n=\"4516\">109</sup> כו' שכל אלו גורמים סילוק אור השבת לכן צריך ליזהר מהם בתכלית וממילא יומשך אור השבת כי אור השבת אינו באה ע\"י עובדא רק ע\"י שמירה מן ההיפוך כו' וד\"ל.\n<b>ומקדשי</b> תיראו הנה מקדש הוא בשם אדני כמאמר מקדש אדני כוננו ידיך<sup data-n=\"4517\">110</sup> והוא בחי' אנת אשתמודע אדון על כולא<sup data-n=\"4518\">111</sup> והוא בחי' המשכת בחי' מל'<sup data-n=\"4519\">112</sup> דאצי' בבי\"ע ובחי' זאת נק' ג\"כ בשם מקדש<sup data-n=\"4520\">113</sup> [... כידוע דהיכל ק\"ק הוא מקום השראת השכינה<sup data-n=\"4521\">114</sup> שהוא בחי' מל'<sup data-n=\"4522\">115</sup> דאצי' וע\"י היכל הנ\"ל מתגלה בעולם הברי' וכן ביצי' ועשי' התגלות השכינה בעולם ההוא הוא ע\"י היכל ק\"ק שבעולם ההוא כו' וד\"ל. ..]. וכאן הוא מקום היראה [... כי להיות הנברא נראה ליש לזאת לא יוכל להדבק באה' כ\"א ע\"י ביטול מהותו שהוא בחי' יראה ונמצא שיש בנבראים אותם שמדריגתם בבחי' אה' כמו מחנה מיכאל מ\"מ גם האה' פנימיותה הוא בחי' ביטול היש שזהו בחי' יראה ונמצא כללות העבודה דנבראים הוא בחי' יראה בלבד כו' וד\"ל. ..] ולזה הזהיר שגם שתקיים את שבתותי תשמרו ותעלה במדריגות גבוהות דג' שבתות הנ\"ל שכולם הם בבחי' עונג כנ\"ל רק דשבת תתאה הוא עונג המלובש בבחי' בינה שמתגלה בכל העולמות אחרי תשובתם למקורם שהוא בחי' בינה ואח\"כ מתגלה העונג שבחכ' הנק' שבת עילאה ואח\"כ מתגלה תעה\"פ שנק' שבת שבתון וכ\"ז גורם בחי' האה' והדביקות ובעא\"ע ותעלה על דעתך שאינך צריך לבחי' היראה לזה",[["4512","105","<b>אין נותנין המתנה רק למי שטרח</b>: ראה מגילה כו, ב. גיטין נ, ב. ב\"מ טז, א. ב\"ב קנו, א."],["4513","106","<b>קוב\"ה לא שרי' רק באתר שלים</b>: ראה זהר ויחי רטז, ב. אמור צ, ב. לקו\"ת אמור לח, רע\"א ובהנסמן במ\"מ לשם."],["4514","107","<b>שלא יעשה דבר המחלל את השבת</b>: ראה גם אוה\"ת בהר כאן ס\"ע א'קנג ואילך. פלח הרמון יתרו ע' רמז."],["4515","108","<b>דובר שקרים לא יכון לנגד עיני</b>: תהלים קא, ז."],["4516","109","<b>אין אני והוא יכולים לדור</b>: סוטה ה, א. ערכין טו, ב."],["4517","110","<b>מקדש אדני כוננו ידיך</b>: בשלח טו, יז. ראה גם אוה\"ת בהר כאן ע' א'קנו. ש\"ש ע' א'תעה."],["4518","111","<b>אנת אשתמודע אדון על כולא</b>: ת\"ז בהק-דמה יז, רע\"ב. ראה גם לעיל ע' רמז ובהערה 56."],["4519","112","<b>בחי' מל'</b>: ראה זהר ויקרא יא, א. לעיל שם ובהערה 55."],["4520","113","<b>מל'. . מקדש</b>: ראה ע\"ח שער לידת המוחין שכ\"א, פ\"ב."],["4521","114","<b>דהיכל ק\"ק. . השראת השכינה</b>: ראה תניא פנ\"ב."],["4522","115","<b>השכינה. . מל'</b>: ראה זהר רע\"מ תצא רפא, ב. פרדס שער טעם האצילות ש\"ב, פ\"ב. שעה\"כ שכ\"ג, פכ\"א מערכת שכינה. לקוטי הש\"ס להאריז\"ל בחלק פי' מארז\"ל ע\"ד הסוד ד\"ה כ\"מ שנמצא השכינה (ב\"ב תשל\"ב ע' כג). תניא שם. אגה\"ק סכ\"ה (קלט, א). מאמרי אדה\"א הנחות תקע\"ז ע' כא. וש\"נ. לקמן מאמר ד\"ה אם בחוקותי הא' על יד הערה 76."]]],[4801940581,"הזהיר ומקדשי תיראו שאחר כל עליות המדריגות צריך אתה לעורר מדת היראה בנפשך כי היא העולה על כולנה אע\"פ שהיא סוף כל המדריגות שהוא מאצי' לבי\"ע כנ\"ל.\n<b>וביאור</b> טעם הדבר ילה\"ק מארז\"ל גדול מקדש שניתן בין שתי אותיות<sup data-n=\"4523\">116</sup> והיינו בין שתי שמות דהוי' ואדני וכמ\"ש מכון לשבתך כו' ה' מקדש אדני כוננו ידיך<sup data-n=\"4524\">117</sup> כו', ונמצא שהמקדש הוא המחבר בחי' הוי' ואדני<sup data-n=\"4525\">118</sup> כי אדני הוא בחי' יחו\"ת<sup data-n=\"4526\">119</sup> ד\"ת מאין ליש והוי' הוא בחי' ד\"ע<sup data-n=\"4527\">120</sup> יחו\"ע<sup data-n=\"4528\">121</sup> מיש לאין היינו שלמעלה הוא יש האמיתי וכולא קמי' כלא חשיב<sup data-n=\"4529\">122</sup> ושיהי' הביטול למטה כמו למעלה זהו יחוד שתי דעות הנ\"ל וזה נעשה ע\"י המקדש, והטעם כי על המקדש נא' מה נורא המקום הזה<sup data-n=\"4530\">123</sup> כו' ובחי' נורא שרשו בבחי' הקו\"ח ולכן נא' והנורא בתוס' וי\"ו<sup data-n=\"4531\">124</sup> כי הגדול הגבור הוא בחי' חו\"ג ששרשם בבחי' ראשית הקוין שהם בחי' חו\"ב משא\"כ נורא הוא בחי' מדת הת\"ת ששרשו בבחי' פנימי' הקו\"ח שלמעלה מהתחלקות ג' קוין לזה נא' והנורא בתוס' וי\"ו וידוע דהוי\"ו נק' אות אמת<sup data-n=\"4532\">125</sup> להיותו מושרש באמת העצמות [... וכידוע דבחי' פנימי' הקו הוא מאא\"ס שלפני הצמצום שהאור הוא כעין המאור שהוא בחי' אמתת העצמות שלמעלה מגילוי אור כו' וד\"ל. ..]<sup data-n=\"4533\">126</sup>. והנה בחי' נורא זה שורה במקדש כו' כנ\"ל לזאת ע\"י המקדש נתייחדו ב' הדיעות דהוי' ואדני להיותו בשרשו למעלה מהם שהוא בבחי' הקו\"ח כו'. וזהו ג\"כ הטעם דגדול העונה אמן<sup data-n=\"4534\">127</sup> יותר מן המברך כי מברך נק' המשפיע למקבל והמקבל הוא בחי' שם אדני והמשפיע הוא בחי' הוי' אבל העונה אמן הוא המייחד הוי' ואדני כי אמן בגימ' הוי' ואדני<sup data-n=\"4535\">128</sup> וכיון שהוא מייחדם ע\"כ לומר<sup data-n=\"4536\">129</sup> שהוא למעלה מהם כו'. ועי\"ז יובן מה שהזהיר ומקדשי תיראו כי היראה נמשכת מבחי' נורא השורה במקדש ה' ובחי' זאת שרשה בבחי' הקו\"ח ששרשו באמתת עצמות המאור שלמעלה מכל מיני גילוי אור דבחי' שבת הנ\"ל [... והיינו למעלה אפי' מבחי' שבת שבתון שהוא בחי' התגלות תעה\"פ שלמעלה מבחי' חכ' והיינו בחי' ג\"ר דע\"י שזהו מל' דא\"ק שהוא בחי' גילוי",[["4523","116","<b>גדול מקדש שניתן בין שתי אותיות</b>: סנהדרין צב, א. ברכות לג, א."],["4524","117","<b>מכון לשבתך. . ידיך</b>: בשלח טו, יז. בסנהדרין וברכות שם: פעלת ה' מקדש ה' (כוננו ידיך)."],["4525","118","<b>שהמקדש הוא המחבר בחי' הוי' ואדני</b>: ראה גם לקו\"ת נשא כא, ג. אוה\"ת בשלח ע' תקסד. ויקהל ר\"ע ב'ריא. במדבר ע' כה. עקב ע' תקיט."],["4526","119","<b>אדני. . יחו\"ת</b>: ראה שער היחוה\"א פ\"ז. לקו\"ת ש\"ש סד, ב. סה, ד."],["4527","120","<b>ד\"ת. . ד\"ע</b>: ראה גם לעיל ע' שיב ובהערה 229."],["4528","121","<b>והוי'. . יחו\"ע</b>: שהיחוה\"א פ\"ז."],["4529","122","<b>וכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. לעיל ע' רמט ובהערה 74."],["4530","123","<b>מה נורא המקום הזה</b>: ויצא כח, יז."],["4531","124","<b>והנורא בתוס' וי\"ו</b>: עקב י, יז. תפלת שמו\"ע. ראה מאמרי אדה\"ז תקס\"ז ע' כו ואילך. תו\"ח בראשית מא, ד ובהערה 50. בשלח ח\"א קנה, סע\"א ואילך."],["4532","125","<b>דהוי\"ו נק' אות אמת</b>: ראה זהר ויחי רמא, ב. ויקרא ב, א."],["4533","126","<b>וד\"ל]</b>: תוקן ע\"פ ב."],["4534","127","<b>דגדול העונה אמן</b>: ברכות נג, ב."],["4535","128","<b>אמן בגימ' הוי' ואדני</b>: ראה ת\"ז תי\"ט מ, א. תכ\"ו עא, ב. ספר המנהיג דיני תפלה קרוב לתחילתו (ירושלים תשל\"ח ר\"ע לב. וש\"נ). פע\"ח שער כוונת אמן שי\"א, פ\"א — פ\"ד. מאו\"א מערכת אמן אות צד."],["4536","129","<b>ע\"כ לומר</b>: תוקן ע\"פ ב."]]],[4801940592,"אור בלבד מבחי' רצון הקדום שנק' א\"ק ורצון קדום זה הוא בחי' בריאה מאין ליש לגבי בחי' הקו\"ח שהוא שרש בחי'<sup data-n=\"4537\">*130</sup> נורא השורה במקדש ה' ונמצא שהביטול דיראה שבמקדש הגם שהוא למטה מבחי' אה' הנמשכת מן התענוג כו' מ\"מ מגיע שרשה למעלה הרבה אפי' מבחי' מקור התענוג כו' ואפי' שרש התענוג דג\"ר דע\"י שמגיע שרשו למעלה מעלה לפני הצמצום בבחי' הנק' שעשועי המלך בעצמותו כנ\"ל מ\"מ עצמות השעשועים הוא בחי' גילוי אור העצמות רק שהוא גילוי עצמותו כמ\"ש לבדו ואינו בחי' מקור להשפעה עדיין כמבואר בכמה מקומות<sup data-n=\"4538\">130</sup> כו' אבל אמתות העצמות הוא מובדל לגמרי מבחי' גילוי אור אפי' מבחי' אור המאיר לעצמו ושרש הקו\"ח הוא באמתת העצמות וא\"כ ממילא היראה שבמקדש היא העולה על כולנה בבחי' ביטול לאמתת העצמות כו' וד\"ל. ..].",[["4537","*130","<b>בחי'</b>: ניתוסף ע\"פ ב."],["4538","130","<b>עצמות השעשועים. . ואינו בחי' מקור להשפעה. . כמבואר בכמה מקומות</b>: ראה גם לעיל ע' עו. ע' פה. ע' קנ. לקמן בהביאור על יד הערה 8."]]],[4801940127,"<b>ביאור על הנ\"ל מהר\"ה ז\"ל</b>\n[ועם כל הנ\"ל<sup data-n=\"4539\">1</sup> פירשתי סדר הקרבנות המבוארים בפ' פנחס<sup data-n=\"4540\">2</sup> שהתחיל בתמידים בכ\"י, ואח\"כ סידר המוספים ומתחילה סידר מוסף שבת ואח\"כ מוסף ר\"ח ואח\"כ מוספי' הרגלים כסדרן חה\"פ ואח\"כ חה\"ש ואח\"כ קודם חה\"ס סידר מוספי ר\"ה ויוהכ\"פ<sup data-n=\"4541\">3</sup> ואח\"כ מוספי ימי הסוכות וסיים במוסף שמ\"ע שהוא מש\"א ביום השמיני עצרת תהי' לכם<sup data-n=\"4542\">4</sup>, כי הנה י\"ל בתוס' ביאור ענין את שבתותי תשמרו ואעפ\"כ ומקדשי תיראו<sup data-n=\"4543\">5</sup> כו' כי הנה ידוע שעיקר פנימי' הכוונה ורצון הנעלם שבעצמות הי' להיות לו דירה בתחתונים<sup data-n=\"4544\">6</sup> והיינו שיתגלה מהו\"ע למטה בעולמות הנבראים מאין ליש דייקא והעיקר בעולם העשי' הגשמי כו' כמאמר וימלא כבוד ה' את כל הארץ<sup data-n=\"4545\">7</sup>, והנה רצון זה יש בו עונג נעלם ושניהם הם מהות אחד ממש ומיוחדים בעצמו' ממש [... וכמבואר בשער היחוד פ' כ\"ג דהרצון ותענוג הם בשרשם אחד כו' יעו\"ש. ..] ועונג ורצון זה פעלו התעוררות העצמות לבוא לידי גילוי אור ובתחלה נתגלה בחי' אור המאיר לעצמו שאינו עדיין בבחי' מקור להשתלשלו' ובחי' זאת נק' שעשועי המלך<sup data-n=\"4546\">8</sup>",[["4539","1","<b>[ועם כל הנ\"ל</b>: ביאור ר\"ה על מאמר ד\"ה את שבתותי תשמרו תרי\"ב שנדפס לפנ\"ז."],["4540","2","<b>בפ' פנחס</b>: כח, א ואילך."],["4541","3","<b>ואח\"כ. . מוספי ר\"ה ויוהכ\"פ</b>: שם כט, א ואילך."],["4542","4","<b>ביום השמיני עצרת תהי' לכם</b>: שם כט, לה."],["4543","5","<b>את שבתותי תשמרו. . ומקדשי תיראו</b>: קדושים יט, ל. בהר כו, ב."],["4544","6","<b>דירה בתחתונים</b>: ראה תניא רפל\"ו (ובהנסמן בליקוט פירושים לשם). ביאוה\"ז תזריע עב, ג. מאמרי אדה\"א הנחות תקע\"ז ע' שכט. שערי אורה צז, ב. לקמן מאמר ד\"ה אם בחוקותי הג' (קרוב לסופו) פיסקא אך הנה ידוע. סה\"מ תרל\"ח ע' לט הערה 138."],["4545","7","<b>וימלא כבוד ה' את כל הארץ</b>: שלח יד, כא."],["4546","8","<b>אור המאיר לעצמו. . שעשועי המלך</b>: ראה לעיל בסיום המאמר ובהערה 130."]]],[4801940191,"בעצמותו<sup data-n=\"4547\">9</sup> ואח\"כ נמשך מחמת זה הרצון להטיב ומח' דאנא אמלוך<sup data-n=\"4548\">10</sup> שזהו בחי' מקור להשפעה רק שהמקור הוא בבחי' א\"ס להיותו כל יכול להאציל עד אין שיעור כו' ובכאן הוא שם הא\"ס שזהו במל' דא\"ס כידוע בשם הרה\"מ נ\"ע<sup data-n=\"4549\">11</sup> וכח ומקור זה לא נתגלה עד אשר נתגלה מתחילה הבחי' הנק' שעשועי המלך בעצמותו ואח\"כ יכול להיות גילוי המקור להשתל' [וכידוע המשל ממה שאיתא מארז\"ל חזיי' דהוה קא בדח טובא וממילא אי הוי שאיל לי' כל חללי דעלמא הוי א' להו ]<sup data-n=\"4550\">12</sup> אך להיות מקור זה הוא בבחי' א\"ס לכן אם הי' נמשך ממנו הגילוי להדי' הי' ההשפעה ג\"כ בבחי' א\"ס ופנימי' הרצון הי' שיהי' העולמות במדה וגבול דייקא ובמספר קצוב ושיתגלה בהם בחי' א\"ס [שזה\"ע להיות לו דירה בתחתונים כנ\"ל] לזאת נמשך ההשפעה ע\"י צמצום והעלם העצמו' ולא נתגלה רק בחי' קו דק<sup data-n=\"4551\">13</sup> כמבואר בכהאריז\"ל.\n<b>והנה</b> ראשית האצי' מבחי' הקו הוא בחי' מחה\"ק דא\"ק<sup data-n=\"4552\">14</sup> הכוללת לכל ד' עולמות דאבי\"ע בהשוואה ואח\"כ נמשך מהעלם אל הגילוי בחי' הרצון להאציל ורצון זה נמשך ע\"י צמצום מח' הכללי' הנ\"ל ונעשה מקור לי\"ס דאצי' ואח\"כ נמשכו י\"ס דאצי' ע\"י צמצום מהעלם אל הגילוי וכן מאצי' לברי' כו' עד עולם העשי' שנמשך ע\"י צמצום היותר אחרון כו', והנה בכל המשכה פרטי' צריך להתעורר עונג הפשוט שבעצמות הנק' שעשועי המלך בעצמותו ולהאיר מחדש בכדי לפעול ההמשכה הנ\"ל ולכן כאשר נאצל בחי' א\"ק מבחי' הקו\"ח הי' ע\"י גילוי שעשועים הנ\"ל [וכמבואר בכהאריז\"ל שגם בבחי' א\"ק יש כדוגמת עתיק לעילא מגולגלתא דילי'<sup data-n=\"4553\">15</sup> ] וכן כאשר נאצל מקור האצי' שהוא הרצון להאציל מהעלם המח' הי' ע\"י גילוי שעשועים הנ\"ל שמתגלים בבחי' ג\"ר דע\"י כו' וכן גילוי הי\"ס דאצי' בפרט מהעלם הרצון הוא ג\"כ ע\"י גילוי שעשועי' הנ\"ל שמתגלי'<sup data-n=\"4554\">16</sup> באו\"א עילאין שהם כלים לגילוי שעשועים הנ\"ל ואח\"כ מתגלה בחי' הי\"ס דאצי' שהוא בחי' הנק' ז\"א שזהו מקור השתל' הנבראים מאין ליש, ומובן מכל הנ\"ל שכמו שבעצמות ממש יש שני בחי' הא' בחי' אור המאיר לעצמו שהוא בחי' שעשועי המלך בעצמו כנ\"ל ואור המאיר לזולתו שזהו בחי' הרצון להיטיב ומח' דאנא אמלוך שהם בחי' מקור להשפעה כן בכל מדריגה ומדריגה שבעולמות יש שני בחי' הנ\"ל אור המאיר לעצמו",[["4547","9","<b>שעשועי המלך בעצמותו</b>: ראה עמה\"מ שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. קונטרסים ע' שמה ובהנסמן בהנ\"ל."],["4548","10","<b>ומח' דאנא אמלוך</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' ז: וכמ\"ש בזהר בפי' וימלוך אנא אמלוך. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצד."],["4549","11","<b>שם הא\"ס שזהו במל'. . בשם הרה\"מ נ\"ע</b>: ראה גם לקמן מאמר ד\"ה אם בחוקותי הג' על יד הערה 105. פלח הרמון לך מד, סע\"א ואילך. מקץ קח, א. שמות ע' רסג. שה\"ש ע' 100. ע' 250. לעיל ס\"ע טו ובהערה 155."],["4550","12","<b>חזיי' דהוה קא בדח טובא. . אי הוי שאיל. ֿ. להו</b>: ראה שבת עז, ב. לעיל ע' עו ובהערות 13-14."],["4551","13","<b>ע\"י צמצום. . קו דק</b>: ראה ע\"ח דרוש עגו\"י ש\"א, ענף ב."],["4552","14","<b>מחה\"ק דא\"ק</b>: ראה תו\"א משפטים עח, ב. מאמרי אדה\"א דברים ח\"ג ס\"ע תתפז ואילך ובהנסמן שם ובע' תתפח."],["4553","15","<b>כדוגמת עתיק לעילא מגולגלתא דילי'</b>: ראה ע\"ח שער שביה\"כ ש\"ט, רפ\"ו. לקו\"ת מסעי צה, ב. המשך תער\"ב ח\"ג ע' א'שצז."],["4554","16","<b>בבחי' ג\"ר. . שמתגלי'</b>: ניתוסף ע\"פ ב."]]],[4801940248,"ואור המאיר לזולתו עד גם בי\"ס דאצי' שהם סוף מדריגת כל ההמשכות שבבחי' הא\"ס יש ג\"כ שני בחי' אלו שהם בחי' או\"א עילאין נק' בחי' אור המאיר לעצמו ובחי' ז\"א עם המוחין שלו וגם מקור המוחין דז\"א הנק' ישסו\"ת הכל נכלל בבחי' אור המאיר לזולתו [וכמו באדה\"ת יש שכל עצמי להשכיל השכלות עמוקות בעצם בלתי שייך להשכלות שום מדה ומה שמשכיל שכל במוחו איך להתנהג במדותיו שמזה נמשך אח\"כ מוחין להתלבש במדות שבלב, אך כ\"ז שהשכלה זאת היא במוח היא נבדלת עדיין מבחי' המדות רק שהוא מקור למוחין השייך למדות והוא דוגמא להבין למעלה ענין ישסו\"ת כו'].\n<b>והנה</b> ע\"י הקדמה זאת בסדר ההשתל' מרכד\"ר עד סוכד\"ר נוכל להבין ענין הנ\"ל דאת שבתותי תשמרו ומקדשי תיראו כי בשבת יש בחי' עליות שלושה וכולם בבחי' למעלה מהשתל' הא' העלי' בבחי' אימא עילאה והוא בחי' שבת תתאה, והב' העלי' בבחי' אבא עילאה והוא בחי' שבת עילאה, וכ\"ז הוא בחי' אור המאיר לעצמו שמאיר בשבת שהוא בחי' עצם השעשועים אך כמ\"ש לבוש בכלים דאו\"א עילאין כנ\"ל אך עלי' שלישית הוא גילוי עצם השעשועים שבעצמות אא\"ס ממש שאינו מתלבש עדיין בשום לבוש אפי' בבחי' הרצון הפשוט להשיג כו'. וזהו את שבתותי תשמרו, אך אח\"כ א' ומקדשי תיראו כי תכלית הכוונה הוא שיתגלה אור עצמות השעשועים למטה בעולמות הנבראים מאין ליש ובזה נשלם פנימי' הכוונה ורצון הנעלם וממילא נתוסף אור בעצמות השעשועים עצמו ע\"י גילוי העלם העצמות כו', וא\"כ הארתם למטה בבי\"ע הוא ביתר שאת מכפי שהיו מאירים במקורם כאשר לא נגלו עדיין למטה והגילוי שלהם למטה בבי\"ע לא יוכל להיות כ\"א ע\"י ביטול היש של הנברא בתכלית וזהו ומקדשי תיראו כו' שבחי' מקדש הוא בחי' שם אדני<sup data-n=\"4555\">17</sup> שהוא בחי' ביטול היש של כל הנבראים ע\"י גילוי מלכותו ית' ובזה שורה ומתגלה בחי' שעשועים העצמי' נמצא שאחר שמירת השבתות שהוא התגלות אור השעשועים העצמיי' הנ\"ל צריך להמשיכם למטה במל' דאצי' בכדי שיתגלו למטה בבחי' הנבראים מאין ליש ולזה הזהיר שאחר דאת שבתותי תשמרו שהוא העלי' הנ\"ל אח\"כ ומקדשי תיראו להמשיך גילוי הנ\"ל למטה בבי\"ע כו' וד\"ל.\n[ואפשר לומר שבחי' זאת הוא ג\"כ מאיר בשבת כי בליל שבת מאיר בחי' שבת תתאה הנ\"ל וביום השבת מאיר בחי' שבת עילאה ובסעודה שלישית מאיר בחי' עצמו' השעשועים שהוא בחי' שבת שבתון הנ\"ל אך מתעורר בחי' שבת דמעלי שבתא<sup data-n=\"4556\">18</sup> שהוא בחי' המל' דאצי' לקבל בחי' אור השעשועים הנ\"ל. והנה במל' דאצי' יש שני בחי' הא' כמ\"ש בבחי' אצי' שבחי' זאת מאיר בליל שבת, והב' בחי' מל' דאצי' שמתלבש בבי\"ע שבחי' זאת אינו עולה בשם מצד שבליל שבת היא עולה ונכללת בבחי' המל' דאצי' כמ\"ש בבחי' אצי' אך בסעודה שלישית שמתגלה בחי' שעשועים העצמי' שעיקר כוונה של גילוי זה הוא שיתגלה בבי\"ע לזאת אז בחי'",[["4555","17","<b>מקדש. . אדני</b>: ראה לעיל בהמאמר כאן ובהערה 110."],["4556","18","<b>שבת דמעלי שבתא</b>: זהר בהקדמה ה, ב."]]],[4801940301,"המל' דאצי' המתלבשת בבי\"ע מתגלית לקבל אור שעשועים הנ\"ל ומאיר בבי\"ע וממילא היא עולה בשם להשפיע ולהאיר בנבראים. ובזה יובן לפ\"ד עומק ל' הטייעא בפ' בראשית<sup data-n=\"4557\">19</sup> ד\"ה ע\"ב אשתאר שבת אחרא דלא אדכר ופשיטו<sup data-n=\"4558\">20</sup> שלא נזכר בכתו' אך במתק לשונו מרמז ענין הנ\"ל שהמל' המתלבשת בבי\"ע אינו עולה בשם להיותו נכלל בעצם המל' כמ\"ש בבחי' אצי' ולזה א' אח\"כ אנא מעטר לך בעטרא עילאה יתיר שהוא עצמות השעשועים שלמעלה מבחי' שבת עילאה ושבת תתאה שיתגלה בך דייקא וזהו אעבר כרוזא וא' ומקדשי תיראו כו' יעו\"ש וד\"ל. ..].\n<b>ובזה</b> יובן סדרי הקרבנות דהנה מבואר למעלה שבימות החול צריך להכין אור השבת והוא ע\"י תומ\"צ והנחת תפילין כמבו' לעיל באריכות, ונמצא שבחי' תומ\"צ העליונים ממשיכים אור השעשועים למטה אך המשכה זאת הוא בהעלם בבחי' מקיף לזאת התפילין בולטין ע\"ג הראש כנ\"ל, אך איך מעוררים תומ\"צ העליונים לבוא לידי גילוי הוא ע\"י תומ\"צ התחתונים מלמטה למעלה כמו עד\"ד כאשר האדם מניח תפילין הוא גורם שיהי' הקב\"ה מניח תפילין<sup data-n=\"4559\">21</sup> וכן כל הקורא ושונה<sup data-n=\"4560\">22</sup> כו' הקב\"ה קורא ושונה כו'. והנה עליות התומ\"צ הוא ע\"י הקרבנות דשני תמידין בכ\"י [ועכשיו ע\"י אהוי\"ר שבתפלה כמאמר אורייתא בלא דו\"ר לא פרחא לעילא<sup data-n=\"4561\">23</sup> וכן מצות בלא דו\"ר כו'] ועי\"ז מעוררים המשכת תומ\"צ העליונים לפעול גילוי השעשועים בהעלם בבחי' מקיף כנ\"ל אך בשבת מתגלי' מהעלם הלבושים שלהם ונמשכים בבחי' או\"פ בגילוי בתוך הכלים [ולזה אין מניחין תפילין בשבת<sup data-n=\"4562\">24</sup> כי נכנסו בפנימי כנ\"ל] ולזה הוא קרבן המוסף שענינו תוס' אור כי כאשר מאיר בגילוי אז מורה שהאור מאיר בתוס' וריבוי יותר הרבה מכפי שהוא מאיר בבחי' מקיף בלבד ולזה הקרבן הוא שני כבשים כנגד עצמות או\"א עלאין שמאיר בהם אור השעשועים כנ\"ל. אך הנה מבואר למעלה שעיקר הכוונה שיתגלה עצמות השעשועים למטה במל' דאצי' כמ\"ש מתלבשת בבי\"ע. והנה הגם שהמשכה זאת נעשית בשבת כנ\"ל בענין אעבר כרוזא ומקדשי כו' דקאי על המל' המתלבשת בבי\"ע שמאיר בהם במנחה מעצמות השעשועים ואז היא עולה בשם כו' מ\"מ בכללות השנה עיקר גילוי' הוא בשמע\"צ ולזה צריך להמשיך מתחלה אור השעשועים הנ\"ל מעצמו' פנימי' חו\"ב בבחי' חיצוני' חו\"ב מקור המדות שהוא בחי' ישסו\"ת כנ\"ל].\n<b>וזהו</b> הקרבן דר\"ח פרים שנים כנגד ב' מוחין חו\"ב ואיל אחד הוא כנגד הדעת שרש המדות וכבשים בני שנה שבעה כנגד ז' מדות כנ\"ל<sup data-n=\"4563\">25</sup>, אך המשכה זאת הוא בבחי' המדות כמ\"ש כלולים בשרשם בבחי' חו\"ב [וכמשל מדות שבשכל",[["4557","19","<b>בפ' בראשית</b>: זהר בהקדמה."],["4558","20","<b>ופשיטו</b>: אוצ\"ל: ופשיטא."],["4559","21","<b>הקב\"ה מניח תפילין</b>: ברכות ו, א. ראה גם תו\"א מקץ לה, ב. סה\"מ תרכ\"ז ע' מה. וש\"נ. ע' קיא. וש\"נ."],["4560","22","<b>כל הקורא ושונה</b>: ראה תדא\"ר רפי\"ח. מאמרי אדה\"א דברים ח\"ב ע' שפז. וש\"נ. תו\"ח וארא ח\"א נח, ג. וש\"נ."],["4561","23","<b>אורייתא בלא דו\"ר לא פרחא לעילא</b>: בתניא פל\"ט בתיקונים — ת\"ז ת\"י כה, ב."],["4562","24","<b>אין מניחין תפילין בשבת</b>: ראה שו\"ע אדה\"ז הל' תפילין רסל\"א. אוה\"ת בהר כאן ע' א'קמח. ר\"ה כרך ו ע' ב'תפט. וש\"נ. סה\"מ תרכ\"ז ע' עה."],["4563","25","<b>כנ\"ל</b>: כ\"ה בהכת\"י."]]],[4801940351,"שבאדה\"ת כו'], אך אח\"כ צריך להמשיך המשכה זאת בבחי' מדות דז\"א כו' וזה\"ע מוספי המועדים בפסח ההמשכה במדת החסד ובשבועות הוא ההמשכה בבחי' הגבו' כו' אך בסכות הוא ההמשכה במדת הת\"ת<sup data-n=\"4564\">26</sup> ולהמשכה זאת צריך לעורר מתחילה בחי' י\"ס שבפנימי' הכתר והוא ע\"י העומקי' דר\"ה ועשי\"ת ויו\"כ כו' [ולזה הזכיר מתחילה מוספי ר\"ה ויוה\"כ] ואח\"כ מתגלה בסוכות במדת הת\"ת כו' וד\"ל, ואח\"כ ההמשכה והקליטה במדת המל' המתלבשת בבי\"ע דייקא והוא בחי' ומקדשי תיראו בכללות השנה כו' וזהו במוסף דשמע\"צ כו' שהוא עצרת תהי' לכם שיוקלט אור הנ\"ל בתוך לב של כל או\"א מישראל כו' ולזה או' משיב הרוח ומוריד הגשם במוסף שמע\"צ<sup data-n=\"4565\">27</sup> שהו\"ע קליטת הטיפה שנק' בחי' גשמי' כו' ובזה יובן ג\"כ מה שהשבת נק' תחלה למקראי קדש<sup data-n=\"4566\">28</sup> וכש\"א בפ' אמור אלה מועדי ה'<sup data-n=\"4567\">29</sup> הזכיר אח\"כ ענין השבת תומ\"י קודם למועדים והיינו משום שתחלת גילוי אור השעשועים בבחי' פנימי' חו\"ב הוא בשבת ומחמת זה מתגלה ממילא בחיצוני' חו\"ב ומדות ע\"י המועדים [וכמו ההוא דהוי קא בדח טובא ממילא כו' כנ\"ל] ונמצא ששבת הוא מקור המועדים ולכן נק' תחלה למקראי קדש כו' וד\"ל. כל הנ\"ל כנלע\"ד בדא\"פ כו' וד\"ל<sup data-n=\"4568\">30</sup>.",[["4564","26","<b>בפסח. . החסד ובשבועות. . הגבו'. . בסכות. . הת\"ת</b>: ראה זהר רע\"מ פינחס רנז, ב. סידור שחרית לד, א. לז, סע\"א ואילך. תו\"ח בא צד, סע\"ב. וש\"נ."],["4565","27","<b>או' משיב הרוח. . במוסף שמע\"צ</b>: משנה ריש תענית. שו\"ע אדה\"ז הל' תפלה רסקי\"ד. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שנה ואילך."],["4566","28","<b>תחלה למקראי קדש</b>: נוסח הקידוש ליל שבת."],["4567","29","<b>בפ' אמור אלה מועדי ה'</b>: כג, ב."],["4568","30","<b>כו' וד\"ל</b>: ב: ליתא."]]],[4801940128,"<b>אם</b> בחוקותי<sup data-n=\"4569\">1</sup> תלכו<sup data-n=\"4570\">2</sup> כו'<sup data-n=\"4571\">3</sup> ואת מצותי תשמרו כו' ונתנה הארץ כו' ועץ השדה יתן פריו<sup data-n=\"4572\">4</sup>. ודרשו בילקוט<sup data-n=\"4573\">5</sup> והובא ברש\"י שתהיו עמלים בתו', והיינו כי הוקשה להם שא\"א לפרש בחוקתי על המצות כמו בכ\"מ דהא א' לקמן ואת מצותי תשמרו וע\"כ לפרש בחוקותי על התו'. אך יש להבין כוונת המקרא גופא למה אפקי' ללימוד התו' בלשון חוקותי דקאי תמיד על המצות. ועוד יש להבין כיון דקאי על לימוד התו' היא מצוה אחת ולמה אמר חוקתי לשון רבים. ועוד דלשון תלכו אינו שייך על לימוד התו' רק על ההילוך בדרכי הוי' בפו\"מ שזהו עשיית המצות כו'.",[["4569","1","<b>אם בחוקותי</b>: כנראה הנחת ר\"ה מדרוש כ\"ק אדמו\"ר הצ\"צ."],["4570","2","<b>אם בחוקותי תלכו</b>: בחוקותי כו, ג."],["4571","3","<b>כו'</b>: כ\"ה בהכת\"י."],["4572","4","<b>ונתנה הארץ. . פריו</b>: בחוקותי שם, ד."],["4573","5","<b>בילקוט</b>: כאן רמז תרעא בשם התו\"כ [ושם: שיהו ישראל עמלים בתורה]."]]],[4801940192,"<b>והנה</b> מתחילה י\"ל ענין מעהמ\"צ הנכלל במש\"א ואת מצותי תשמרו כי הנה רמ\"ח פיקודין הם רמ\"ח אברים דמלכא<sup data-n=\"4574\">6</sup> משמע מזה שמעהמ\"צ הוא בחי' עשיית הכלים לאורות ובמ\"א נאמר שכל המצות הם להוסיף אורות<sup data-n=\"4575\">7</sup> כו'. אך הנה מתחילה י\"ל ענין אורות וכלים, הנה ידוע דהאור הוא אא\"ס עצמו המאיר לעשות הכלים דחכים ומבין וא\"כ האור דחכ' או דבינה הוא בחי' גילוי בבחי' א\"ס כמו מקור כל האורות שהוא בחי' אא\"ס וא\"כ איך יתכן ממנו שפע פרטי'<sup data-n=\"4576\">8</sup> דחכ' או חסד בבי\"ע, אך היינו ע\"י הכלים המגבילים את האורות<sup data-n=\"4577\">9</sup> כמו הכלי דחכים מגביל את אורו שהוא פשוט להיות נמצא בבחי' מקור להמשיך שפע פרטי' דחכ' ולא שפע אחר וכן הכלי דמבין מגביל את האור וכן כל הכלים די\"ס דאצי', והנה אעפ\"י שהאור מוגבל להיות בחי' חכ' בלבד מ\"מ בחכ' גופא יכול להיות נמשך בריבוי אופנים שונים לאין שיעור לזאת נמשכו הכלים די\"ס דבי\"ע להגביל את האור שלא יהי' נמשך ממנו רק ג' אופני חכ' וברא ונוצר ונעשה הגם שבכל בחי' יש בחי' לאין שיעור מ\"מ כל ההתחדשו' בבחי' חכ' לאין שיעור הוא רק בבחי' ג' מדריגות הנ\"ל, וזהו\"ע הגבלת הכלים ועוד זאת שהכלים מעלימים את האור<sup data-n=\"4578\">10</sup> שלא יתגלה למקבלים הנבראים כמ\"ש ולכן כל מה שנמשך האור בריבוי כלים מכלים שונים יותר ויותר הוא מוסתר ונעלם עד שלמטה בעולם העשי' מסתתר ע\"י הכלים דעשי' בתכלית עד שנעשה נפרד לגמרי בבחי' יש עד שיכול להיות קליפה וסט\"א לומר לי יאורי<sup data-n=\"4579\">11</sup> כו' אך כ\"ז הוא בחי' ההשתלשלות [פועל ב' בחי' להגביל ע\"י פנימי' הכלים וע\"י פנימי' הכלים לא נעשה רק ההשתלשלות בחשבון ומספר ולא בבחי' מקום והיינו ענין רבבות בפנימי' הכתר הנק' עתיק ואלפים בכתר<sup data-n=\"4580\">12</sup> עד יחידות במל' וכ\"ז הוא בחי' השתלשלות מלמעלה מהשתלשלות הנק' חד ולא בחושבן<sup data-n=\"4581\">13</sup> וע\"י חיצוני' הכלים נעשה הסתר האור שמחמת זה נתהווה בחי' עולם בבחי' מקום וזמן<sup data-n=\"4582\">14</sup> נבדל ואז ההשתלשלות הוא בבחי' מקום רוחני עד מקום הגשמי כמבואר במ\"א וד\"ל]. אך בחי' מעשה המצות הוא תוס' אורות בכלים והיינו שע\"י עשיות הכלים של המצות עושה בחי' כלים למע' ונק' אברים דמלכא כמו כשמניח תפילין עושה למעלה כלים דחב\"ד להיות אא\"ס נמשך ומתלבש בהם וכן כשעושה צדקה עושה למעלה כלי החסד הנק' דרועא ימינא להיות האור מתלבש בו וידוע דתיקון הכלי הוא גורם תוס' אור במקור",[["4574","6","<b>רמ\"ח פיקודין הם רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["4575","7","<b>שכל המצות הם להוסיף אורות</b>: ראה פע\"ח בהקדמה. ע\"ח שער מ\"ן ומ\"ד של\"ט, דרוש יא כלל טז. מאמרי אדה\"א דברים ח\"ד ע' א'תסז. וש\"נ. תו\"ח בשלח ח\"א קנו, ב הערה 312."],["4576","8","<b>דהאור הוא אא\"ס. . שפע פרטי'</b>: ראה גם ביאוה\"ז בלק ק, ב."],["4577","9","<b>הכלים המגבילים את האורות</b>: ראה תו\"א בראשית ג, א. לקו\"ת אחרי כח, ג. ביאוה\"ז בשלח מ, א. בלק שם. מאמרי אדה\"ז תקס\"ב ח\"א ס\"ע קצה ואילך. תקס\"ט ס\"ע ריז ואילך."],["4578","10","<b>שהכלים מעלימים את האור</b>: ראה גם סה\"מ תרנ\"ז ע' מו ואילך. אעת\"ר ע' מ."],["4579","11","<b>לי יאורי</b>: יחזקאל כט, ג."],["4580","12","<b>רבבות. . עתיק ואלפים בכתר</b>: ראה לקו\"ת ברכה צג, ג. מאמרי אדה\"ז תקס\"ח ח\"א ע' תקכו. סה\"מ תרל\"ח ע' סד. וש\"נ."],["4581","13","<b>חד ולא בחושבן</b>: ת\"ז בהקדמה יז, א."],["4582","14","<b>עולם בבחי' מקום וזמן</b>: ראה שער היחוה\"א פ\"ז ובמ\"מ הגהות והע\"ק שם. לקו\"ת בהר מא, ב. ברכה צח, א. לקו\"ש בא כרך כו ע' 62."]]],[4801940249,"כמו כשמתקן כלי העין גורם תוס' אור בכח הראי' מבחי' עצמות הנפש ותוס' אור הנ\"ל הוא פועל בכח הראי' עצמה שמתגלה בכלי העין יותר כן למע' הגם שע\"י המצות אינם עושין רק תיקון הכלים לאורות מ\"מ תיקון זה מעורר תוס' אור מעצמו' אוא\"ס מקור כל האורות להיות נמשך באורות דאצי'<sup data-n=\"4583\">15</sup> בבחי' תוס' מרובה על העיקר ולכן פועל תוס' גילוי האורות בכלים באופן שהכלים אינם מגבילים ומעלימים את האור, ולכן נמשך ע\"י המצות תוס' אור בנשמה ג\"כ והיינו מפני שהנשמה שרשה מפנימי' הכלים<sup data-n=\"4584\">16</sup> שהם ראשית במעלה לקבל האור ולכן גם הנשמה היא ראשונה במעלה להיות מתקבל בה תוס' אור שע\"י המצות כו' וד\"ל [וזהו ענין הוי' לי בעוזרי שעוזרי נק' המצות<sup data-n=\"4585\">17</sup> להיותם מסייעים להמשכת גילוי האור מטעם הנ\"ל שתיקון הכלים גורם תוס' אור כמבואר במ\"א באריכות וד\"ל].\n<b>והנה</b> מצד תוס' אור עד שהכלים אינם מסתירים ומגבילים נעשה יחוד והתכללות האורות עד שמחמת זה שורה בהם מבחי' אוא\"ס עצמו מקור כל האורות [וזהו ענין שמחה של מצוה<sup data-n=\"4586\">18</sup> מצד עצם המצוה שהוא רצונו ית' שזהו ענין כללי בכל המצות ולא השמחה מצד היחוד עליון וההמשכה שמאיר ונמשך על ידה שאינה עיקרים<sup data-n=\"4587\">19</sup> רק העיקר הוא שמחה כללי' שבכל מעשה המצות כנ\"ל]. אך א\"כ הי' צ\"ל כל איש מישראל בעשותו מצוה ממצות ה' להיות מתפעל תיכף בעונג ושמחה מצד תוס' אור א\"ס המאיר בכלים והנשמה מקבלת משם, ואנו רואים שאינו כן ואדרבה ע\"פ רוב בזה\"ג נעשים המצות בקרירות כו', אך הטעם הוא להיות שיש בחי' רשע המכתיר את הצדיק<sup data-n=\"4588\">20</sup>, כי כל איש מישראל נק' בשם צדיק מצד נפשו האלקית כמאמר ועמך כולם צדיקים<sup data-n=\"4589\">21</sup>, אך להיות נה\"ט מכסה ומסתיר על קדושת נה\"א שמצד זה אינה מאירה בגוף [וכן מסתרת ברוחני' אפי' על ניצוץ האלקי שבנקודת פנימי' הלב שלא יאיר בנר\"ן כו'].\n<b>והנה</b> כנס\"י נק' שמחה<sup data-n=\"4590\">22</sup> כמבואר בזה\"ק על מאמ' כו' והיינו מפני שהיא בעצם מציאות שמחה ותענוג ממהו\"ע אא\"ס ועוד ניתוסף בה שמחה ועונג בעא\"ע מצד מעשה המצות כנ\"ל, אך כ\"ז הוא מוסתר ונעלם בנה\"ב וזהו\"ע אל גינת אגוז ירדתי<sup data-n=\"4591\">23</sup> שכנס\"י נק' אגוז<sup data-n=\"4592\">24</sup> המכוסה בד' קליפין<sup data-n=\"4593\">25</sup> כן הוא בחי'",[["4583","15","<b>תיקון זה מעורר.. באורות דאצי'</b>: ראה תו\"א מג\"א צז, א ואילך."],["4584","16","<b>שהנשמה שרשה מפנימי' הכלים</b>: ראה לעיל ע' רמח הערה 61."],["4585","17","<b>הוי' לי בעוזרי. . המצות</b>: תהלים קיח, ז. ראה מאמר ד\"ה זה משנת תקס\"ה בלקו\"ת שמ\"ע צ, א. מאמרי אדה\"ז תקס\"ד ע' רלג וע' רלו. מאמרי אדה\"א הנחות תקע\"ז ע' שסח. דברים ח\"ד ע' א'תקיט. לעיל ע' עה."],["4586","18","<b>שמחה של מצוה</b>: ראה גם לעיל ע' צז. לקמן מאמר ד\"ה רפאיני הא' על יד הערה 51. פלח הרמון בשלח ע' קל. מאמרי אדה\"א נ\"ך ע' רעז."],["4587","19","<b>עיקרים</b>: אוצ\"ל: עיקר."],["4588","20","<b>רשע המכתיר את הצדיק</b>: ע\"פ חבקוק א, ד. ראה גם לקמן מאמר ד\"ה אם בחוקותי תר\"י על יד הערה 50."],["4589","21","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["4590","22","<b>כנס\"י נק' שמחה</b>: ראה זהר ויקרא ח, ב. ז\"ח תשא מה, ב. וראה גם תו\"א וארא נח, ד. מאמרי אדה\"ז תקס\"ג ח\"א ע' קט."],["4591","23","<b>אל גינז אגוז ירדתי</b>: שה\"ש ו, יא."],["4592","24","<b>שכנ\"י נק' אגוז</b>: ראה שהש\"ר שם."],["4593","25","<b>אגוז המכוסה בד' קליפין</b>: ראה השמטות לזהר בראשית רסג, א. רע\"מ פינחס רכז, א ואילך. תצא רעט, א. סה\"מ תרל\"ח ע' קלז ובהערה 731."]]],[4801940302,"המל' [מוסתרת בד' מיני נוגה דאבי\"ע כי גם לעומת האצי' יש נוגה רק שהיא בבריאה כמבואר בכתבי האריז\"ל<sup data-n=\"4594\">26</sup>, ובנפש בחי' נוגה דאצי' הוא ראומה כמ\"ש בכתבי' בשם הרה\"מ נ\"ע<sup data-n=\"4595\">27</sup> כו' וד\"ל] היא מוסתרת בנוגה דאבי\"ע וכן בכאו\"א מישראל ניצוץ האלקי שבו מוסתר בד' מיני נוגה כו' וצריך לשבר הקליפה וממילא תתגלה הפרי והיינו להעביר בחי' ההסתר שיש בחומר נה\"ב [ולא העברת עצם חומר נה\"ב דא\"כ למה ירדה הנשמה בגוף ואדרבה ע\"י חומר נה\"ב תעלה הנשמה בעא\"ע כמו שית' לקמן בענין תלכו כו'] וכאשר מזדכך חומר הנה\"ב בתכלית אז ממילא תתגלה הפרי שהוא ענין השמחה בה' להיות חדות הוי' ממש היא מעוזו<sup data-n=\"4596\">28</sup> [שכ\"ז הוא מצד עצם ניצוץ האלקי עצמו הנק' שמחה כנ\"ל ומצד תוס' אורו' שמאירין בה ע\"י המצות כנ\"ל], וענין שבירת הקליפה המכסה ומסתיר הוא ג\"כ ע\"י תומ\"צ כי הנה ידוע שהתו' ממשיך או\"פ והמצות ממשיכים בחי' מקיפים<sup data-n=\"4597\">29</sup> וכל בחי' אורות אלו נמשכים גם בנה\"ט שע\"י נעשית עיקר המצוה מצד שנעשית בגשמי'. והנה כמו למע' בבחי' הכלים דאצי' אוה\"מ מזכך חצי הכלי מבחוץ<sup data-n=\"4598\">30</sup> ואוה\"פ מזכך חצי הכלי מבפנים עד שמחמת זה נעשה מזוכך בתכלי' לגלות האור כמ\"ש בלי הסתר כלל [ולכן נק' ספי' מלשון סיפור כמ\"ש במ\"א על מאמר וספרתם<sup data-n=\"4599\">31</sup> כו'] כן הוא בנה\"ט נזדכך חצי הכלי מבפנים ע\"י התו' וחצי הכלי מבחוץ ע\"י המצות [והו\"ע הרע שבגילוי והרע שבהעלם שנק' פנימי' הכלי וחיצוני' הכלי כו' וד\"ל] ואז מזדכך נה\"ט בתכלית עד שמאיר ע\"י בבחי' הגוף בחי' נפשו האלקי' כמ\"ש בפנימי' נקודת הלב בבחי' גילוי ממש ואז מאיר בחי' השמחה של מצוה מצד עצם המצוה כו' [ועיקר הגילוי הוא בבחי' מועדי' לשמחה והעיקר בבחי' חג הסוכות שמאיר בחי' המקיפים דשמחה ובשמע\"צ בבחי' פנימיות<sup data-n=\"4600\">32</sup> ואז נזדכך כלי הנה\"ט בתכלית ומאיר מעין לעתיד דכתי' כי בשמחה תצאו<sup data-n=\"4601\">33</sup> כו' וד\"ל] בנה\"ט וחומר הגוף וזהו\"ע שבירת הקליפה שגורם גילוי הפרי כו' וד\"ל, וזהו ענין כי הוי' אלקיך אש אוכלה<sup data-n=\"4602\">34</sup> שזהו מקיפים ופנימי' שנמשכים ע\"י תומ\"צ שנק' אלקיך שהוא בחי' אש המזכך נה\"ט כמו אש המעביר החלודה מבפנים ומבחוץ כו' וד\"ל. [וביאור הענין הנה המצות הם כלולים ממים ואש שהוא בחי' חו\"ג, ובחי' החסדים שבמצוה גורמים גילוי אור המאיר שהוא ענין תוס' אור למעלה שמזה נמשך תוס' שמחה בנה\"א כנ\"ל ובחי' הגבורה שבמצוה הוא בחי'",[["4594","26","<b>לעומת האצי' יש נוגה. . בבריאה כמבואר בכתבי האריז\"ל</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תנג וע' תעה. וש\"נ. הנחות תקע\"ז ע' קז. תו\"ח נח נא, א ובהערה 2. לקמן מאמר ד\"ה רפאיני תר\"ח על יד הערה 36."],["4595","27","<b>ראומה. . בשם הרה\"מ נ\"ע</b>: ראה גם לעיל מאמר ד\"ה את שבתותי תקצ\"ח ובהערות 125-126."],["4596","28","<b>חדות ה'. . היא מעוזו</b>: ע\"פ נחמי' ח, י."],["4597","29","<b>שהתו'. . או\"פ והמצות. . מקיפים</b>: ראה תניא פ\"ה. תו\"א יתרו סט, א. תצוה פג, ג. מאמרי אדה\"א ויקרא ס\"ע תקד ואילך."],["4598","30","<b>אוה\"מ מזכך חצי הכלי מבחוץ</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"ב. לעיל ע' רסג הערה 113."],["4599","31","<b>ספי' מלשון סיפור. . על </b>[כ\"ה בהכת\"י]<b> מאמר וספרתם</b>: ראה גם אוה\"ת ח\"ש קו, ב ואילך. סה\"מ תרל\"ח ע' סה."],["4600","32","<b>חג הסוכות. . המקיפים. . ובשמע\"צ בבחי' פנימיות</b>: ראה לקו\"ת שמ\"ע פט, א. אוה\"ת סוכות ס\"ע א'תשסב ואילך. אמור ע' קעח."],["4601","33","<b>כי בשמחה תצאו</b>: ישעי' נה, יב."],["4602","34","<b>כי הוי' אלקיך אש אוכלה</b>: ואתחנן ד, כד."]]],[4801940352,"הגבורות דאור שנעשה בחי' אש השורף ומכלה בחי' היש דנה\"ט כידוע בענין שני דברים שיש באור, הא' אור המאיר נק' נהורא חיוורא והב' אש השורף נק' נהורא אוכמא<sup data-n=\"4603\">35</sup> כו' וד\"ל]. וזהו ענין למען דעת כל עמי הארץ<sup data-n=\"4604\">36</sup> כי דעת הוא מל' שבירה<sup data-n=\"4605\">37</sup>, ויודע בהם את אנשי סוכות<sup data-n=\"4606\">38</sup> כו', ועמי הארץ הם ז' מדות<sup data-n=\"4607\">39</sup> דנה\"ט [שרשם נלקח מזמ\"ק<sup data-n=\"4608\">40</sup> מקור ע' אומות<sup data-n=\"4609\">41</sup> כו' וד\"ל] וכאשר נשבר רוח נה\"ט ע\"י תומ\"צ שהוא ענין העברת ההסתר עד שנשאר החומר מזוכך כנ\"ל אזי ממילא נתגלה בחי' כי הוי' הוא האלקי'<sup data-n=\"4610\">42</sup> דהיינו איך דהוי' והאלקי' כולא חד<sup data-n=\"4611\">43</sup> להיות שהכלים אינם מסתירים על האור כלל [והיינו להיות כי בשרש כל השרשים שרש האורות ושרש הכלים אחד הוא שהוא בבחי' עצמי' אא\"ס והיינו שמחמת שא\"ס להתפשטותו וכל יכול להאיר עד אין שיעור לזאת ביכולתו להגביל א\"ע נמצא ששרש הכלים הוא בחי' עצמות אא\"ס שהוא מקור האורות וא\"כ הוי' ואלקי' כולא חד כו' וד\"ל].\n<b>וזהו</b> ענין ג' פעמים הודו להוי'<sup data-n=\"4612\">44</sup> הוא ענין תוס' האורות עצמן ואח\"כ אמר הודו לאלקי האלקי'<sup data-n=\"4613\">45</sup> שזהו ענין המשכת תוס' האור בריבוי הכלים עד שלא יסתירו ונמצא שגם בשם אלקים יאיר שם הוי' בגילוי וידוע דיש ק\"כ צירופי אלקי'<sup data-n=\"4614\">46</sup> וע\"ב הראשונים הם בקדושה ומ\"ח צירופים האחרונים<sup data-n=\"4615\">47</sup> נמשך מהם חיות ויניקה לסט\"א, אך כאשר מאיר שם הוי' בשם אלקי' אז מאיר בכל הק\"כ צירופים עד שנבדל תוס' יניקת החיצוני' לגמרי, ובחי' זאת דהארת שם הוי' באלקי' נק' אלקי האלקי', וזהו ענין א' קורא וא' מתרגם<sup data-n=\"4616\">48</sup> שהי' בימי חכמי הגמרא כי הקריאה בלה\"ק הוא בחי' המשכת שם הוי' והתרגום הוא בחי' אחוריים<sup data-n=\"4617\">49</sup> ודין שהוא בחי' ק\"כ צירופים אלקי'",[["4603","35","<b>נהורא חיוורא. . נהורא אוכמא</b>: ראה זהר בראשית נא, א. ש\"א לד, ס\"ב ואילך."],["4604","36","<b>למען דעת כל עמי הארץ</b>: מ\"א ח, ס."],["4605","37","<b>דעת. . שבירה</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'תקיא. וש\"נ. אוה\"ת משפטים ס\"ע א'קה. שבועות ס\"ע פא. (חוקת תתמג). המשך תער\"ב ח\"א ע' תנח. הקדמת ד\"ח — לר\"ה — נדפס בלקו\"ב ווארשא תרכ\"ח מ, ד."],["4606","38","<b>ויודע בהם את אנשי סוכות</b>: שופטים ח, טז. ראה לקו\"ת שמ\"ע פח, ג. הנסמן בהערה שלפנ\"ז."],["4607","39","<b>ועמי הארץ הם ז' מדות</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' קצח. לעיל ע' רסג ובהערה 112."],["4608","40","<b>מזמ\"ק</b>: ראה וישלח לו, לא ואילך. זהר אד\"ר נשא קכח, א. קלה, א. ע\"ח שער הכללים פ\"א. שער דרושי נקודות ש\"ח, פ\"ד. שער שבה\"כ ש\"ט, פ\"א ואילך. לעיל ע' שמא הערה 43."],["4609","41","<b>מזמ\"ק מקור ע' אומות</b>: ראה גם תו\"ח נח עג, ג. תולדות קנג, ב. בשלח ח\"א רל, ד."],["4610","42","<b>כי הוי' הוא האלקי'</b>: המשך הכתוב למען דעת — מ\"א ח, ס."],["4611","43","<b>דהוי' והאלקי' כולא חד</b>: ראה גם לעיל ע' שעב ובהערה 35."],["4612","44","<b>הודו להוי'</b>: תהלים קלו, א."],["4613","45","<b>הודו לאלקי האלקי'</b>: תהלים שם, ב. ראה מאמרי אדה\"ז תקס\"ד ע' רלה. אוה\"ת שמ\"ע ע' א'תתכד. וראה גם ספר המצות להצ\"צ מצות מילה ע' 10 ואילך. לקו\"ת שמ\"ע פח, סע\"ג ואילך. לעיל ע' שעב."],["4614","46","<b>ק\"כ צירופי אלקי'</b>: ראה ע\"ח שער הזיווגים שט\"ו, פ\"ו. שער השמות שמ\"ד, פ\"ה. הנסמן במאמרי אדה\"א שמות ח\"א ע' קלז."],["4615","47","<b>ומ\"ח צירופים האחרונים</b>: ראה לעיל ע' רעא הערה 62."],["4616","48","<b>א' קורא וא' מתרגם</b>: ראה רמב\"ם הל' תפלה פי\"ב, ה\"י. טור או\"ח סקמ\"ה."],["4617","49","<b>והתרגום הוא בחי' אחוריים</b>: ראה טעהמ\"צ פ' ואתחנן ענין שמו\"ת. שעהמ\"צ שם. וראה גם אוה\"ת צפני' כרך ב ע' תתקד."]]],[4801940398,"וכשהי' מתרגם מה שקורא בלה\"ק הי' ממשיך שם הוי' בבחי' שם אלקי' כו' שנק' אלקי האלקי' כנ\"ל וד\"ל, ואח\"כ אמר הודו לאדוני האדונים<sup data-n=\"4618\">50</sup> שגם בע' שרים<sup data-n=\"4619\">51</sup> שנק' אדונים יאיר אדוני האדונים והיינו שגם המה יהיו נכנעים ובטלים לשם הוי' בתכלית כמו לעתיד דכתי' ובאו במערות צורים<sup data-n=\"4620\">52</sup> כו' מפני פחד הוי' כו'. וזהו ענין אם בחוקותי כו' מלשון חקיקה<sup data-n=\"4621\">53</sup> שיש ב' חקיקות<sup data-n=\"4622\">54</sup> הא' חקיקה מבפנים לעשות חלל ובית קיבול והב' חקיקה מבחוץ<sup data-n=\"4623\">55</sup> להעביר החלודה. והנה זהו\"ע התומ\"צ להמשיך או\"מ ופנימי' לזכך הנה\"ט מבפנים ומבחוץ. אך מה שכלל ב' החקיקות דתומ\"צ הנ\"ל בתו' במש\"א שתהי' עמלים בתו' יובן עפ\"י הידוע בענין תלמוד גדול שמביא לידי מעשה<sup data-n=\"4624\">56</sup> להיות שהמשכת המקיפים ע\"י המצות הוא לפ\"ע העסק שלו בתו' בבחי' ביטול כי לימוד התו' צ\"ל בבחי' ביטול<sup data-n=\"4625\">57</sup> עד שלא יהי' מהות כלל עד שאין הוא המדבר רק ה' הוא המדבר בפיו, וזהו בחי' משה ונחנו מ\"ה<sup data-n=\"4626\">58</sup>, ובחי' זאת פועל בחי' החקיקה הן החקיקה שע\"י התו' והן החקיקה שע\"י המצות ולכן נק' משה מחוקק<sup data-n=\"4627\">59</sup> כו' וד\"ל.\n<b>והנה</b> ע\"ז א' אם בחוקותי תלכו שאם ילמוד התו' בבחי' ביטול כנ\"ל אז יפעול ב' חקיקות שהוא ענין זיכוך הנה\"ט מבפנים ומבחוץ אז תלכו בבחי' מהלכים בין העומדים<sup data-n=\"4628\">60</sup> שהילוך זה הוא מצד בירור הנה\"ט דייקא כמבואר במ\"א וד\"ל [וביאור הדברים בדרך קצרה יובן עפ\"י מארז\"ל שלשה כתרים הם<sup data-n=\"4629\">61</sup> כתר תו' וכתר כהונה וכתר מל' וכתר ש\"ט עולה על גביהם כו' דהנה שלשה כתרים הם שלשה עטרות המבוארים במד\"ר<sup data-n=\"4630\">62</sup>, כי כתר כהונה הוא רצון<sup data-n=\"4631\">63</sup> הנשמה לעלות במס\"נ כידוע",[["4618","50","<b>הודו לאדוני האדונים</b>: תהלים קלו, ג."],["4619","51","<b>בע' שרים</b>: ראה זהר בראשית מו, סע\"ב. שע\"ת עד, א הערה 2."],["4620","52","<b>ובאו במערות צורים</b>: ישעי' ב, יט."],["4621","53","<b>אם בחוקותי. . חקיקה</b>: ראה לקו\"ת בחוקותי מה, א (ובהנסמן במ\"מ לשם). מאמרי אדה\"ז תקס\"ד ע' קז. תקס\"ו ע' קסו. מאמרי אדה\"א ויקרא ח\"ב ע' תשנד ואילך (ובהנסמן בריש המאמר שם). אוה\"ת בחוקותי (כרך ב) ס\"ע תרלח ואילך. (כרך ג) ע' תתקכא. סה\"מ תרכ\"ו ע' צט (ובהנסמן שם ע' )."],["4622","54","<b>בחוקותי. . ב' חקיקות</b>: ראה גם בענין ב' חקיקות מאמרי אדה\"ז תקס\"ו שם ואילך. מאמרי אדמו\"ר האמצעי שם ע' תשנה ואילך. אוה\"ת בחוקותי שם ע' תרלט ואילך. סה\"מ תרכ\"ו שבהערה שלפנ\"ז. עטר\"ת ע' תכז ואילך. מאמר ד\"ה אם בחוקותי תר\"י על יד הערה 44."],["4623","55","<b>חקיקה מבפנים. . מבחוץ</b>: ראה גם אוה\"ת בחוקותי שם. סה\"מ תרכ\"ו שבהערה 53. מאמר ד\"ה אם בחוקותי שם."],["4624","56","<b>תלמוד גדול שמביא לידי מעשה</b>: ראה קדושין מ, ב. ראה גם לקו\"ת ראה לג, סע\"א ואילך. לד, א. סידור שער האלול רכו, א ואילך. רכח, רע\"ג. סהמ\"צ להצ\"צ קמו, ב."],["4625","57","<b>לימוד התורה צ\"ל בבחי' ביטול</b>: ראה ברכות כב, א. תו\"א יתרו סז, ב. לקו\"ת מצורע כה, א. תו\"ח וארא ח\"א פ, ג ואילך. לעיל ע' קיז ובהערה 145."],["4626","58","<b>ונחנו מ\"ה</b>: בשלח טז, ז. ח. ראה גם לעיל ע' כד ובהערה 54."],["4627","59","<b>נק' משה מחוקק</b>: ברכה לג, כא. ראה מאמרי אדה\"א דברים ח\"א ס\"ע קצג ואילך. וש\"נ."],["4628","60","<b>מהלכים בין העומדים</b>: זכרי' ג, ז. ראה לקמן מאמר ד\"ה אם בחוקותי תר\"י ובהערה 43."],["4629","61","<b>שלשה כתרים הם</b>: אבות פ\"ד, מי\"ג."],["4630","62","<b>שלשה עטרות המבוארים במד\"ר</b>: ויק\"ר פכ\"ד, ח."],["4631","63","<b>כתר. . רצון</b>: ראה פרדס שער עצמות וכלים ש\"ד, פ\"ח. שער הצחצחות שי\"א, פ\"ה. פ\"ו. אגה\"ק סכ\"ט. מאמרי אדה\"א הנחות תקע\"ז ע' עב. וש\"נ."]]],[4801940441,"שהנשמה נק' בת כהן<sup data-n=\"4632\">64</sup>, ובחי' זאת ממשיך<sup data-n=\"4633\">65</sup> כתר לאו\"א ועי\"ז מתייחדים ג\"כ כידוע בענין יחוד ק\"ש, וכתר תו' הוא המשכה שאחר העלאה והוא מה שנעשה לו רצון לעשות המצות שעי\"ז ממשיך כתר לנוק' שנק' מל' מכ\"ע<sup data-n=\"4634\">66</sup>, והכתרים דזו\"נ נחשבים לב' כתרים<sup data-n=\"4635\">67</sup> משא\"כ באו\"א כתר א' לשניהם<sup data-n=\"4636\">68</sup> כו', ונמצא שע\"י מס\"נ ותומ\"צ ממשיכים ג' עטרות הנ\"ל. והנה יש עוד בחי' אחת הנכלל במס\"נ והו\"ע קבלת עומ\"ש כו' ולכן בק\"ש נאמ' למסו\"נ באחד<sup data-n=\"4637\">69</sup> ותמליכהו<sup data-n=\"4638\">70</sup>. ואפשר לומר שגם קבלת עומ\"ש ממשיך בחי' כתר לאו\"א ממקום גבוה יותר, והיינו שכאשר נמשך מח\"ס זהו ע\"י מס\"נ וכאשר נמשך מגולגלתא הוא ע\"י קבלת עומ\"ש שזה מבעהר\"צ<sup data-n=\"4639\">71</sup> לרצון שית' לקמן בענין הקדמת נעשה לנשמע כו'. אך כל הנ\"ל יכול להיות ג\"כ ברוחני' הנשמה האלקי' אפי' כמ\"ש בג\"ע שיוכל להיות התפעלות במס\"נ ליכלל וליבטל באוא\"ס ע\"ד דוגמא מג' תלמידי רשב\"י<sup data-n=\"4640\">72</sup> וביתר שאת כו' וכן לימוד התו' ועשיות המצות ברוחני' וע\"ד הלימוד בבהרת במתיבתא דרקיע<sup data-n=\"4641\">73</sup> וא\"כ למה ירדה הנשמה בגוף דייקא וגם התומ\"צ ירדו בעוה\"ז הגשמי, אלא שמחמת שהבירור המתברר מעולם העשי' הגשמי' ע\"י תומ\"צ ומעהמ\"צ ע\"י מס\"נ המתגלה בגוף הוא עולה למעלה מעלה מכל הכתרים הנ\"ל והיינו בכתר מל' דא\"ס להמשיך מבחי' העצם לבחי' השם דמל' דא\"ס הנק' שמו הגדול<sup data-n=\"4642\">74</sup> כמשי\"ת לקמן בענין וישמחו בך ישראל מקדשי שמך וזהו כתר ש\"ט שעולה דייקא ע\"י הבירורים על גביהם למעלה משלש עטרות הנ\"ל וזהו נק' הילוך דייקא להיות בחי' זאת הוא בחי' גילוי הא\"ס ממש משא\"כ ההמשכה אפי' מבעהר\"צ נק' עומדים לגבי ההמשכה הנ\"ל כו' וד\"ל].\n<b>ומעתה</b> יש להבין ענין ונתנה הארץ יבולה ועץ השדה יתן פריו, ומתחילה י\"ל ענין יחוד קוב\"ה ושכינתי'<sup data-n=\"4643\">75</sup> כי הנה בחי' שכינה הוא בחי' המל'<sup data-n=\"4644\">76</sup> דאצי' הנק' בשם שכינה ע\"ש ששוכן בתחתונים<sup data-n=\"4645\">77</sup> שהוא בחי' השראה בדבר נבדל דייקא",[["4632","64","<b>שהנשמה נק' בת כהן</b>: זהר סבא משפטים צה, א. אגה\"ק סי\"ב."],["4633","65","<b>ובחי' זאת ממשיך</b>: ראה לקו\"ת אמור לג, ג ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תרכז ואילך. וש\"נ."],["4634","66","<b>מל' מכ\"ע</b>: תהלים קמה, יג."],["4635","67","<b>והכתרים דזו\"נ נחשבים לב' כתרים</b>: ראה גם לקו\"ת שם לד, א ואילך. שה\"ש כ, ד. תו\"א תשא קיב, ב."],["4636","68","<b>באו\"א כתר א' לשניהם</b>: ראה ע\"ח שער הולדת או\"א וזו\"נ שט\"ז, פ\"א. פ\"ב. פ\"ו."],["4637","69","<b>למסו\"נ באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["4638","70","<b>ותמליכהו</b>: ראה זהר רע\"מ פינחס רכג, ב. עקב ערב, א. הנסמן במאמרי אדה\"א בראשית ע' לד."],["4639","71","<b>מבעהר\"צ</b>: ראה גם בענין בעל הרצון לעיל ע' סז ובהערה 10."],["4640","72","<b>מג' תלמידי רשב\"י</b>: זהר אד\"ר נשא קמד, א-ב."],["4641","73","<b>הלימוד בבהרת במתיבתא דרקיע</b>: ב\"מ פו, א."],["4642","74","<b>דמל' דא\"ס הנק' שמו הגדול</b>: ראה גם ש\"א ח, ב ובהערה 24. תו\"ח שמות ח\"א ה, ג. וש\"נ."],["4643","75","<b>יחוד קוב\"ה ושכינתי'</b>: ראה גם תו\"ח וארא ח\"א נא, ג."],["4644","76","<b>שכינה הוא בחי' המל'</b>: ראה זהר רע\"מ תצא רפא, ב. תניא פנ\"ב. אגה\"ק סכ\"ה (קלט, א). מאמרי אדה\"א הנחות תקע\"ז ע' כא. וש\"נ. לעיל מאמר ד\"ה את שבתותי תרי\"ב על יד הערה 115."],["4645","77","<b>שכינה ע\"ש ששוכן בתחתונים</b>: ראה פרדס שער עה\"כ שכ\"ג, פכ\"א מערכת שכינה. תניא פמ\"א (נז, ב) ובמ\"מ הגהות והע\"ק לשם."]]],[4801940479,"שנק' בלה\"ק משכן והוא ענין השראת כח האלקי דמל' דאצי' בעולמות הנבראים, ותחילת ההשראה הוא בהיכל ק\"ק דבריאה<sup data-n=\"4646\">78</sup> ומשם מתפשט למטה מטה כו' עד מל' דמל' דעשי' ומשם מתפשט החיות עד למטה בארץ הגשמי, וכל המשכה זאת הוא בא בחילוקי מדריגות בכל עולם לפי\"ע בבחי' מקיף ופנימי [שנק' בשם חיות ואור השפעה בגילוי שנק' אור פנימי ושפע בדרך השראה שנק' אור מקיף כו'] וע\"ד דוגמא משכן הנשמה במוח<sup data-n=\"4647\">79</sup> שמה שמחי' אבר המוח בגילוי נק' בשם פנימי ועצם החיות הוא בהעלם בבחי' השראה בדרך מקיף, אך המקיף הזה אינו רק מקיף לאבר המוח אבל לגבי אבר הלב הוא נבדל בערך ממנו עד שלא יתכן לקרותו גם בשם מקיף אליו כו', וכן מתפשט מן המוח אל הלב ע\"י צמצום ונמשך החיות בלב ג\"כ בבחי' מקיף ופנימי ומשם לאברי המעשה ע\"י צמצום וע\"ד דוגמא זאת למעלה ההמשכה מברי' ליצי' ומיצי' לעשי' כו', אך בחי' קוב\"ה הוא בחי' המדות דז\"א<sup data-n=\"4648\">80</sup> הנק' בשם סובב שהוא נמצא בכל העולמות דבי\"ע בהשוואה ממש בלי חילוקי מדריגות כלל בעשי' כמו בבריאה ובבריאה כמו בעשי' כו' שכמו שנמצא בבריאה כן ממש נמצא בעשי' וכמ\"ש בעשי' בהעלם ולא בגילוי כ\"ה ממש נמצא בבריאה בבחי' העלם ולא בבחי' גילוי, והטעם להיות שאין מקום העולמות דבי\"ע [שמבחי' המקום דכל עולם נמצא חילוקי המדריגות כידוע] תופס מקום כלל לגבי' להיות שהוא אמיתית המהווה של המקום ובלעדו לא נמצא שום מציאות מקום והיינו מצד כחו הנושא וסובל כל העולמות שזהו אמיתית קיומם והתהוותם מאין ליש והוא בחי' הסובבת ומקפת כל העולמות [כמבואר בלק\"א<sup data-n=\"4649\">81</sup> בענין הידיעה המקפת את כדור הארץ כו'] מזה נמצא מאין ליש מציאות המקום גשמי או רוחני הנושא וסובל את המתקיימם<sup data-n=\"4650\">82</sup> ומגבילו לפי ערכו כו' וזהו ענין מארז\"ל הוא מקומו של עולם<sup data-n=\"4651\">83</sup> כו' וכיון שהוא אמיתית מציאות המקום א\"כ המקום אין ואפס ממש לגבי ואפס בלעדו ולא יתכן לומר עליו שם שכינה שאינו נופל רק על השראה בדבר נבדל שאינו שייך רק כשהדבר נבדל תופס מקום קצת כו', ולכן נק' בשם קוב\"ה ע\"ש שהוא קדוש ומובדל מגדר מקום וזמן דנבראים, אך ענין יחוד קוב\"ה ושכינתי' הוא המשכת סובב בממלא בבחי' גילוי ממש ולא בהעלם כמ\"ש ע\"פ סדר ההשתלשלות כו', והוא כאשר יתגלה בבחי' היש של הנבראים בחי' הסובב ואעפי\"כ לא יתבטלו ממציאותם לגמרי רק יהי' בתכלית הביטול עד שלא יהי' נראים למציאות נפרד ולכן יהי' לע\"ל שיהי' הגילוי בשלימות וגר זאב עם כבש<sup data-n=\"4652\">84</sup> כו' לא ירעו<sup data-n=\"4653\">85</sup> כו' [וכמבואר במ\"א שהביטול לא יהי' בדרך הפשטת המהות כתלמיד לפני רבו רק ביטול טבעי כאברי הגוף לבחי' הנפש כו' וד\"ל].",[["4646","78","<b>ותחילת ההשראה הוא בהיכל ק\"ק דבריאה</b>: ראה תניא פנ\"ב."],["4647","79","<b>משכן הנשמה במוח</b>: ראה תניא פנ\"א. לעיל ע' קעב."],["4648","80","<b>קוב\"ה. . דז\"א</b>: ראה לקוטי הש\"ס להאריז\"ל ברכות ו, א (ה, א בדפי הספר). אוה\"ת בהר כרך ד ע' א'קמב [ושם נדפס: בזח\"ג ואתחנן דרס\"ו ע\"ב. וכנצ\"ל: דרס\"ב ע\"ב]. הנסמן בתו\"ח נח סט, א הערה 1."],["4649","81","<b>בלק\"א</b>: פמ\"ח."],["4650","82","<b>המתקיימם</b>: כ\"ה בהכת\"י."],["4651","83","<b>הוא מקומו של עולם</b>: ראה ב\"ר פס\"ח, ט. הנסמן בתו\"ח בראשית מג, א הערה 2. סה\"מ תרכ\"ט ע' קסט. וש\"נ."],["4652","84","<b>וגר זאב עם כבש</b>: ישעי' יא, ו."],["4653","85","<b>לא ירעו</b>: ישעי' יא, ט. סה, כה."]]],[4801940514,"<b>והנה</b> ענין יחוד קוב\"ה ושכינתי' הוא עד רוהמ\"ע שמה שלמטה הוא בחי' העלם שהוא קדוש ומובדל מגדר מקום אפי' מבחי' שפע בדרך השראה כנ\"ל לגבי מדריגה שלמע' ממנו הוא נחשב לבחי' גילוי וכמבואר בע\"ח [שער תיקון נוקבא ספ\"ב] בענין אתה הוא שהוא הוא בחי' בינה ואתה הוא בחי' חכ' ואיך יתכן שהחכ' יהי' נק' אתה בבחי' גילוי והבינה שהיא למטה במדריגה מהחכ' נקרא בשם הוא בחי' העלם, אך הענין דבחי' הוא בכ\"מ הוא בבחי' הכתר<sup data-n=\"4654\">86</sup> שאינו בא מבחי'<sup data-n=\"4655\">87</sup> ידיעת המהות ולכן נק' בשם הוא ע\"ש שנעלם ומוסתר מהותו אבל מ\"מ מציאותו נגלה כיון שאומרים עלי' הוא א\"כ ידוע איזה מציאות שיתכן לומר עלי' בחי' הוא וכמבואר בסידור בפי' ברוך הוא<sup data-n=\"4656\">88</sup> כו', ועד\"ז בבחי' הבינה לגבי ז\"א ידוע דמת\"ת דאימא נעשה כתר לז\"א<sup data-n=\"4657\">89</sup> וא\"כ הבינה נמשך בבחי' ז\"א בבחי' ידיעת המציאות ולא בבחי' ביטול ידיעת המהות ולכן נק' בשם הוא, והחסד דז\"א נק' בשם אתה לנוכח ע\"ש שבא בבחי' גילוי המהות [היינו באצי' עצמו אבל לגבי בי\"ע אינו בא בבחי' גילוי כלל ולכן המדות נק' קוב\"ה לגבי בי\"ע כנ\"ל], אבל בחי' החכ' לא יתכן לקרותו בשם הוא לגבי ז\"א להיות שאינו נמשך בו אפי' בבחי' ידיעת המציאות וכמו מבשרי אחזה<sup data-n=\"4658\">90</sup> שמבחי' השגה נולד המדות ולכן נק' בינה אם הבנים<sup data-n=\"4659\">91</sup> שמחה<sup data-n=\"4660\">92</sup> וממנה נמשך האור וחיות במדות בבחי' מקיף ופנימי משא\"כ בחי' החכ' הוא נבדל בערך מבחי' המדות כו' [ולכן נק' החכ' דאבא בשם קוב\"ה לגבי ז\"א ובחי' הבינה נק' בשם שכינה לגבי ז\"א שמאיר בו בבחי' פנימי' ובבחי' מקיף שהוא בחי' אור וחיות שפע בבחי' גילוי ושפע בבחי' השראה כנ\"ל בבחי' המל' לגבי בי\"ע, ונק' יחוד או\"א ג\"כ בשם יחוד קוב\"ה ושכינתי' במדריגה יותר גבוה כו'] אך אעפ\"כ נק' החכ' בשם אתה לגבי למע' מן החכ' שהוא בחי' מקור החכ' כמ\"ש כלולה בבחי' הכתר, שנק' ח\"ס או חכ' שבכתר כו' וכמו באדם ברק המבריק<sup data-n=\"4661\">93</sup> דעצם ההשכלה שנבדל בערך עדיין מבחי' השגה ע\"ד<sup data-n=\"4662\">94</sup> שנק' בשם אין לגבי ההשגה מ\"מ הוא בחי' יש לגבי כח המשכיל כו' וענין כח המשכיל עם כח העונג אחד הוא<sup data-n=\"4663\">95</sup> כידוע וא\"כ לפי\"ז בחי' החכ' דאא\"ב<sup data-n=\"4664\">96</sup> נק' אתה ע\"ש שמאיר באצי' בבחי' גילוי כידוע דחכ' הוא ראשית הגילוי<sup data-n=\"4665\">97</sup>, ובחי' הוא הוא בחי' הכתר בכלל [הכולל בתוכו תלת רישין<sup data-n=\"4666\">98</sup> שמלובש בהם ז\"ת דעתיק כידוע",[["4654","86","<b>הוא בבחי' הכתר</b>: ראה בנוסף לע\"ח המובא לעיל בפנים. שערי אורה — לר\"י גיקטלייא — שער י [ירושלים תש\"ך קא, ב]. פרדס שער עה\"כ שכ\"ג, פ\"ה מערכת הוא."],["4655","87","<b>מבחי'</b>: אוצ\"ל: בבחי'."],["4656","88","<b>בסידור בפי' ברוך הוא</b>: שחרית מ, ד."],["4657","89","<b>דמת\"ת דאימא נעשה כתר לז\"א</b>: ראה ע\"ח שער מוחין דצלם שכ\"ג, רפ\"ה ורפ\"ז. מאמרי אדה\"א דברים ח\"ג ע' תתעג. וש\"נ."],["4658","90","<b>מבשרי אחזה</b>: ע\"פ איוב יט, כו."],["4659","91","<b>בינה אם הבנים</b>: ראה זהר ויחי ריט, א. יתרו פד, א. פה, ב. פרדס שעה\"כ שכ\"ג, פ\"א מערכת אם הבנים. לקו\"ת שמ\"ע פח, ד. לעיל ע' רנא הערה 108."],["4660","92","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["4661","93","<b>ברק המבריק</b>: ראה גם בענין ברק המבריק לעיל ע' של ובהערה 54."],["4662","94","<b>ע\"ד</b>: כנצ\"ל: עד."],["4663","95","<b>כח המשכיל עם כח העונג אחד הוא</b>: ראה גם לעיל ע' רסו. לקמן מאמר ד\"ה והתהלכתי תרט\"ו על יד הערה 248. תו\"ח יתרו ח\"ב רסז, ג. וש\"נ."],["4664","96","<b>דאא\"ב</b>: דאור אבא."],["4665","97","<b>דחכ' הוא ראשית הגילוי</b>: ראה תניא פל\"ה בהגהה. תו\"ח ח\"ש קלט, ד ובהנסמן במ\"מ לשם."],["4666","98","<b>תלת רישין</b>: זהר אד\"ז האזינו רפח, א. ראה ש\"א נז, ב הערה 37."]]]]});
